<template>
  <div class="json-sub-editor-panel">
    <!-- 返回条：唯一新增 UI，复用现有 token，极简 -->
    <div class="sub-editor-header">
      <button class="back-btn" type="button" @click="onBack">
        <ArrowLeft :size="14" />
        <span>返回</span>
      </button>
      <span class="sub-editor-title me-mono">{{ title }}</span>
    </div>

    <!-- 配置链面包屑（层级 ≥2 时显示）：点任一层由编排层 popTo 直接回跳 -->
    <SubEditorBreadcrumb :items="crumbs ?? []" @jump="(index) => emit('jump', index)" />

    <!-- 内容区：场景 / Raw 由外部 activeTab 驱动（底部 LeftSidebar 切换），不自造 tab -->
    <div class="sub-editor-body">
      <!-- 场景视图：上下结构（上面第一层字段 key 列表 + 下面 value 编辑），对齐主编辑器 -->
      <div v-show="mode === 'scene'" class="sub-scene">
        <!-- 空配置：无字段时引导切 Raw 手动添加 -->
        <div v-if="rules.length === 0" class="sub-empty">
          <div class="sub-empty-title">空配置</div>
          <div class="sub-empty-hint">切到底部「Raw 模式」手动填写字段</div>
        </div>

        <template v-else>
          <!-- 上面：第一层字段 key 列表 -->
          <div class="sub-keys" :style="{ height: `${keyListHeight}px` }">
            <div class="sub-keys-header">
              <ListTree :size="13" class="sub-keys-icon" />
              <span>字段</span>
              <span class="sub-keys-count">{{ rules.length }}</span>
            </div>
            <div class="sub-keys-list">
              <button
                v-for="f in rules"
                :key="f.path"
                class="sub-key-item"
                :class="{ selected: f.path === selectedKey }"
                type="button"
                @click="selectedKey = f.path"
              >
                <span class="sub-key-label">{{ f.label }}</span>
                <span class="sub-key-path me-mono">{{ f.path }}</span>
              </button>
            </div>
          </div>

          <!-- 水平分隔条：拖拽调整 key 列表高度 -->
          <Splitter
            direction="horizontal"
            :model-value="keyListHeight"
            :min="100"
            :max="420"
            :default-value="180"
            @update:model-value="keyListHeight = $event"
          />

          <!-- 下面：编辑选中 key 的 value -->
          <div class="sub-property">
            <PropertyPanel
              :widget-id="selectedKey"
              :value="draft"
              :schema="subSchema"
              :value-base-dir="configDir"
              @change="onChange"
              @array-push="onArrayPush"
              @array-remove="onArrayRemove"
              @upload-resource="onUploadResource"
              @open-json-editor="onOpenJsonEditor"
            />
          </div>
        </template>
      </div>

      <RawModePanel v-show="mode === 'raw'" :value="draft" @apply="onRawApply" />
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, reactive, ref, watch, onBeforeUnmount, toRaw } from 'vue';
import { ArrowLeft, ListTree } from 'lucide-vue-next';
import PropertyPanel from './PropertyPanel.vue';
import SubEditorBreadcrumb from './SubEditorBreadcrumb.vue';
import RawModePanel from './RawModePanel.vue';
import Splitter from './Splitter.vue';
import type { FieldDef, WidgetSchema } from '../schema/types';
import { buildSubEditorRules } from '../schema/sub-editor-rules';
import { setByPath, getByPath, removeAtPath } from '../schema/path-utils';
import { isChunkedEntryField } from '../schema/sub-editor-node';
import * as FileBundle from '../schema/file-bundle';
import { getWorkspaceRoot, ensureReadWritePermission, writeFileToDirectory } from '../schema/assets-loader';
import { pushToast } from './Toast.vue';
import {
  activateGizmoMulti,
  collectTransformEntries,
  deactivateGizmo,
  setGizmoSourceContext,
  useGizmoBridge,
} from '../composables/useGizmoBridge';

const props = defineProps<{
  /**
   * 入口字段名（末段，如 configFile / chunkedUrl）。
   *
   * v1.11.0：由 `absPath`（meta 绝对路径）泛化而来 —— 多层下第二层以上的路径
   * （如 `regions[0].configFile`）不在 meta 里；而 schema 注册表本就按**字段名**匹配
   * （见 sub-editor-rules.resolveSchemaByEntry），故这里只需字段名。
   */
  entryFieldName: string;
  /** 子 json 在 FileBundle 中的 key（编辑即生效写回的目标路径） */
  cfgPath: string;
  /** 标题（字段名/文件名） */
  title: string;
  /** 初始 json 数据（plain object；空 {} 表示新建） */
  json: Record<string, unknown>;
  /** 当前显示视图，由外部 activeTab 驱动：scene → 结构化表单，raw → JSON 文本 */
  mode: 'scene' | 'raw';
  /** 类型骨架（JSON_EDITOR_SKELETONS 同构）：把数据中已删除但骨架仍声明的字段补回占位行 */
  skeleton?: Record<string, unknown>;
  /** 配置链面包屑（每层标题），下标即层级；长度 1 时不显示 */
  crumbs?: string[];
}>();

const emit = defineEmits<{
  /**
   * 点击「返回」：退出二级页，上层负责 runPendingConfigLoad 补读。
   * hasChanges 标记本次会话是否真的编辑过（用于上层决定是否标脏——否则打开后未编辑直接
   * 退出也会被标记为「有未保存修改」，顶部 dirty 橙点无端亮起）。
   */
  (e: 'close', hasChanges: boolean): void;
  /**
   * 防抖写回 FileBundle 后通知上层：config 内容已变（可能改了 baseUrl/collision_name/ply_name
   * 等资源引用字段），上层据此做「静默补读」——用缓存目录句柄试读新引用的资源，不弹框。
   * 仅由 watch 触发的写回 emit；onBack/onBeforeUnmount 的落盘不 emit（退出时走完整补读）。
   */
  (e: 'config-changed'): void;
  /**
   * 「下一层」入口（v1.10.0）：用户点击本层内某个指向 json 的字段的「编辑/新建 JSON」按钮。
   *
   * relPath 是**相对本 json 根的短路径**（如 `regions[0].configFile`）—— 本面板的
   * `subSchema.rootPath=''` 使 PropertyPanel.rendererBasePath=''，SchemaRenderer 的
   * `absPathOf(field.path)` 因此就是草稿相对路径。
   *
   * value 为该字段**当前值**（实时取自 draft）：上层需据此判断「编辑已有 json」
   * 还是「新建空白 json」，而栈节点上存的是 draft 初值、可能已过期。
   *
   * 本层只负责如实转发，不做路径解析——多层语义（父节点是谁、cfgPath 如何推导、
   * 是否成环）只有编排层（MetaEditor）掌握。
   */
  (e: 'open-json-editor', relPath: string, value: unknown): void;
  /**
   * 面包屑回跳（v1.11.0）：请求编排层 popTo(index) 直接回到第 index 层
   * （被弹出的各层由编排层统一标脏 + 补读）。
   */
  (e: 'jump', index: number): void;
}>();

/**
 * 子 json 的编辑副本（reactive）。
 *
 * 编辑即生效：任何字段变更经 300ms 防抖后序列化写回 FileBundle（register 覆盖同 key），
 * contentVersion++ 触发 PreviewPanel 重建。组件按 cfgPath 作为 key 重新挂载（MetaEditor
 * 侧），故此处无需 watch(props.json) 重新灌入，draft 在 setup 一次性初始化即可。
 */
const draft = reactive<Record<string, unknown>>(structuredClone(toRaw(props.json ?? {})) as Record<string, unknown>);

/**
 * 是否为 chunked manifest 类型（collision/terrain/npcs 的 chunkedUrl）。
 *
 * chunked 与 region-replace 的 baseUrl 基准不同（对齐 SDK）：
 * - chunked（buildChunkModule）：`url = baseUrl + seg` 纯前缀拼接，baseUrl 相对「页面根
 *   （= 授权根 = meta.json 目录）」，不相对 manifest 目录。
 * - region-replace（config-manager）：`resolveUrl(baseUrl, config目录)`，baseUrl 相对
 *   config 目录。
 * - npc legacy configFile：无 baseUrl，字段值相对 config 目录。
 */
const isChunkedManifest = computed(() => isChunkedEntryField(props.entryFieldName));

/**
 * 子 json 内 url 资源字段（modules[].url / regions[].configFile / modelFilePath）的
 * 「落盘基准目录」（相对项目根，带尾斜杠），透传 PropertyPanel → SchemaRenderer →
 * UrlField.valueBaseDir。
 *
 * - chunked：baseUrl 相对授权根（页面根）→ 不拼 dirname，直接 baseUrl || ''
 * - region-replace / npc legacy：baseUrl/字段值相对 config 目录 → dirname + baseUrl
 *
 * draft.baseUrl 在 computed 内访问，编辑 baseUrl 时 valueBaseDir 响应式跟随。
 */
const configDir = computed(() => {
  const dir = FileBundle.dirname(props.cfgPath);
  const baseUrl = typeof draft.baseUrl === 'string' ? draft.baseUrl : '';
  if (isChunkedManifest.value) {
    return baseUrl || '';
  }
  return FileBundle.joinRelativePath(dir, baseUrl || './');
});

/**
 * 场景表单字段树（白名单驱动源）。
 *
 * 只在「结构变化」时重建（array-push / array-remove / raw 应用）——叶子字段 value 变化
 * 不改变字段名与形态，rules 无需重建，避免 v-for 重排导致输入框失焦。
 */
const rules = ref<FieldDef[]>(buildSubEditorRules(draft, props.skeleton, props.entryFieldName));

/** 当前选中的第一层字段 key（上下结构里「下面编辑哪个字段」） */
const selectedKey = ref<string | null>(rules.value[0]?.path ?? null);

/** key 列表高度（水平 Splitter 拖拽调整） */
const keyListHeight = ref(180);

/**
 * 合成 widget schema：rootPath='' + fields=[选中 field]。
 *
 * PropertyPanel 对 rootPath='' 会短路 effectiveFields 直接返回 fields，且 widgetData =
 * 整个 value（draft）、rendererBasePath=''，因此字段 path 相对 draft 根——选中单个
 * 第一层 field 后，SchemaRenderer 只渲染该字段（group 内部递归 children、array 展开项、
 * 叶子直接单控件），与主编辑器「选中 widget 编辑其字段」语义一致。
 */
const subSchema = computed<WidgetSchema>(() => {
  const field = rules.value.find((f) => f.path === selectedKey.value);
  return {
    id: selectedKey.value ?? '__sub__',
    rootPath: '',
    fields: field ? [field] : [],
  };
});

/**
 * 下一层入口转发（v1.10.0）。
 *
 * 打通「第二层以下」的关键一环：此前本面板未监听 PropertyPanel 的 open-json-editor，
 * 导致子配置内的 `regions[].configFile` 虽有按钮但点击无任何反应（事件链在此断裂）。
 */
function onOpenJsonEditor(relPath: string): void {
  // PropertyPanel 的 open-json-editor 只抛路径（不带值），value 由本层从 draft 实时取——
  // 比透传更准确（draft 才是用户当前编辑态，props.json 是初值）。
  emit('open-json-editor', relPath, getByPath(draft, relPath));
}

/** 重建字段树，并校正选中 key（结构变化后原选中字段可能已不存在） */
function rebuildRules(): void {
  rules.value = buildSubEditorRules(draft, props.skeleton, props.entryFieldName);
  if (!rules.value.some((f) => f.path === selectedKey.value)) {
    selectedKey.value = rules.value[0]?.path ?? null;
  }
  // 结构变化（数组增删/ Raw 应用）可能改变 transform 条目集合，重算 gizmo；
  // selectedKey 未变时上面 watch 不会触发，必须在此显式重算。
  syncDraftGizmo();
}

// ==================== Gizmo（与主编辑器同构：选中 key 即自动全开） ====================
//
// 主编辑器行为是「选中控件 → 其下所有 transform 字段自动激活 gizmo」（MetaEditor 的
// watch(selectedWidgetId) + collectWidgetGizmoEntries）。子编辑器复用同一套 gizmo 桥接单例，
// 但 entry.path 必须是**相对 draft 根的短路径**（如 list[0].transform）：
// 桥接层的 isGizmoPathActive 是字符串全等匹配，若用 meta 绝对路径，则开关高亮失效，
// 用户点开关还会叠出第二个 gizmo。故统一以 selectedKey 为 basePath 收集，并标记
// source='draft' —— 让 PreviewPanel 跳过 findSceneObjectByPath 的兜底分支
// （draft 路径与 3D 场景对象没有对应关系，落兜底会误移场景首个 mesh/group）。
//
// 回写链路：拖拽 → changeHandler → MetaEditor 转发 applyGizmoChange →
// setByPath(draft) → draft deep watch 300ms → FileBundle.register → 场景重建 → gizmo 归位。

// 挂载期间把桥接层的来源上下文切到 'draft'：SchemaRenderer 的 toggle 按钮拿不到来源，
// 用户「关掉再打开」某个 gizmo 时靠此上下文继承正确的 source（见 setGizmoSourceContext）。
setGizmoSourceContext('draft');

/** 激活条目数组（原地刷新快照需要读写元素，故取引用而非副本） */
const { activeGizmoEntries } = useGizmoBridge();

/** 按当前选中 key 重算 draft 内应激活的 gizmo 条目（Raw 模式无表单，直接关闭） */
function syncDraftGizmo(): void {
  if (props.mode !== 'scene' || !selectedKey.value) {
    deactivateGizmo();
    return;
  }
  activateGizmoMulti(collectTransformEntries(getByPath(draft, selectedKey.value), selectedKey.value, 'draft'));
}

// selectedKey 变化（换字段）与 mode 切换（场景/Raw）都要重算；
// immediate 保证组件挂载即以首个字段激活，与主编辑器「选中即全开」一致。
watch([selectedKey, () => props.mode], syncDraftGizmo, { immediate: true });

/** 归一化为 plain number 三元组：draft 会被 JSON.stringify 序列化，不能塞代理对象/向量对象 */
function normalizeAxis(value: unknown): [number, number, number] {
  const arr = Array.isArray(value) ? value : [];
  return [Number(arr[0]) || 0, Number(arr[1]) || 0, Number(arr[2]) || 0];
}

/**
 * gizmo 拖拽回写（MetaEditor 从 changeHandler 转发而来）。
 *
 * path 是 draft 内的 transform 短路径，channel 为 position/rotation/scale/size。
 * 与表单输入走同一条 setByPath(draft) 链路，因此「编辑即生效」的防抖写回/补读逻辑天然复用。
 */
function applyGizmoChange(path: string, channel: string, value: unknown): void {
  const target = getByPath(draft, path);
  if (target == null || typeof target !== 'object') return;
  (target as Record<string, unknown>)[channel] = normalizeAxis(value);
}

/** 打点拾取回填（MetaEditor 从 pickResult 转发而来）：把命中坐标写回 draft 内 transform.position */
function applyPickPosition(path: string, pos: unknown): void {
  applyGizmoChange(path, 'position', pos);
}

/**
 * draft 数值变化后刷新已激活条目的 transform 快照。
 *
 * 为什么需要：draft 条目没有场景对象，编辑结果只能靠重建上屏；而重建后
 * restoreGizmoAfterSceneReady → createGizmoInstance 会**用条目快照初始化 proxy**。
 * 快照不刷新 → gizmo 停在旧位置，用户再拖拽时以旧值为基准回写，会把刚输入的数值覆盖掉。
 *
 * 为什么原地改 element 而不重新 collectTransformEntries：替换数组引用会触发 PreviewPanel
 * 的 watch(activeGizmoEntries)，虽然路径集合未变时无副作用，但原地更新语义更精确——
 * 这里只同步"值"，"条目集合"的增删一律交给 syncDraftGizmo。
 */
function refreshDraftGizmoTransforms(): void {
  for (const entry of activeGizmoEntries.value) {
    if (entry.source !== 'draft') continue;
    const value = getByPath(draft, entry.path);
    if (value == null || typeof value !== 'object') continue;
    const src = value as Record<string, unknown>;
    const next = { ...entry.transform };
    if (src.position != null) next.position = normalizeAxis(src.position);
    if (src.rotation != null) next.rotation = normalizeAxis(src.rotation);
    if (src.scale != null) next.scale = normalizeAxis(src.scale);
    entry.transform = next;
  }
}

/**
 * 外部写入字段值（v1.11.0）。
 *
 * 供 MetaEditor 在「非根层新建子 json」后把新 cfgPath 回填进**本层活 draft**——
 * 栈节点上的 json 只是备份快照，真正的编辑态在这里；写 draft 后 deep watch 会自动防抖写回。
 *
 * 与 applyGizmoChange 同构：relPath 相对 draft 根。
 */
function applyFieldValue(relPath: string, value: unknown): void {
  setByPath(draft, relPath, value);
}

defineExpose({ applyGizmoChange, applyPickPosition, applyFieldValue });

// ==================== 编辑即生效：draft 防抖写回 FileBundle ====================

const WRITE_DEBOUNCE_MS = 300;
let writeTimer: number | null = null;

/** 本次会话是否真的编辑过 draft（打开后未编辑直接退出不算脏） */
const hasChanges = ref(false);

function flushDraftToBundle(): void {
  const jsonStr = JSON.stringify(toRaw(draft), null, 2);
  const bytes = new TextEncoder().encode(jsonStr);
  FileBundle.register(props.cfgPath, bytes);
}

/**
 * deep watch draft：编辑后 300ms 防抖写回 FileBundle。
 * 与 PreviewPanel 的 REBUILD_DEBOUNCE_MS 叠加形成双缓冲，避免每次按键触发场景全量重建。
 * FileBundle 变化不会回流到 draft，无循环写回。
 */
watch(
  draft,
  () => {
    hasChanges.value = true;
    // 同步 gizmo 条目快照（原地更新，不替换数组引用）——重建恢复 gizmo 时依赖它，
    // 否则 gizmo 会停在旧位置、再拖拽还会把刚输入的数值覆盖掉。
    refreshDraftGizmoTransforms();
    if (writeTimer != null) window.clearTimeout(writeTimer);
    writeTimer = window.setTimeout(() => {
      writeTimer = null;
      flushDraftToBundle();
      // 通知上层静默补读：config 内容已变，可能改了资源引用字段（baseUrl/ply_name/…）
      emit('config-changed');
    }, WRITE_DEBOUNCE_MS);
  },
  { deep: true },
);

// ==================== 表单事件（对齐旧 JsonSubEditorModal 语义） ====================

/** 叶子字段写回：absPath 相对子 json 根（rootPath='' 时 rendererBasePath=''）。value === undefined 视为删除该 key */
function onChange(absPath: string, value: unknown): void {
  if (value === undefined) {
    removeAtPath(draft, absPath);
  } else {
    setByPath(draft, absPath, value);
  }
}

/** 数组追加：就地 push 后重建 rules（数组项结构可能变化） */
function onArrayPush(arrAbsPath: string, item: unknown): void {
  const arr = getByPath(draft, arrAbsPath);
  if (Array.isArray(arr)) arr.push(item);
  rebuildRules();
}

/** 数组移除：就地 splice 后重建 rules */
function onArrayRemove(arrAbsPath: string, index: number): void {
  const arr = getByPath(draft, arrAbsPath);
  if (Array.isArray(arr)) arr.splice(index, 1);
  rebuildRules();
}

/**
 * 资源段上传落盘（托管模式，ply_name / collision_name 等 string[] 资源引用）。
 *
 * 这类字段值语义是「相对 config.baseUrl 的资源段」。上传文件后：
 * - 落盘到 `dirname(cfgPath) + baseUrl + 文件名`（相对 meta 所在目录，与 MetaEditor 补读
 *   层 extractRegionReplaceResourcePaths 的 resolveFileSegToRelPath 推导基准一致）
 * - 字段值回填为文件名（**含扩展名**）——resolveFileSegToRelPath 对含扩展名的段不再补
 *   fileType，路径与落盘位置一致，ply_name(.splat) / collision_name(.glb) 均正确。
 *
 * 写盘失败降级：仍回填字段值（内存可预览），提示用户手动拷贝到目标相对路径。
 * setByPath 触发 draft deep watch → 300ms 防抖写回 FileBundle → emit config-changed →
 * 上层静默补读（此时文件已落盘，精确命中，不再依赖 basename 兜底）。
 */
async function onUploadResource(itemPath: string, file: File): Promise<void> {
  const root = getWorkspaceRoot();
  if (!root) {
    pushToast({ type: 'warn', message: '当前未处于托管工作区模式，无法落盘' });
    return;
  }
  const dirBase = FileBundle.dirname(props.cfgPath);
  const rawBaseUrl = typeof draft.baseUrl === 'string' ? draft.baseUrl : '';
  const base = FileBundle.joinRelativePath(dirBase, rawBaseUrl || './');
  const landPath = FileBundle.joinRelativePath(base, file.name);

  try {
    await ensureReadWritePermission(root);
    await writeFileToDirectory(root, landPath, file);
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn('[JsonSubEditorPanel] 资源落盘失败：', err);
    pushToast({
      type: 'warn',
      title: '已登记但未落盘',
      message: `无法写入托管目录，请手动把「${file.name}」拷贝到：${landPath}`,
      duration: 6000,
    });
  }
  // 字段值 = 文件名（含扩展名）
  setByPath(draft, itemPath, file.name);
}

/** Raw 模式「应用」：整体替换 draft 内容并重建 rules（替换后走同一 deep watch 写回） */
function onRawApply(parsed: Record<string, unknown>): void {
  for (const k of Object.keys(draft)) delete draft[k];
  Object.assign(draft, parsed);
  rebuildRules();
}

// ==================== 返回 & 生命周期清理 ====================

/**
 * 返回按钮：先同步落盘最后改动，再通知上层退出。
 *
 * 若直接 emit('close')，上层 onCloseSubEditor 会立即 runPendingConfigLoad 读 FileBundle，
 * 而组件卸载（onBeforeUnmount 的兜底 flush）是异步的——用户在编辑后 300ms 防抖内点
 * 「返回」时，补读可能读到旧内容（缺最后几次改动）。这里在 emit 前同步 flush 一次，
 * 保证补读读到最新 draft，消除竞态。
 */
function onBack(): void {
  if (writeTimer != null) {
    window.clearTimeout(writeTimer);
    writeTimer = null;
  }
  // 仅在有真实改动时 flush（未编辑直接退出不必写回，也避免无意义的 contentVersion++ 触发重建）
  if (hasChanges.value) {
    flushDraftToBundle();
  }
  emit('close', hasChanges.value);
}

onBeforeUnmount(() => {
  // 释放本会话以 draft 短路径激活的 gizmo，并把来源上下文还原为 'meta'，
  // 避免主编辑器后续（或再次进入二级页）把草稿条目误当 meta 绝对路径处理。
  deactivateGizmo();
  setGizmoSourceContext('meta');
  // 兜底：组件因其他原因卸载（非返回按钮）时，若还有未落盘的防抖写回，立即 flush 不丢改动
  if (writeTimer != null) {
    window.clearTimeout(writeTimer);
    writeTimer = null;
    flushDraftToBundle();
  }
});
</script>

