function unwrapSchema(schema: z.ZodTypeAny): NormalizedSchemaNode {
  let current: any = schema;
  let required = true;

  while (true) {
    if (current instanceof z.ZodOptional || current instanceof z.ZodDefault || current instanceof z.ZodNullable) {
      if (current instanceof z.ZodOptional || current instanceof z.ZodDefault) {
        required = false;
      }
      current = typeof (current as any).unwrap === 'function' ? (current as any).unwrap() : current;
      continue;
    }

    if (current instanceof z.ZodLazy) {
      current = current._def.getter();
      continue;
    }

    // z.preprocess 解包：兼容 zod v3 兼容层 (ZodEffects + _def.effect.type==='preprocess', 内层在 _def.schema)
    // 与 zod v4 (ZodPreprocess, _def.type==='pipe', 内层在 _def.out)；v4 中 z.ZodEffects 为 undefined，需先守卫
    const ZodEffectsClass = (z as any).ZodEffects;
    if (ZodEffectsClass && current instanceof ZodEffectsClass && current._def?.effect?.type === 'preprocess') {
      current = current._def.schema;
      continue;
    }
    const ZodPreprocessClass = (z as any).ZodPreprocess;
    if (ZodPreprocessClass && current instanceof ZodPreprocessClass && current._def?.out) {
      current = current._def.out;
      continue;
    }

    break;
  }

  return { schema: current, required };
}

function getObjectShape(schema: z.ZodObject<any>): Record<string, z.ZodTypeAny> {
  return typeof schema.shape === 'function' ? schema.shape() : schema.shape;
}

function isTupleOfNumbers(schema: any, size?: number): boolean {
  if (!(schema instanceof z.ZodTuple)) return false;
  const tupleDef = schema as any;
  const items = Array.isArray(tupleDef?._def?.items) ? tupleDef._def.items : [];
  return (
    (size === undefined || items.length === size) &&
    items.every((item: any) => unwrapSchema(item).schema instanceof z.ZodNumber)
  );
}

function isVector3ObjectSchema(schema: any): boolean {
  if (!(schema instanceof z.ZodObject)) return false;
  const shape = getObjectShape(schema);
  const keys = Object.keys(shape);
  return keys.length === 3 && ['x', 'y', 'z'].every((key) => unwrapSchema(shape[key]).schema instanceof z.ZodNumber);
}

function getNumberChecks(schema: any): { min?: number; max?: number } {
  const checks = Array.isArray(schema?._def?.checks) ? schema._def.checks : [];
  return checks.reduce((acc: { min?: number; max?: number }, check: any) => {
    if (check?.kind === 'min' && typeof check.value === 'number') acc.min = check.value;
    if (check?.kind === 'max' && typeof check.value === 'number') acc.max = check.value;
    return acc;
  }, {});
}

function applyFieldMetaOverride<T extends FieldDef>(field: T, override?: FieldMetaOverride): T {
  if (!override) {
    return field;
  }

  return {
    ...field,
    ...(override.label ? { label: override.label } : {}),
    ...(override.defaultValue !== undefined ? { defaultValue: override.defaultValue } : {}),
    ...(field.type === 'text' && override.placeholder ? { placeholder: override.placeholder } : {}),
  };
}

function createTextLikeField(
  path: string,
  label: string,
  required: boolean,
  fieldType: 'text' | 'textarea' | 'color' | 'url',
): FieldText | FieldTextarea | FieldColor | FieldUrl {
  if (fieldType === 'url') {
    return {
      type: 'url',
      path,
      label,
      hint: path,
      required,
      defaultValue: '',
      urlMode: 'dual',
    };
  }

  if (fieldType === 'color') {
    return {
      type: 'color',
      path,
      label,
      hint: path,
      required,
      defaultValue: '#ffffff',
    };
  }

  if (fieldType === 'textarea') {
    return {
      type: 'textarea',
      path,
      label,
      hint: path,
      required,
      defaultValue: '',
      rows: 4,
    };
  }

  return {
    type: 'text',
    path,
    label,
    hint: path,
    required,
    defaultValue: '',
  };
}

function buildScalarField(path: string, label: string, normalized: NormalizedSchemaNode): FieldDef | null {
  const { schema, required } = normalized;
  const normalizedPath = path.toLowerCase();

  if (schema instanceof z.ZodEnum) {
    const field: FieldSelect = {
      type: 'select',
      path,
      label,
      hint: path,
      required,
      options: schema.options.map((option: any) => ({ value: String(option), label: String(option) })),
    };
    if (schema.options[0] !== undefined) {
      field.defaultValue = schema.options[0];
    }
    return field;
  }

  if (schema instanceof z.ZodBoolean) {
    return {
      type: 'switch',
      path,
      label,
      hint: path,
      inline: true,
      required,
      defaultValue: false,
    };
  }

  if (schema instanceof z.ZodNumber) {
    const checks = getNumberChecks(schema);
    const hasRange = typeof checks.min === 'number' || typeof checks.max === 'number';
    if (hasRange) {
      const field: FieldSlider = {
        type: 'slider',
        path,
        label,
        hint: path,
        required,
        min: checks.min ?? 0,
        max: checks.max ?? 100,
        step: 0.1,
        defaultValue: checks.min ?? 0,
      };
      return field;
    }

    const field: FieldNumber = {
      type: 'number',
      path,
      label,
      hint: path,
      required,
      step: 0.1,
      defaultValue: 0,
    };
    if (typeof checks.min === 'number') field.min = checks.min;
    if (typeof checks.max === 'number') field.max = checks.max;
    return field;
  }

  if (schema instanceof z.ZodString) {
    // v1.12.1：文本/指针例外优先于 URL 猜测——zoneNavigateUrl / setPath / baseUrl
    // 只是字符串（跳转地址/集合标识/目录基准），不是资源文件，按 text 渲染，
    // 避免被 URL_FIELD_PATTERN 命中后获得本地上传入口（resolveResourceBundleDir 同排除）。
    if (isTextOnlyFieldName(normalizedPath)) {
      return createTextLikeField(path, label, required, 'text');
    }
    if (URL_FIELD_PATTERN.test(normalizedPath)) {
      // special: singleSceneConfigPath 支持本地导入（bundleDir: 'single-scene'）
      if (normalizedPath === 'singlesceneconfigpath') {
        return {
          type: 'url',
          path,
          label,
          hint: path,
          required,
          defaultValue: '',
          urlMode: 'dual',
          bundleDir: 'single-scene',
          // accept 与 SplatConfig.fileType 枚举（splat/ksplat/ply/spz/sog）及 SDK 识别能力对齐：
          // - spz：viewer-sdk utils/getGSFileExt 明确支持，spark detectResourceHint 亦识别
          // - sog：spark 的 SplatFullFileType.PCSOGSZIP、playcanvas 原生 gsplat 支持
          // - json：single scene config（配置入口，非 splat 数据本体）
          // 注意 rad/radc 是 Spark 流式 LOD 分块格式，必须真实托管 URL（内部按 rootUrl/page0.rad
          // 拼路径），blob URL 会失败，故不纳入本地上传白名单（见 PreviewPanel streamUrl 判定）。
          accept: '.splat,.ksplat,.ply,.spz,.sog,.json',
        };
      }
      // special: triangleMesh 的 mesh.url —— 本地 GLB 触发几何（授权导入 + zip 打包）
      if (normalizedPath === 'meshurl') {
        return {
          type: 'url',
          path,
          label,
          hint: path,
          required,
          defaultValue: '',
          urlMode: 'dual',
          bundleDir: 'mesh',
          accept: '.glb,.gltf',
        };
      }
      // v1.5.0：资源 URL 字段白名单统一支持本地导入。
      // regionReplaceConfigPath 在此（RESOURCE_URL_BUNDLE_DIRS → 'region-replace'），
      // 从 remote-only 改为 dual；collision.url / audioUrl / hdriUrl 等同样命中。
      const bundleDir = resolveResourceBundleDir(normalizedPath);
      // v1.14.0：目录型配置字段（regionReplaceConfigPath / configFile / chunkedUrl）
      // 标记 jsonEditable，字段旁可打开 JSON 子编辑器就地编辑。
      const jsonEditable = isJsonEntryFieldName(normalizedPath) || undefined;
      if (bundleDir) {
        return {
          type: 'url',
          path,
          label,
          hint: path,
          required,
          defaultValue: '',
          urlMode: 'dual',
          bundleDir,
          jsonEditable,
        };
      }
      // v1.12.0 无条件开放后：凡进入本 if（URL_FIELD_PATTERN 命中）的字段
      // resolveResourceBundleDir 必返回目录，此 remote-only 分支正常不可达。
      // 仅作防御保留（若未来 resolveResourceBundleDir 再次引入排除语义时兜底）。
      return {
        type: 'url',
        path,
        label,
        hint: path,
        required,
        defaultValue: '',
        urlMode: 'remote-only',
        jsonEditable,
      };
    }
    if (COLOR_FIELD_PATTERN.test(normalizedPath)) {
      return createTextLikeField(path, label, required, 'color');
    }
    if (TEXTAREA_FIELD_PATTERN.test(normalizedPath)) {
      return createTextLikeField(path, label, required, 'textarea');
    }
    return createTextLikeField(path, label, required, 'text');
  }

  return null;
}

function buildVec3Field(path: string, label: string, normalized: NormalizedSchemaNode): FieldVec3 | null {
  const schema = normalized.schema;
  if (isTupleOfNumbers(schema, 3) || isVector3ObjectSchema(schema)) {
    return {
      type: 'vec3',
      path,
      label,
      hint: path,
      required: normalized.required,
      step: 0.01,
      defaultValue: isVector3ObjectSchema(schema) ? { x: 0, y: 0, z: 0 } : [0, 0, 0],
    };
  }

  if (schema instanceof z.ZodArray && VEC3_FIELD_PATTERN.test(path)) {
    const itemSchema = unwrapSchema((schema as any).element).schema;

    if (itemSchema instanceof z.ZodNumber) {
      return {
        type: 'vec3',
        path,
        label,
        hint: path,
        required: normalized.required,
        step: 0.01,
        defaultValue: [0, 0, 0],
      };
    }
  }

  return null;
}

function buildFieldsFromObjectSchema(schema: z.ZodObject<any>): FieldDef[] {
  return Object.entries(getObjectShape(schema))
    .map(([key, childSchema]) => buildFieldFromSchema(key, childSchema as z.ZodTypeAny))
    .filter((field): field is FieldDef => Boolean(field));
}

function buildArrayField(path: string, label: string, normalized: NormalizedSchemaNode): FieldArray | null {
  const arraySchema = normalized.schema;
  const itemSchema =
    arraySchema instanceof z.ZodArray
      ? arraySchema.element
      : typeof arraySchema.unwrap === 'function'
        ? arraySchema.unwrap()
        : null;
  if (!itemSchema) {
    return null;
  }

  const itemNormalized = unwrapSchema(itemSchema);
  const itemLabel = label.endsWith('列表') ? label.slice(0, -2) : label;

  // v1.16.0：三元组数组（如 patrolPoints: z.array(z.tuple([n,n,n]))）→ array + itemSchema=[vec3]。
  // 此前 buildArrayField 只处理 object/union/string/number 数组项，tuple 数组项不命中任何
  // 分支 → return null → 字段被静默过滤（npc list[].patrolPoints 因此不渲染）。
  // itemSchema path='' 使 vec3 控件直接读写数组项本身（[n,n,n]），defaultItem 返回 [0,0,0]。
  if (isTupleOfNumbers(itemNormalized.schema, 3)) {
    return {
      type: 'array',
      path,
      label,
      hint: path,
      required: normalized.required,
      listLabel: `${label}列表`,
      emptyText: `尚未添加${itemLabel}`,
      itemTitle: (index) => `${path || 'item'}[${index}]`,
      itemColor: () => ARRAY_COLOR,
      itemSchema: [
        {
          type: 'vec3',
          path: '',
          label: itemLabel,
          hint: `${path}[]`,
          step: 0.01,
          defaultValue: [0, 0, 0],
        },
      ],
      defaultItem: () => [0, 0, 0] as unknown as Record<string, unknown>,
      defaultValue: [],
    };
  }

  if (itemNormalized.schema instanceof z.ZodObject) {
    const itemFields = buildFieldsFromObjectSchema(itemNormalized.schema);
    const shape = getObjectShape(itemNormalized.schema);
    const titleKey = ['name', 'id', 'label', 'title'].find((key) => key in shape);
    // 统一使用 buildObjectSkeleton 生成默认项骨架，与 Record variant 的 recordValueSkeleton 保持一致
    const defaultItem = buildObjectSkeleton(itemNormalized.schema);

    return {
      type: 'array',
      path,
      label,
      hint: path,
      required: normalized.required,
      listLabel: `${label}列表`,
      emptyText: `尚未添加${itemLabel}`,
      itemTitle: (index, item) => {
        if (titleKey && item && typeof item === 'object') {
          const title = (item as Record<string, unknown>)[titleKey];
          if (typeof title === 'string' && title) return title;
        }
        return `${path || 'item'}[${index}]`;
      },
      itemColor: () => ARRAY_COLOR,
      itemSchema: itemFields,
      defaultItem: () => JSON.parse(JSON.stringify(defaultItem)),
      defaultValue: [],
    };
  }

  // v1.11.0：判别联合作为数组项（如 renderer.preDepthPass.sources——每项是 mesh/gaussian
  // 变体）。此前 union 数组项无法渲染：此分支缺失 → return null → 字段被静默过滤。
  // itemSchema 以 path='' 的 union 字段承载整个数组项——SchemaRenderer 渲染 array item 时
  // resolve('') 返回 item 自身；mergeWithInferred 对 path='' 字段短路（:759-760），不会按
  // data key 推断多余字段（避免 type/url 被重复渲染成普通控件）。defaultItem 取首个变体
  // 骨架（含 type 判别字段），variant.fields 相对 item 对象（buildFieldsFromObjectSchema
  // 不依赖传入 path，仅用其结构）。
  if (itemNormalized.schema instanceof z.ZodUnion) {
    const unionField = buildUnionField(path, itemLabel, itemNormalized.schema, normalized.required);
    if (!unionField) return null;
    return {
      type: 'array',
      path,
      label,
      hint: path,
      required: normalized.required,
      listLabel: `${label}列表`,
      emptyText: `尚未添加${itemLabel}`,
      itemTitle: (index, item) => {
        const t =
          item && typeof item === 'object' && !Array.isArray(item) ? (item as Record<string, unknown>).type : undefined;
        return typeof t === 'string' && t
          ? `${humanizeLabel(t)} [${index}]`
          : `${itemLabel || path || 'item'}[${index}]`;
      },
      itemColor: () => ARRAY_COLOR,
      itemSchema: [{ ...unionField, path: '', label: itemLabel }],
      defaultItem: () =>
        JSON.parse(JSON.stringify((unionField.variants[0]?.defaultSkeleton ?? {}) as Record<string, unknown>)),
      defaultValue: [],
    };
  }

  if (itemNormalized.schema instanceof z.ZodString) {
    return {
      type: 'array',
      path,
      label,
      hint: path,
      required: normalized.required,
      listLabel: `${label}列表`,
      emptyText: `尚未添加${itemLabel}`,
      itemTitle: (index, item) => (typeof item === 'string' && item ? item : `[${index}]`),
      itemColor: () => ARRAY_COLOR,
      itemSchema: [
        {
          type: 'text',
          path: '',
          label: itemLabel,
          hint: `${path}[]`,
        },
      ],
      defaultItem: () => '' as unknown as Record<string, unknown>,
      defaultValue: [],
    };
  }

  if (itemNormalized.schema instanceof z.ZodNumber && VEC3_FIELD_PATTERN.test(path)) {
    return {
      type: 'array',
      path,
      label,
      hint: path,
      required: normalized.required,
      listLabel: `${label}列表`,
      emptyText: `尚未添加${itemLabel}`,
      itemTitle: (index) => `[${index}]`,
      itemColor: () => ARRAY_COLOR,
      itemSchema: [
        {
          type: 'number',
          path: '',
          label: itemLabel,
          hint: `${path}[]`,
          step: 0.1,
        },
      ],
      defaultItem: () => 0 as unknown as Record<string, unknown>,
      defaultValue: [],
    };
  }

  // 通用数字数组（如 geometry: z.array(z.number())）
  if (itemNormalized.schema instanceof z.ZodNumber) {
    return {
      type: 'array',
      path,
      label,
      hint: path,
      required: normalized.required,
      listLabel: `${label}列表`,
      emptyText: `尚未添加${itemLabel}`,
      itemTitle: (index) => `[${index}]`,
      itemColor: () => ARRAY_COLOR,
      itemSchema: [
        {
          type: 'number',
          path: '',
          label: itemLabel,
          hint: `${path}[]`,
          step: 0.1,
        },
      ],
      defaultItem: () => 0 as unknown as Record<string, unknown>,
      defaultValue: [],
    };
  }

  return null;
}

function buildGroupField(
  path: string,
  label: string,
  normalized: NormalizedSchemaNode,
): FieldGroup | FieldTransform | null {
  if (!(normalized.schema instanceof z.ZodObject)) {
    return null;
  }

  const shape = getObjectShape(normalized.schema);

  // 识别 transformSchema：ZodObject 含 position / rotation / scale 三个 vec3 tuple → type:'transform'（Gizmo 可用）
  if (isTransformShape(shape)) {
    return {
      type: 'transform',
      path,
      label,
      hint: path,
      required: normalized.required,
      color: GROUP_COLOR,
      step: 0.01,
      defaultValue: { position: [0, 0, 0], rotation: [0, 0, 0], scale: [1, 1, 1] },
    };
  }

  return {
    type: 'group',
    path,
    label,
    hint: path,
    required: normalized.required,
    color: GROUP_COLOR,
    children: buildFieldsFromObjectSchema(normalized.schema),
    defaultValue: {},
  };
}

/**
 * 判别联合分支识别：ZodObject 的 `type` 字段若为 ZodLiteral，返回其字面量值；
 * 否则返回 undefined（普通对象分支）。
 *
 * 用于 shapeSchema 等判别联合：每个分支 `type: z.literal('box')` → 返回 'box'，
 * 使 union variants 以 shape 类型作为变体 id / label / 匹配判据。
 */
function getDiscriminantLiteral(shape: Record<string, any>): string | undefined {
  const typeSchema = shape['type'];
  if (!typeSchema) return undefined;
  const normalized = unwrapSchema(typeSchema);
  const literal = normalized.schema;
  if (literal instanceof z.ZodLiteral) {
    return typeof literal.value === 'string' ? literal.value : undefined;
  }
  if (literal instanceof z.ZodEnum) {
    return typeof literal.options?.[0] === 'string' ? literal.options[0] : undefined;
  }
  return undefined;
}

/** zod transformSchema 判定：ZodObject 含 position / rotation / scale 三个 vec3 tuple（允许额外可选字段如 locationCM） */
function isTransformShape(shape: Record<string, any>): boolean {
  const keys = Object.keys(shape);
  const coreKeys = ['position', 'rotation', 'scale'];
  // 核心三轴至少出现 2 个，且出现者均为 3 元组数字数组，即判定为 transform 结构。
  // 不限制 keys 总数：transformSchema 已新增 locationCM（可选 vec3）等扩展字段，
  // 若沿用 keys.length<=3 会把含 4 个 key 的 transform 误判为普通 group，导致 Gizmo 控件消失。
  const presentCore = coreKeys.filter((k) => keys.includes(k));
  if (presentCore.length < 2) return false;
  return coreKeys.every((k) => {
    if (!(k in shape)) return true;
    const child = (shape[k] as any)?._def?.innerType ?? shape[k];
    return isTupleOfNumbers(child, 3);
  });
}

function buildFieldFromSchema(path: string, schema: z.ZodTypeAny, override?: FieldMetaOverride): FieldDef | null {
  const label = override?.label ?? humanizeLabel(path);
  const normalized = unwrapSchema(schema);

  const vec3Field = buildVec3Field(path, label, normalized);
  if (vec3Field) return applyFieldMetaOverride(vec3Field, override);

  const scalarField = buildScalarField(path, label, normalized);
  if (scalarField) return applyFieldMetaOverride(scalarField, override);

  if (normalized.schema instanceof z.ZodArray) {
    const arrayField = buildArrayField(path, label, normalized);
    return arrayField ? applyFieldMetaOverride(arrayField, override) : null;
  }

  if (normalized.schema instanceof z.ZodObject) {
    const groupField = buildGroupField(path, label, normalized);
    return groupField ? applyFieldMetaOverride(groupField, override) : null;
  }

  // v1.17.0：Record（如 npc anim.animations: z.record(string, union(object,string).optional())）
  // → auto-object 键值对编辑。值为结构化对象时补 recordValueSchema/recordValueSkeleton，
  // 否则（标量值）走基础 auto-object。此前 ZodRecord 不命中任何分支 → return null → 静默过滤。
  if (normalized.schema instanceof z.ZodRecord) {
    const recordField = buildRecordField(path, label, normalized);
    return recordField ? applyFieldMetaOverride(recordField, override) : null;
  }

  if (normalized.schema instanceof z.ZodUnion) {
    // 判别联合字段（如 shape 节点）：各分支含 `type: z.literal('xxx')` → 生成 FieldUnion（类型切换器）
    const unionField = buildUnionField(path, label, normalized.schema, normalized.required);
    if (unionField) return applyFieldMetaOverride(unionField, override);
    // 非判别联合：取第一个能构建的分支字段（兜底）
    const options = (normalized.schema as any)._def?.options ?? [];
    for (const option of options) {
      const field = buildFieldFromSchema(path, option);
      if (field) return applyFieldMetaOverride(field, override);
    }
    return null;
  }

  return null;
}

/**
 * 从 z.ZodRecord 构建 auto-object 字段（键值对 map 编辑）。
 *
 * Record 值类型可能是标量（z.record(string, z.string())）或结构化对象
 * （z.record(string, npcAnimationInfoSchema)）或二者的 union（z.record(string,
 * union(object, string).optional())）。值为结构化对象时补 recordValueSchema +
 * recordValueSkeleton（SchemaRenderer onAutoObjectAddKey 深拷贝骨架作为新建键默认值）。
 *
 * @returns auto-object 字段；无法取到 valueType 时返回 null
 */
function buildRecordField(path: string, label: string, normalized: NormalizedSchemaNode): FieldAutoObject | null {
  const valueType = (normalized.schema as any)._def?.valueType as z.ZodTypeAny | undefined;
  if (!valueType) return null;

  const field: FieldAutoObject = {
    type: 'auto-object',
    path,
    label,
    hint: path,
    required: normalized.required,
    defaultExpanded: false,
    defaultValue: {},
  };

  // 值类型解包 optional/nullable 后，提取结构化对象 + union 标量类型列表
  const { objectSchema, scalarTypes } = extractObjectFromValue(unwrapSchema(valueType).schema);
  if (objectSchema) {
    field.recordValueSchema = buildFieldsFromObjectSchema(objectSchema);
    field.recordValueSkeleton = buildObjectSkeleton(objectSchema);
    // union（object | 标量，如 npc anim.animations 的 NPCAnimationInfo | string）：
    // 标记标量类型，新建键类型下拉 = 标量 + 'object'（默认标量）；
    // 纯 object 值类型（无标量分支）不标记，新建直接骨架、无类型下拉。
    if (scalarTypes.length > 0) {
      field.recordValueUnionTypes = scalarTypes;
    }
  }

  return field;
}

/** 从 Record 值类型中提取结构化对象 schema 与 union 标量类型列表 */
function extractObjectFromValue(schema: z.ZodTypeAny): {
  objectSchema: z.ZodObject<any> | null;
  scalarTypes: ('string' | 'number' | 'boolean')[];
} {
  if (schema instanceof z.ZodObject) return { objectSchema: schema, scalarTypes: [] };
  if (schema instanceof z.ZodUnion) {
    const options = (schema as any)._def?.options ?? [];
    let objectSchema: z.ZodObject<any> | null = null;
    const scalarTypes: ('string' | 'number' | 'boolean')[] = [];
    for (const option of options) {
      const normalized = unwrapSchema(option);
      if (normalized.schema instanceof z.ZodObject && !objectSchema) {
        objectSchema = normalized.schema;
      } else if (normalized.schema instanceof z.ZodString) {
        scalarTypes.push('string');
      } else if (normalized.schema instanceof z.ZodNumber) {
        scalarTypes.push('number');
      } else if (normalized.schema instanceof z.ZodBoolean) {
        scalarTypes.push('boolean');
      }
    }
    return { objectSchema, scalarTypes };
  }
  return { objectSchema: null, scalarTypes: [] };
}

function mergeWidgetFields(baseFields: FieldDef[] | undefined, generatedFields: FieldDef[]): FieldDef[] {
  const existingPaths = new Set((baseFields ?? []).map((field) => field.path));
  // 浅拷贝 base，避免 mutate widget-schemas 的模块级常量
  const merged: FieldDef[] = (baseFields ?? []).map((field) => ({ ...field }));

  // v1.9.0：url 字段的本地导入能力由 zod 白名单推断决定（单一真相源 resolveResourceBundleDir）。
  // widget-schemas 手写规则可能把字段标成 remote-only（历史写法，如 regionReplaceConfigPath /
  // npcs.configFile），若 zod 推断为 dual 则升级 base 的 urlMode + 补 bundleDir——
  // 手写规则保留 label/hint/accept 等展示细节，但不再覆盖本地导入能力。
  for (const gen of generatedFields) {
    if (gen.type !== 'url' || (gen as any).urlMode !== 'dual' || !(gen as any).bundleDir) continue;
    const base = merged.find((f) => f.path === gen.path);
    if (!base || base.type !== 'url') continue;
    const b = base as any;
    if (b.urlMode !== 'dual') b.urlMode = 'dual';
    if (!b.bundleDir) b.bundleDir = (gen as any).bundleDir;
  }

  // 补充 base 没有的字段
  for (const gen of generatedFields) {
    if (!existingPaths.has(gen.path)) merged.push(gen);
  }
  return merged;
}

function resolveSchemaAtPath(schema: z.ZodTypeAny, path: string): z.ZodTypeAny | null {
  const segments = path.split('.').filter(Boolean);
  let current: z.ZodTypeAny = schema;

  for (const segment of segments) {
    const normalized = unwrapSchema(current);
    if (!(normalized.schema instanceof z.ZodObject)) {
      return null;
    }
    const shape = getObjectShape(normalized.schema);
    const next = shape[segment] as z.ZodTypeAny | undefined;
    if (!next) {
      return null;
    }
    current = next;
  }

  return current;
}

function getTopLevelShape(schema: z.ZodTypeAny): Record<string, z.ZodTypeAny> {
  const normalized = unwrapSchema(schema);
  if (!(normalized.schema instanceof z.ZodObject)) {
    return {};
  }
  return getObjectShape(normalized.schema);
}

/**
 * 从 ZodObject 递归提取默认值骨架。
 * 每个字段取 Zod schema 的 defaultValue 或按类型推断（string→'', number→0, boolean→false）。
 */
function buildObjectSkeleton(schema: z.ZodObject<any>): Record<string, unknown> {
  const shape = getObjectShape(schema);

  // transform schema（position/rotation/scale 三元组）→ 返回标准 transform 骨架
  // 必须在逐字段遍历前短路，否则 ZodTuple 子段不会被处理，得到空 {}
  if (isTransformShape(shape)) {
    return { position: [0, 0, 0], rotation: [0, 0, 0], scale: [1, 1, 1] };
  }

  const skeleton: Record<string, unknown> = {};
  for (const [key, childSchema] of Object.entries(shape)) {
    const normalized = unwrapSchema(childSchema as z.ZodTypeAny);
    const def = (childSchema as any)?._def;
    // 有显式 .default() 的字段 → 始终包含（schema 作者明确指定了默认值）
    if (def?.defaultValue !== undefined && typeof def.defaultValue !== 'function') {
      skeleton[key] = def.defaultValue;
      continue;
    }
    // 可选字段（无显式 .default()）→ 不写入骨架
    // 编辑器以占位行 + "+ 添加"按钮呈现，用户主动添加后才写入
    if (!normalized.required) {
      continue;
    }
    if (normalized.schema instanceof z.ZodString) skeleton[key] = '';
    else if (normalized.schema instanceof z.ZodNumber) skeleton[key] = 0;
    else if (normalized.schema instanceof z.ZodBoolean) skeleton[key] = false;
    else if (normalized.schema instanceof z.ZodObject) skeleton[key] = buildObjectSkeleton(normalized.schema);
    else if (normalized.schema instanceof z.ZodArray) skeleton[key] = [];
    else if (normalized.schema instanceof z.ZodTuple) {
      // vec3 tuple（如 position: [number, number, number]）→ 生成对应长度的零数组
      const items = (normalized.schema as any)._def?.items ?? [];
      skeleton[key] = items.map(() => 0);
    }
  }
  return skeleton;
}

/**
 * 从 ZodUnion 生成 WidgetVariant 列表。
 *
 * 支持 ZodObject / ZodArray / ZodRecord 三种 union 分支：
 * - ZodObject → variant rootPath = id，fields 从对象 schema 生成
 * - ZodArray → variant rootPath = ''，field path = id（数组控件）
 * - ZodRecord → variant rootPath = ''，field path = id（auto-object 控件）
 */
function buildUnionVariants(id: string, unionSchema: z.ZodUnion<any>): WidgetVariant[] {
  const options = (unionSchema as any)._def?.options ?? [];
  const variants: WidgetVariant[] = [];

  // 统计每个 key 在几个 ZodObject 分支出现——用于无判别 union 的变体标识
  // （如 npcs：chunkedRef{enabled,chunkedUrl} vs legacy{enabled,configFile,models,list}，
  //  共享 enabled 导致 keys[0] 冲突；独有字段 chunkedUrl/configFile 才能区分分支）
  const keyCount = new Map<string, number>();
  for (const option of options) {
    const n = unwrapSchema(option);
    if (n.schema instanceof z.ZodObject) {
      for (const k of Object.keys(getObjectShape(n.schema))) {
        keyCount.set(k, (keyCount.get(k) ?? 0) + 1);
      }
    }
  }

  for (const [index, option] of options.entries()) {
    const normalized = unwrapSchema(option);
    const schema = normalized.schema;

    if (schema instanceof z.ZodArray) {
      const arrayField = buildArrayField(id, humanizeLabel(id), normalized);
      if (arrayField) {
        variants.push({
          id: 'array',
          label: 'Array',
          rootPath: '',
          fields: [arrayField],
          defaultSkeleton: { [id]: [] },
          match: (data: unknown) => Array.isArray(data),
        });
      }
    } else if (schema instanceof z.ZodRecord) {
      const recordDef = (schema as any)._def;
      const valueSchema = recordDef.valueType;
      const valueNormalized = unwrapSchema(valueSchema);

      const autoObjectField: any = {
        type: 'auto-object',
        path: id,
        label: humanizeLabel(id),
        hint: id,
        required: normalized.required,
        color: ARRAY_COLOR,
        defaultExpanded: true,
      };

      // Record 值为结构化对象（如 interactionZoneSchema）→ 携带字段定义和骨架
      if (valueNormalized.schema instanceof z.ZodObject) {
        autoObjectField.recordValueSchema = buildFieldsFromObjectSchema(valueNormalized.schema);
        autoObjectField.recordValueSkeleton = buildObjectSkeleton(valueNormalized.schema);
      }

      variants.push({
        id: 'record',
        label: 'Record',
        rootPath: '',
        fields: [autoObjectField],
        defaultSkeleton: { [id]: {} },
        match: (data: unknown) => data != null && typeof data === 'object' && !Array.isArray(data),
      });
    } else if (schema instanceof z.ZodObject) {
      const shape = getObjectShape(schema);
      const keys = Object.keys(shape);
      const hasUrl = 'url' in shape;
      const hasTransform = 'transform' in shape;
      const hasModules = 'modules' in shape;
      const hasLoadConfig = 'loadConfig' in shape;

      let variantId = `${id}-${index}`;
      let variantLabel = `${humanizeLabel(id)} ${index + 1}`;
      let matcher = (data: unknown) => data != null && typeof data === 'object' && !Array.isArray(data);

      // 判别联合分支：对象含 `type: z.literal('xxx')` 字段 → 用 literal 值作为 variantId / label / matcher
      // （覆盖 shapeSchema 等判别联合；对 interactionZone 的 shape 节点、audioZone 的 shape 节点生效）
      const discriminantValue = getDiscriminantLiteral(shape);
      if (discriminantValue !== undefined) {
        variantId = discriminantValue;
        variantLabel = humanizeLabel(discriminantValue);
        matcher = (data: unknown) => {
          if (!data || typeof data !== 'object' || Array.isArray(data)) return false;
          return (data as Record<string, unknown>).type === discriminantValue;
        };
      } else if (id === 'collision') {
        if (hasUrl && hasTransform) {
          variantId = 'legacy';
          variantLabel = 'Legacy';
          matcher = (data: unknown) => {
            if (!data || typeof data !== 'object' || Array.isArray(data)) return false;
            return 'url' in (data as Record<string, unknown>) || 'transform' in (data as Record<string, unknown>);
          };
        } else if (hasModules && hasLoadConfig) {
          variantId = 'chunked';
          variantLabel = 'Chunked';
          matcher = (data: unknown) => {
            if (!data || typeof data !== 'object' || Array.isArray(data)) return false;
            return 'modules' in (data as Record<string, unknown>) || 'loadConfig' in (data as Record<string, unknown>);
          };
        }
      } else if (keys.length > 0) {
        // 无判别字段的 union（如 npcs chunkedRef/legacy、terrain legacy/chunkedRef）：
        // 用"本分支独有字段"（仅出现在当前分支的 key）作为 variantId / label / matcher。
        // 避免共享字段（enabled）导致 variantId 冲突、类型下拉无法区分。
        const uniqueKeys = keys.filter((k) => (keyCount.get(k) ?? 0) === 1);
        const marker = uniqueKeys[0] ?? keys[0];
        variantId = marker;
        variantLabel = humanizeLabel(marker);
        matcher = (data: unknown) => {
          if (!data || typeof data !== 'object' || Array.isArray(data)) return false;
          // 有独有字段 → 严格按独有字段判定；退化（全分支同 keys）→ 任一 key 存在即命中
          if (uniqueKeys.length > 0) {
            return uniqueKeys.some((key) => key in (data as Record<string, unknown>));
          }
          return keys.some((key) => key in (data as Record<string, unknown>));
        };
      }

      variants.push({
        id: variantId,
        label: variantLabel,
        rootPath: id,
        fields: buildFieldsFromObjectSchema(schema),
        defaultSkeleton: { [id]: buildObjectSkeleton(schema) },
        match: matcher,
      });
    }
  }

  return variants;
}

/**
 * 从判别联合（ZodUnion，各分支含 `type: z.literal('xxx')`）生成 FieldUnion 变体列表。
 *
 * 与 buildUnionVariants 的区别：字段级（相对当前字段路径渲染），
 * 每个分支的 fields 不含 type 自身（type 由切换器写回），defaultSkeleton 为字段级骨架。
 */
function buildUnionFieldVariants(id: string, unionSchema: z.ZodUnion<any>): WidgetVariant[] {
  const options = (unionSchema as any)._def?.options ?? [];
  const variants: WidgetVariant[] = [];

  for (const option of options) {
    const normalized = unwrapSchema(option);
    const schema = normalized.schema;
    if (!(schema instanceof z.ZodObject)) continue;

    const shape = getObjectShape(schema);
    const discriminantValue = getDiscriminantLiteral(shape);
    if (discriminantValue === undefined) continue;

    variants.push({
      id: discriminantValue,
      label: humanizeLabel(discriminantValue),
      rootPath: '',
      // 过滤判别字段 type 自身：类型由顶部 union 切换器控制，不重复渲染 Type 控件
      fields: buildFieldsFromObjectSchema(schema).filter((f) => f.path !== 'type'),
      // v1.10.0：defaultSkeleton 显式补 type 判别字段——buildObjectSkeleton 不处理
      // ZodLiteral（无 defaultValue、非常规类型），生成的骨架缺 type。缺 type 会导致：
      // interactionZones 添加 shape 后 gizmo entries 收集不到（zone.shape.type undefined）、
      // SDK 跳过 Trigger 注册（"zone 缺少 shape"）、网格类型错乱。
      defaultSkeleton: { ...buildObjectSkeleton(schema), type: discriminantValue },
      match: (data: unknown) => {
        if (!data || typeof data !== 'object' || Array.isArray(data)) return false;
        return (data as Record<string, unknown>).type === discriminantValue;
      },
    });
  }

  return variants;
}

/** 判别联合字段：生成 FieldUnion（顶部类型切换 + 当前变体字段） */
function buildUnionField(
  path: string,
  label: string,
  unionSchema: z.ZodUnion<any>,
  required: boolean,
): {
  type: 'union';
  path: string;
  label: string;
  hint: string;
  required: boolean;
  discriminant: string;
  variants: WidgetVariant[];
  color: string;
  defaultExpanded: boolean;
} | null {
  const variants = buildUnionFieldVariants(path, unionSchema);
  if (variants.length === 0) return null;
  return {
    type: 'union',
    path,
    label,
    hint: path,
    required,
    discriminant: 'type',
    variants,
    color: GROUP_COLOR,
    defaultExpanded: true,
  };
}

function buildAutoWidget(id: string, schema: z.ZodTypeAny): WidgetSchema {
  const normalized = unwrapSchema(schema);
  const isObjectWidget = normalized.schema instanceof z.ZodObject;
  const isUnionWidget = normalized.schema instanceof z.ZodUnion;
  const widgetMeta = TOP_LEVEL_WIDGET_META_OVERRIDES[id];
  const label = widgetMeta?.label ?? id;

  if (isUnionWidget) {
    const variants = buildUnionVariants(id, normalized.schema);
    // v1.13.0：npcs union 的 schema 顺序是 chunkedRef 在前（SDK strict 契约——
    // chunkedRef 用 .strict() 拒绝含 models/list 的对象，legacy 无 strict 兜底混合形态，
    // 顺序不可在 schema 层调整）。但编辑器里 legacy 单文件清单（configFile/models/list）
    // 是主要使用形态：删除 npcs 后重新添加默认应写入 legacy 骨架，而不是 chunkedRef——
    // 否则用户误在 chunkedUrl 字段上传 legacy json → region manifest 提取 0 引用 →
    // 内部资源不补读/不打包（导出只剩一份 json）。此处把 configFile(legacy) 变体置首，
    // onAddWidget / PropertyPanel「无数据回退 variants[0]」即落到 legacy；已有数据仍由
    // match 精确判定形态，不受数组顺序影响。
    if (id === 'npcs') {
      const legacyIdx = variants.findIndex((v) => v.id === 'configFile');
      if (legacyIdx > 0) {
        const [legacyVariant] = variants.splice(legacyIdx, 1);
        variants.unshift(legacyVariant);
      }
    }
    const firstVariant = variants[0];
    return {
      id,
      label,
      rootPath: '',
      desc: widgetMeta?.desc ?? label,
      info: widgetMeta?.info,
      required: widgetMeta?.required ?? normalized.required,
      fields: firstVariant?.fields ?? [],
      variants,
    };
  }

  return {
    id,
    label,
    rootPath: isObjectWidget ? id : '',
    desc: widgetMeta?.desc ?? label,
    info: widgetMeta?.info,
    required: widgetMeta?.required ?? normalized.required,
    fields: isObjectWidget
      ? buildFieldsFromObjectSchema(normalized.schema)
      : [buildFieldFromSchema(id, schema, TOP_LEVEL_FIELD_META_OVERRIDES[id])].filter((field): field is FieldDef =>
          Boolean(field),
        ),
  };
}

/**
 * 合并 base（手动 widget-schemas）与 generated（schema 推断）：
 * - 顶层 fields 按 path 去重合并（base 优先）
 * - array widget 的 itemSchema 同样按 path 合并，使 schema 新增字段（如统一 Shape 判别联合）
 *   自动补充进手动定义的 item 表单，无需改 widget-schemas.ts
 */
function mergeWidget(baseWidget: WidgetSchema | undefined, generatedWidget: WidgetSchema): WidgetSchema {
  if (!baseWidget) {
    return generatedWidget;
  }

  const mergedFields = mergeWidgetFields(baseWidget.fields, generatedWidget.fields ?? []);

  // 收集 generated 中所有候选 array field（顶层 fields + union variants 内的 fields）
  const generatedArrayFields = [
    ...(generatedWidget.fields ?? []),
    ...(generatedWidget.variants ?? []).flatMap((v) => v.fields ?? []),
  ];

  // 对 array widget：把 generated.itemSchema 里 base 缺失的字段（按 path）补充进去。
  // 若 base itemSchema 已用子路径覆盖某 top-level key（如 geometry.type/size/transform 覆盖 geometry），
  // 则丢弃 schema 推断的整对象字段（geometry group），避免 UI 出现重复编辑区。
  //
  // unified-shape-trigger-ecs 阶段一：interactionZones 的 geometry/model 是旧格式兼容镜像
  // （二阶段统一 shape 后从 schema 移除），编辑器不展示——从 generated 中显式过滤。
  const mergedFieldsWithItemSchema = mergedFields.map((field) => {
    if (field.type !== 'array') return field;
    const generatedArray = generatedArrayFields.find((f) => f.type === 'array' && f.path === field.path) as
      (FieldArray & { type: 'array' }) | undefined;
    if (!generatedArray?.itemSchema) return field;
    const isInteractionZones = field.path === 'interactionZones';
    const baseTopKeys = new Set((field.itemSchema ?? []).map((f) => (f.path || '').split(/[.[]/)[0]).filter(Boolean));
    const filteredGenerated = (generatedArray.itemSchema ?? []).filter((f) => {
      const top = (f.path || '').split(/[.[]/)[0];
      if (isInteractionZones && (top === 'geometry' || top === 'model')) return false;
      return !top || !baseTopKeys.has(top);
    });
    return {
      ...field,
      itemSchema: mergeWidgetFields(field.itemSchema, filteredGenerated),
    };
  });

  return {
    ...generatedWidget,
    ...baseWidget,
    fields: mergedFieldsWithItemSchema,
    variants: generatedWidget.variants ?? baseWidget?.variants,
  };
}

function buildWidgetsFromSchema(rootSchema: z.ZodTypeAny, baseWidgets: WidgetSchema[] = []): WidgetSchema[] {
  const shape = getTopLevelShape(rootSchema);
  const baseWidgetMap = new Map(baseWidgets.map((widget) => [widget.id, widget]));
  const autoWidgetIds = Object.keys(shape).filter((id) => !CONSUMED_TOP_LEVEL_KEYS.has(id));
  const allWidgetIds = new Set<string>([...autoWidgetIds, ...baseWidgets.map((widget) => widget.id)]);

  const orderedIds = [
    ...DEFAULT_WIDGET_ORDER.filter((id) => allWidgetIds.has(id)),
    ...Array.from(allWidgetIds)
      .filter((id) => !DEFAULT_WIDGET_ORDER.includes(id as (typeof DEFAULT_WIDGET_ORDER)[number]))
      .sort(),
  ];

  return orderedIds
    .map((id) => {
      const baseWidget = baseWidgetMap.get(id);
      const schema =
        shape[id] ?? (baseWidget?.rootPath ? (resolveSchemaAtPath(rootSchema, baseWidget.rootPath) as any) : null);

      if (!schema) {
        return baseWidget!;
      }

      const generatedWidget = buildAutoWidget(id, schema);
      const generatedRootPath = Object.prototype.hasOwnProperty.call(shape, id)
        ? generatedWidget.rootPath
        : (baseWidget?.rootPath ?? generatedWidget.rootPath);

      generatedWidget.rootPath = generatedRootPath;
      return mergeWidget(baseWidget, generatedWidget);
    })
    .filter((widget): widget is WidgetSchema => Boolean(widget));
}

/**
 * 通过共享 zod schema 生成 editor rules：
 * - 顶层 widgets 默认从 ProjectConfig schema 自动派生
 * - widget-schemas.ts 只保留复杂控件、树行为和文案的 override
 * - 未手写覆盖的字段按 schema 语义自动生成
 */
export function buildEditorRules(options: BuildEditorRulesOptions): EditorRules {
  const mode = options.mode ?? 'hybrid';
  const useBaseRules = mode === 'hybrid';
  const includeSpecialWidgets = options.includeSpecialWidgets ?? true;
  const baseRules = useBaseRules
    ? projectConfigEditorRules
    : {
        version: '1.0',
        autoInferUnknownTopKeys: false,
        treeTitle: '操作菜单',
        widgets: [],
      };
  const widgets = buildWidgetsFromSchema(options.schema, useBaseRules ? projectConfigEditorRules.widgets : []);

  return {
    ...baseRules,
    widgets: includeSpecialWidgets ? applySpecialWidgets(widgets, options.schema) : widgets,
  };
}

export const zodOnlyEditorRules: EditorRules = buildEditorRules({
  schema: projectConfigSchema as unknown as z.ZodTypeAny,
  mode: 'zod',
});

/**
 * 从 zod object schema 生成平铺字段树（供子编辑器 schema 驱动复用）。
 *
 * 复用主编辑器的 zod → FieldDef 推断层（buildFieldFromSchema → buildScalarField /
 * buildArrayField / buildGroupField，含 enum→select、url→上传、transformSchema→transform
 * gizmo、optional→占位行），把任意 z.object schema 转成 FieldDef[]。
 *
 * 子编辑器（如 npc configFile）用它替代 infer 数据驱动，获得完整字段、枚举下拉、
 * 占位行（删除后可加回）、transform gizmo 等 schema 语义，不再依赖手写骨架/白名单猜类型。
 *
 * @param schema zod object schema（z.lazy/optional/default/nullable 会自动 unwrap）
 * @returns 平铺字段树；schema 不是 z.object 时返回空数组
 */
export function buildFieldsFromZodSchema(schema: z.ZodTypeAny): FieldDef[] {
  const normalized = unwrapSchema(schema);
  if (normalized.schema instanceof z.ZodObject) {
    return buildFieldsFromObjectSchema(normalized.schema);
  }
  return [];
}
