<template>
  <div class="add-key-row">
    <!-- 左列：键名输入 -->
    <div class="add-key-label-col">
      <input
        class="me-input"
        type="text"
        placeholder="键名"
        :value="modelValue"
        @input="emit('update:modelValue', ($event.target as HTMLInputElement).value)"
        @keyup.enter="emit('add')"
      />
    </div>
    <!-- 右列：类型选择 + 添加按钮 -->
    <div class="add-key-control-col">
      <select
        v-if="showType"
        class="me-select"
        :value="keyType"
        @change="emit('update:keyType', ($event.target as HTMLSelectElement).value)"
      >
        <option v-for="opt in typeOptions" :key="opt.value" :value="opt.value">
          {{ opt.label }}
        </option>
      </select>
      <button class="add-key-btn" :disabled="!modelValue.trim()" @click="emit('add')">
        <Plus :size="12" :stroke-width="2.5" />
        <span>添加</span>
      </button>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue';
import { Plus } from 'lucide-vue-next';

const props = defineProps<{
  modelValue: string;
  keyType?: string;
  showType?: boolean;
  /** 类型下拉选项（默认 string/number/boolean；union 值类型时传入标量 + object） */
  typeOptions?: { value: string; label: string }[];
}>();

const DEFAULT_TYPE_OPTIONS = [
  { value: 'string', label: '字符串' },
  { value: 'number', label: '数字' },
  { value: 'boolean', label: '布尔' },
];

/** 类型下拉选项（未传时用默认 string/number/boolean） */
const typeOptions = computed(() => props.typeOptions ?? DEFAULT_TYPE_OPTIONS);

const emit = defineEmits<{
  (e: 'update:modelValue', value: string): void;
  (e: 'update:keyType', value: string): void;
  (e: 'add'): void;
}>();
</script>

<style scoped>
