  display: grid;
  grid-template-columns: var(--me-field-label-width, 180px) 1fr;
  gap: 8px;
  align-items: center;
  min-height: 28px;
  padding: 6px 0;
  border-bottom: 1px solid var(--me-border);
}

/* 左列：与 FieldRow label-col 对齐 */
.add-key-label-col {
  overflow: hidden;
  min-width: 0;
}

/* 右列：类型选择 + 添加按钮 */
.add-key-control-col {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

/* 原生 select 基样式（SchemaRenderer scoped 隔离，AddKeyRow 需自己提供） */
.me-select {
  padding: 6px 0px;
  border-radius: 0;
  background: transparent;
  color: var(--me-text-2);
  font-size: var(--me-fs-sm);
  font-family: inherit;
  cursor: pointer;
  outline: none;
}

.add-key-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 12px;
  font-size: var(--me-fs-sm);
  font-family: inherit;
  color: var(--me-primary-hover);
  background: var(--me-primary-bg);
  border: 1px solid var(--me-primary);
  border-radius: var(--me-radius);
  cursor: pointer;
  transition: all var(--me-trans-fast);
  flex-shrink: 0;
  white-space: nowrap;
}

.add-key-btn:hover:not(:disabled) {
  background: var(--me-primary);
  color: #fff;
}

.add-key-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
</style>
