<template>
  <Teleport to="body">
    <div class="me-toast-container meta-editor-scope">
      <TransitionGroup name="me-toast">
        <div
          v-for="t in store"
          :key="t.id"
          class="me-toast"
          :class="`me-toast-${t.type}`"
          @click="dismiss(t.id)"
        >
          <component :is="iconOf(t.type)" :size="16" class="me-toast-icon" />
          <div class="me-toast-content">
            <div v-if="t.title" class="me-toast-title">{{ t.title }}</div>
            <div class="me-toast-msg">{{ t.message }}</div>
          </div>
          <X :size="14" class="me-toast-close" />
        </div>
      </TransitionGroup>
    </div>
  </Teleport>
</template>

<!-- 普通 <script>：暴露命令式 API（任意位置 import 即可使用），与组件共享同一个 store ref -->
<script lang="ts">
import { ref } from 'vue';
import { Info, CheckCircle2, AlertTriangle, XCircle, X } from 'lucide-vue-next';

export type ToastType = 'info' | 'success' | 'warn' | 'error';

interface ToastItem {
  id: number;
  type: ToastType;
  title?: string;
  message: string;
  timer?: number;
}

interface ToastOptions {
  type?: ToastType;
  title?: string;
  message: string;
  /** 自动消失毫秒数；0 表示需手动点击关闭。默认 4000 */
  duration?: number;
}

/**
 * 全局 Toast store（module 级单例）。
 *
 * - 任意位置可 `import { pushToast } from './Toast.vue'` 调用
 * - 必须在某个组件树挂载一次 `<Toast />`（推荐 MetaEditor 根节点），否则 toast 不会显示
 */
const _store = ref<ToastItem[]>([]);
let _idSeed = 1;

export function pushToast(opts: ToastOptions): number {
  const id = _idSeed++;
  const entry: ToastItem = {
    id,
    type: opts.type ?? 'info',
    title: opts.title,
    message: opts.message,
  };
  _store.value.push(entry);
  const dur = opts.duration ?? 4000;
  if (dur > 0) {
    entry.timer = window.setTimeout(() => {
      const i = _store.value.findIndex((t) => t.id === id);
      if (i >= 0) _store.value.splice(i, 1);
    }, dur);
  }
  return id;
}

export function dismissToast(id: number): void {
  const i = _store.value.findIndex((t) => t.id === id);
  if (i >= 0) {
    const [removed] = _store.value.splice(i, 1);
    if (removed.timer) window.clearTimeout(removed.timer);
  }
}

/** 内部钩子：组件 setup 与外部 helpers 共享同一个 ref */
export function _useToastStore() {
  return _store;
}

const _iconOf = (type: ToastType) => {
  switch (type) {
    case 'success':
      return CheckCircle2;
    case 'warn':
      return AlertTriangle;
    case 'error':
      return XCircle;
    default:
      return Info;
  }
};

export { X, _iconOf };
</script>

<script setup lang="ts">
import { onBeforeUnmount } from 'vue';

const store = _useToastStore();
const iconOf = _iconOf;
const dismiss = dismissToast;

onBeforeUnmount(() => {
  // 卸载时清掉所有定时器，避免内存泄漏
  for (const t of store.value) {
    if (t.timer) window.clearTimeout(t.timer);
  }
});
</script>

