<template>
  <div class="url-field">
    <!-- v1.4.0：radio 组与 JSON 操作按钮并排一行 -->
    <div class="url-field-top">
      <div class="url-mode-tabs">
        <label class="me-radio">
          <input type="radio" :name="modeName" :checked="currentMode === 'remote'" @change="currentMode = 'remote'" />
          <Globe :size="12" />
          <span>远程 URL</span>
        </label>
        <label class="me-radio">
          <input type="radio" :name="modeName" :checked="currentMode === 'local'" @change="currentMode = 'local'" />
          <HardDrive :size="12" />
          <span>本地文件</span>
        </label>
      </div>

      <!-- v1.1.0：JSON 子编辑器入口。字段指向外部 json 配置文件时显示。
           v1.4.0：远程模式按钮语义改为「下载 JSON」（fetch 远程 URL 并触发浏览器下载），
           本地模式维持「编辑 JSON / 新建 JSON」（打开子编辑器）。 -->
      <button
        v-if="jsonEditable"
        class="me-btn me-btn-sm json-edit-btn"
        type="button"
        :title="actionTitle"
        @click="onJsonAction"
      >
        <Download v-if="currentMode === 'remote'" :size="12" />
        <FileJson v-else :size="12" />
        {{ actionLabel }}
      </button>
    </div>

    <!-- v1.7.0：单行 input 改为自适应高度的 textarea —— 长 URL（带 query/长路径）在单行里
         只能看到前半段，改为可换行显示完整内容；高度随内容增长（上限见样式），
         Enter 阻止换行（URL 不应含换行符）。 -->
    <textarea
      v-if="currentMode === 'remote'"
      ref="urlTextareaRef"
      class="me-input me-input-mono url-input-multiline"
      :rows="1"
      spellcheck="false"
      :placeholder="placeholder"
      :value="value"
      @input="onUrlInput"
      @keydown.enter.prevent
    />

    <div v-else class="local-zone" @dragover.prevent @drop.prevent="onDrop">
      <div class="file-info">
        <FileText :size="14" />
        <span class="file-name me-mono">{{ displayLocalName }}</span>
        <span v-if="boundFile" class="file-size">{{ formattedSize }}</span>
      </div>
      <div class="file-actions">
        <button class="me-btn me-btn-sm" type="button" @click="onPickFile">
          <Upload :size="12" />
          {{ isLocalValue ? '替换文件' : '选择文件' }}
        </button>
        <button
          v-if="isLocalValue"
          class="me-btn me-btn-sm danger"
          type="button"
          title="移除本地文件登记"
          @click="onClearFile"
        >
          <Trash2 :size="12" />
          移除
        </button>
        <span class="drop-hint">
          <MousePointer2 :size="11" />
          也可拖拽到此区域
        </span>
      </div>
      <!-- 隐藏的真实 input -->
      <input ref="fileInputRef" class="hidden-file-input" type="file" :accept="accept || ''" @change="onFileChosen" />
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, watch, computed, nextTick, onMounted, onBeforeUnmount } from 'vue';
import { Globe, HardDrive, FileText, Upload, MousePointer2, Trash2, FileJson, Download } from 'lucide-vue-next';
import * as FileBundle from '../schema/file-bundle';
import {
  isWorkspaceMode,
  getWorkspaceRoot,
  getWorkspaceFileIndex,
  writeFileToDirectory,
  ensureReadWritePermission,
} from '../schema/assets-loader';
import { pushToast } from './Toast.vue';

const props = withDefaults(
  defineProps<{
    mode?: 'remote' | 'local';
    value?: string;
    placeholder?: string;
    modeName: string;
    /** 本地文件 zip 子目录（来自 FieldUrl.bundleDir）；未提供时 v0.7.0 起缺省归 assets */
    bundleDir?: string;
    /** input[type=file] 的 accept 属性（来自 FieldUrl.accept） */
    accept?: string;
    /** 是否可打开 JSON 子编辑器（来自 FieldUrl.jsonEditable）；为 true 时显示「编辑/新建 JSON」按钮 */
    jsonEditable?: boolean;
    /**
     * 字段值的「落盘基准目录」（相对项目根，带尾斜杠，如 'npcs/'）。
     *
     * 子编辑器内资源字段（modelFilePath/imagePath 等）的字段值语义是「相对 config 目录」，
     * 但 FileBundle key / 磁盘落盘路径需「相对项目根」= valueBaseDir + 字段值。
     * 主编辑器字段不传（默认 ''，字段值即相对项目根，key=字段值）。
     */
    valueBaseDir?: string;
  }>(),
  { mode: 'remote', value: '', placeholder: 'https://...', valueBaseDir: '' },
);

const emit = defineEmits<{
  (e: 'update:value', v: string): void;
  /** 用户点击「编辑 JSON / 新建 JSON」按钮；由上层打开子编辑器 */
  (e: 'open-json-editor'): void;
}>();

const currentMode = ref<'remote' | 'local'>(props.mode);
const fileInputRef = ref<HTMLInputElement | null>(null);

watch(
  () => props.mode,
  (m) => (currentMode.value = m),
);

/** 字段值是否为本地路径形态（决定本地模式下的展示与移除语义） */
const isLocalValue = computed(() => !!props.value && FileBundle.isLocalPath(props.value));
/** 本地模式文件名展示：非本地路径（如远程 URL）时显示占位，不误显远程链接 */
const displayLocalName = computed(() => (isLocalValue.value ? props.value : '尚未选择文件'));

/** 远程 URL 输入框（v1.7.0 起为 textarea，用于长 URL 换行显示完整） */
const urlTextareaRef = ref<HTMLTextAreaElement | null>(null);
/**
 * 自适应高度上限（**行数**）：最多撑到这么多行，超出则内部滚动，避免超长 URL 把面板撑得过高。
 * 用行数而非像素：行高随主题/字体变化（--me-fs-base / line-height），硬编码像素会失准。
 */
const URL_TEXTAREA_MAX_ROWS = 5;

const onUrlInput = (e: Event) => {
  const el = e.target as HTMLTextAreaElement;
  // 去掉换行：URL 不应含换行符（用户可能粘贴多行内容；Enter 已 prevent，此处兜住粘贴场景）
  const cleaned = el.value.replace(/[\r\n]+/g, '');
  if (cleaned !== el.value) el.value = cleaned;
  syncUrlTextareaHeight();
  emit('update:value', cleaned);
};

/** 按内容高度自适应（最多 URL_TEXTAREA_MAX_ROWS 行，超出内部滚动） */
function syncUrlTextareaHeight(): void {
  const el = urlTextareaRef.value;
  if (!el) return;
  // 测量前必须「复位高度 + 关闭纵向滚动」：
  // 若保留 overflow-y:auto，初始 rows=1 时内容装不下 → 出现滚动条 → 滚动条占掉内容宽度
  // → 换行后需要更多行 → scrollHeight 偏大（实测把两行内容量成 71px/三行）→ 设完高度滚动条消失、
  // 宽度恢复，于是多出一行空白。先隐藏滚动条即可测得真实内容高度。
  el.style.height = 'auto';
  el.style.overflowY = 'hidden';
  const contentHeight = el.scrollHeight;

  // 上限 = 行高 × 行数 + 上下 padding（scrollHeight 已含 padding，故只补 padding）
  const computed = getComputedStyle(el);
  const lineHeight = Number.parseFloat(computed.lineHeight);
  const paddingV =
    Number.parseFloat(computed.paddingTop) + Number.parseFloat(computed.paddingBottom);
  const maxHeight =
    Number.isFinite(lineHeight) && lineHeight > 0
      ? lineHeight * URL_TEXTAREA_MAX_ROWS + paddingV
      : contentHeight; // 行高取不到（normal 等）时不限高，退化为完全自适应

  // 幂等保护：目标值与当前一致时不写 DOM，避免与 ResizeObserver 互相触发
  const nextHeight = `${Math.min(contentHeight, maxHeight)}px`;
  if (el.style.height !== nextHeight) el.style.height = nextHeight;
  // 仅当内容超过行数上限时才启用滚动
  const nextOverflow = contentHeight > maxHeight ? 'auto' : 'hidden';
  if (el.style.overflowY !== nextOverflow) el.style.overflowY = nextOverflow;
}

// 外部值变化（切换字段、清空、子编辑器回填）与首次挂载时重新贴合高度
watch(() => props.value, () => void nextTick(syncUrlTextareaHeight));

/**
 * 尺寸观察器（v1.7.4）：侧边栏可拖拽伸缩 → 输入框宽度随之变化 → 换行数变化，
 * 必须重算高度；仅在 value / mode 变化时同步会漏掉这种场景（表现为「拖窄侧边栏后高度不对」）。
 *
 * 两个必须的规避：
 * 1. **观察父元素而非 textarea 自身** —— 回调里会修改 textarea 高度，若观察自身则
 *    高度变化再次触发观察 → 死循环。
 * 2. **仅在宽度变化时重算** —— 高度变化同样会触发 observer 回调（父元素随内容变高），
 *    用 lastObservedWidth 过滤可避免无谓重算与抖动。
 */
let resizeObserver: ResizeObserver | null = null;
let lastObservedWidth = 0;

onMounted(() => {
  void nextTick(syncUrlTextareaHeight);
  const parent = urlTextareaRef.value?.parentElement;
  if (!parent || typeof ResizeObserver === 'undefined') return;
  resizeObserver = new ResizeObserver((entries) => {
    const width = entries[0]?.contentRect.width ?? 0;
    if (width === lastObservedWidth) return;
    lastObservedWidth = width;
    syncUrlTextareaHeight();
  });
  resizeObserver.observe(parent);
});

onBeforeUnmount(() => {
  resizeObserver?.disconnect();
  resizeObserver = null;
});

// 模式切换（本地 ⇄ 远程）后重新贴合高度。
// 必要性：textarea 由 v-if 控制，切走时卸载、切回时**重新挂载**，而 UrlField 组件本身
// 并不重挂 → onMounted 不会再触发，且切模式不改 value（watch(value) 也不触发），
// 高度会停留在 CSS 默认的 rows=1（表现为「切回远程后输入框变低」）。
// watch 默认 flush:'pre'（DOM 更新前），配合 nextTick 可确保读到已挂载的 textarea。
watch(currentMode, (mode) => {
  if (mode === 'remote') void nextTick(syncUrlTextareaHeight);
});

// ==================== JSON 操作按钮（v1.4.0） ====================

/** 按钮文案：远程模式「下载 JSON」；本地模式依 value 是否为空切「编辑/新建 JSON」 */
const actionLabel = computed(() => {
  if (currentMode.value === 'remote') return '下载 JSON';
  return props.value ? '编辑 JSON' : '新建 JSON';
});

/** 按钮悬浮提示 */
const actionTitle = computed(() => {
  if (currentMode.value === 'remote') return '下载远程 URL 指向的 JSON 文件到本地';
  return props.value ? '编辑该 JSON 文件内容' : '新建空白 JSON 文件';
});

/** 按钮点击分发：远程→下载；本地→打开子编辑器 */
function onJsonAction(): void {
  if (currentMode.value === 'remote') {
    void onDownloadJson();
  } else {
    emit('open-json-editor');
  }
}

/**
 * 下载远程 URL 指向的 JSON 文件到本地（触发浏览器下载）。
 *
 * 远程 URL 指向的 json 内容无法在编辑器内直接编辑（需先落到本地磁盘），
 * 故远程模式下按钮语义由「编辑」改为「下载」。fetch 可能受 CORS 限制，
 * 失败时 toast 提示用户改用浏览器直接打开下载。
 */
async function onDownloadJson(): Promise<void> {
  const url = props.value;
  if (!url) {
    pushToast({ type: 'warn', message: '请先填写远程 JSON URL' });
    return;
  }
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`);
    const blob = await res.blob();
    const objectUrl = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = objectUrl;
    a.download = extractFileNameFromUrl(url);
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(objectUrl);
  } catch (err) {
    pushToast({
      type: 'error',
      title: '下载失败',
      message: (err as Error).message || String(err),
    });
  }
}

/** 从 URL pathname 提取文件名（无有效文件名时回退 config.json） */
function extractFileNameFromUrl(url: string): string {
  try {
    const u = new URL(url);
    const seg = u.pathname.split('/').filter(Boolean);
    const last = seg[seg.length - 1];
    if (last) return last;
  } catch {
    /* 非绝对 URL 等场景：回退默认名 */
  }
  return 'config.json';
}

/** 当前 value 在 FileBundle 中对应的 File（若已上传） */
const boundFile = computed(() => {
  if (!props.value || !FileBundle.isLocalPath(props.value)) return null;
  return FileBundle.get(props.value);
});

const formattedSize = computed(() => {
  if (!boundFile.value) return '';
  const size = boundFile.value instanceof File ? boundFile.value.size : boundFile.value.byteLength;
  return FileBundle.formatSize(size);
});

/**
 * v0.7.0：上传登记目录——字段声明了 bundleDir 用之；未声明（手写规则/infer 裸 url）统一归 assets。
 * v1.6.0：用 `??` 而非 `||`——chunked manifest 的 url 字段 bundleDir 显式为 ''（字段值=相对
 * baseUrl 的纯文件名），`|| 'assets'` 会误 fallback 成 assets 给字段值加目录前缀，破坏
 * SDK baseUrl+seg 语义。`??` 仅在 undefined（未声明）时归 assets。
 */
const effectiveDir = computed(() => props.bundleDir ?? 'assets');

const onPickFile = () => {
  fileInputRef.value?.click();
};

const onFileChosen = (e: Event) => {
  const input = e.target as HTMLInputElement;
  const file = input.files?.[0];
  if (!file) return;
  void registerLocalFile(file);
  // 重置 input 让连续选同一个文件也能触发
  input.value = '';
};

const onDrop = (e: DragEvent) => {
  const file = e.dataTransfer?.files?.[0];
  if (!file) return;
  void registerLocalFile(file);
};

/**
 * 实际执行登记：
 * 1) 如果当前 value 是本地路径，先从 FileBundle 移除（替换语义）
 * 2) 在 bundleDir 下生成不冲突的新路径
 * 3) 注册文件
 * 4) emit 新路径作为字段值
 *
 * **路径策略（A 案，2026-05 决策）**：
 * 不论当前字段值是空、远程 URL、还是 JSON 里写好的本地路径约定（如 `'./my-region/abc.json'`），
 * 用户上传/替换时，新文件路径**统一**走 `${bundleDir}/${safeFileName}`（如 `single-scene/xxx.json`）。
 *
 * 这意味着用户在 meta.json 里写的旧路径约定会被覆盖。原因：
 * - 编辑器有"打包目录"的统一规范（`single-scene/` `collision/`），与导出 zip 的目录结构对齐
 * - 智能保留旧目录会引入"用户路径 vs 规范目录"的二义性，行为不可预期
 * - 用户如果有特殊路径需求，应直接在 raw 模式编辑字段值
 *
 * 重名冲突由 `uniquePath` 自动加 `(1)` `(2)` 后缀处理，不会互相覆盖。
 *
 * **目录型配置例外（v2.32.0）**：jsonEditable 字段（regionReplaceConfigPath / configFile /
 * chunkedUrl）是指向「清单 json」的字段，清单内部用相对路径（baseUrl / ply_name /
 * collision_name / modelFilePath）引用其他资源，相对路径基准 = 清单文件自身所在目录。
 * 这类字段若也走 bundleDir 归一化（如塞进 `region-replace/`），会把清单移到子目录、
 * 使其内部相对路径推导基准错位一层，导致资源精确匹配永远失败、只能靠 basename 兜底。
 * 故 jsonEditable 字段上传时**不归 bundleDir，直接落根**（uniquePath 用空目录），
 * 让清单内部相对路径基准 = 根，与「授权清单所在目录」的语义对齐。
 */
async function registerLocalFile(file: File) {
  // v3.0.0 托管工作区模式：上传的文件直接落盘到授权目录（见 registerLocalFileHosted）
  if (isWorkspaceMode()) {
    await registerLocalFileHosted(file);
    return;
  }
  registerLocalFileSandbox(file);
}

/** 非托管（内存沙盒）模式：维持原有「登记进 FileBundle」逻辑 */
function registerLocalFileSandbox(file: File) {
  // 字段值：jsonEditable（目录型配置本体）落根 / 其余归 bundleDir（effectiveDir）。
  // 非托管模式与托管模式一致拆「字段值 relFieldValue」与「FileBundle key bundleKey」：
  // 子编辑器资源字段值相对 config 目录（valueBaseDir），但 key 需相对项目根 = valueBaseDir
  // + 字段值。否则导出 zip 时 collectLocalPathsInMeta 按 dirname(cfgPath)/baseUrl 推导出的
  // key 与登记 key 对不上 → 导出缺文件。
  const relFieldValue = props.jsonEditable
    ? FileBundle.uniquePath('', file.name)
    : FileBundle.uniquePath(effectiveDir.value, file.name);
  const bundleKey = FileBundle.joinRelativePath(props.valueBaseDir || '', relFieldValue);

  // v0.6.0 同源复用：同一物理文件（name+size+lastModified 全同）已被其他字段登记且 key 一致时，
  // 直接共享该路径（两字段指向同一份字节），不再重复登记生成 `(1)` 副本导致导出打包两份。
  // 必须放在 unregister 之前：共享路径正被其他字段引用，不能因本字段更换而清除。
  // markShared 让该路径进入共享保护：此后任意单字段的清除/替换都无法 unregister 它。
  const shared = FileBundle.findSameSource(file);
  if (shared && shared === bundleKey) {
    FileBundle.markShared(bundleKey);
    emit('update:value', relFieldValue);
    return;
  }
  unregisterCurrent();
  FileBundle.register(bundleKey, file);
  emit('update:value', relFieldValue);
}

/**
 * 托管工作区模式下的上传落盘。
 *
 * - 文件已在授权目录内（同源三元组比对命中）→ 复用磁盘相对路径（相对 meta 所在目录），
 *   不拷贝，路径显示保持原样。
 * - 文件在目录外 → 按字段规范子目录（jsonEditable 落根 / 其余 bundleDir）自动拷贝写盘，
 *   路径显示相对路径；写盘失败（权限/异常）降级为「仍登记进内存保预览 + 提示手动拷贝」。
 */
async function registerLocalFileHosted(file: File): Promise<void> {
  const root = getWorkspaceRoot();
  if (!root) {
    // 理论上 isWorkspaceMode 为真时 root 必然非空；兜底走沙盒
    registerLocalFileSandbox(file);
    return;
  }

  // 字段值（相对 config 目录或项目根，取决于 valueBaseDir）：uniquePath(bundleDir, 文件名)
  const relFieldValue = FileBundle.uniquePath(effectiveDir.value, file.name);
  // FileBundle key / 磁盘落盘路径（相对项目根）：加 valueBaseDir 前缀。
  // 子编辑器里 modelFilePath 字段值 = 'models/xxx.glb'（相对 npcs config 目录），
  // 落盘与登记 key 应为 'npcs/models/xxx.glb'（相对项目根），否则 preview 改写层按
  // joinRelativePath(dirname(cfgPath), 字段值) 找不到资源。
  const bundleKey = FileBundle.joinRelativePath(props.valueBaseDir || '', relFieldValue);

  // 目录内判定：文件是否已在规范位置 bundleKey（同源三元组比对）。命中则复用磁盘
  // 现有文件不重复拷贝；位置不符（在授权目录其他处）仍按 bundleKey 落盘规范位置。
  const inWorkspaceRel = await findInWorkspace(file);
  if (inWorkspaceRel && inWorkspaceRel === bundleKey) {
    unregisterCurrent();
    FileBundle.register(bundleKey, file);
    emit('update:value', relFieldValue);
    return;
  }

  // 目录外 / 位置不符：拷贝落盘到 bundleKey（按字段规范子目录）
  const ok = await copyIntoWorkspace(root, bundleKey, file);
  // 无论写盘成败都 register 进内存（保预览），失败仅降级提示手动拷贝
  unregisterCurrent();
  FileBundle.register(bundleKey, file);
  emit('update:value', relFieldValue);
  if (!ok) {
    pushToast({
      type: 'warn',
      title: '已登记但未落盘',
      message: `无法写入托管目录，请手动把文件「${file.name}」拷贝到：${bundleKey}`,
      duration: 6000,
    });
  }
}

/** 当前字段值对应的 FileBundle key（字段值相对 config 目录时需加 valueBaseDir 前缀） */
function currentBundleKey(): string {
  return FileBundle.joinRelativePath(props.valueBaseDir || '', props.value || '');
}

/** 清除当前字段的旧登记（共享保护由 unregister 内部处理） */
function unregisterCurrent(): void {
  if (props.value && FileBundle.isLocalPath(props.value)) {
    const key = currentBundleKey();
    if (FileBundle.has(key)) FileBundle.unregister(key);
  }
}

/** 在授权目录索引中查找与候选文件同源（name+size+lastModified 全同）的相对路径 */
async function findInWorkspace(file: File): Promise<string | null> {
  const idx = await getWorkspaceFileIndex();
  if (!idx) return null;
  for (const [rel, f] of idx) {
    if (f.name === file.name && f.size === file.size && f.lastModified === file.lastModified) {
      return rel;
    }
  }
  return null;
}

/** 把文件写入托管目录的相对路径（含读写权限确认），返回是否成功 */
async function copyIntoWorkspace(
  root: NonNullable<ReturnType<typeof getWorkspaceRoot>>,
  relPath: string,
  file: File,
): Promise<boolean> {
  try {
    await ensureReadWritePermission(root);
    await writeFileToDirectory(root, relPath, file);
    return true;
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn('[UrlField] 托管目录写入失败，降级手动拷贝：', err);
    return false;
  }
}

/** 移除按钮：清除登记 + 字段值清空 */
const onClearFile = () => {
  if (props.value && FileBundle.isLocalPath(props.value)) {
    // v0.6.0 共享保护：登记被多个字段共享时 unregister 返回 false（保留登记）。
    // 本字段仍清空为未选——共享的登记继续服务其他字段，整体清理只发生在 clear()。
    // 子编辑器字段值相对 config 目录，需加 valueBaseDir 前缀才是 FileBundle key。
    const key = currentBundleKey();
    if (FileBundle.has(key)) FileBundle.unregister(key);
  }
  emit('update:value', '');
};
</script>

