<script setup lang="ts">
import { ref, computed, watch, onMounted, onBeforeUnmount, shallowRef, nextTick } from 'vue';
import { Sparkles, Loader, AlertTriangle, MousePointer2 } from 'lucide-vue-next';
import { pushToast } from './Toast.vue';
import * as THREE from 'three';
import { TransformControls } from 'three/examples/jsm/controls/TransformControls.js';
import {
  ViewerSDK,
  lightModule,
  getModule,
  rendererModule,
  cameraModule,
  sceneModule,
  getWorldOrigin,
  subscribeWorldOrigin,
  normalizeAudioZone,
  normalizeInteractionZoneShape,
  loadTriangleMesh,
  raycast,
} from '@tencent/viewer-sdk';
import type {
  RendererModuleState,
  CameraModuleState,
  SceneState,
  EngineContext,
} from '@tencent/viewer-sdk';
import * as FileBundle from '../schema/file-bundle';
import { resolveResourceBundleDir } from '../schema/build-editor-rules';
import { isWorkspaceMode } from '../schema/assets-loader';
// v20260814（thirdroom ctx 对齐）：引入 provideEngineContext 把 ctx 注入到 Vue 注入树
import { provideEngineContext } from '../composables/useEngineContext';
import { parsePath } from '../schema/path-utils';
import {
  useGizmoBridge,
  notifyGizmoChangeWithPath,
  registerSdk,
  notifySceneReady,
  deactivateGizmo,
  setSuppressRebuild,
  getGizmoModeForPath,
  setPickResult,
  cancelPick,
  roundGizmoValue,
} from '../composables/useGizmoBridge';
import type { GizmoEntry, GizmoSource } from '../composables/useGizmoBridge';

const props = defineProps<{
  /** 整个 meta 对象（reactive） */
  value: any;
  /**
   * 目录型引用配置（regionReplaceConfigPath / npcs.configFile）内部资源补读挂起标记。
   * 属性面板上传该类 config 后，MetaEditor 会引导用户授权目录补读 config 内部引用
   * （地块 splat/glb、NPC 模型等）。挂起期间重建一律跳过，避免"资源未登记 → 改写
   * 保留相对路径 → SDK 拼出无效 blob URL 报 ERR_FILE_NOT_FOUND"的中间态；补读完成
   * 置 false 后由 watch 强制重建一次（此时 FileBundle 已填充）。
   */
  configPendingLoad?: boolean;
  /**
   * 当前子编辑器正在编辑的 config（FileBundle key）；未打开时为空串。
   *
   * 用于跳过「改了也不影响画面」的重建：draft 写回本身无法判断配置有没有消费方，
   * 需结合该字段 + meta 判断（见 isEditingUnconsumedConfig）。
   */
  editingConfigPath?: string;
  /**
   * 子编辑器栈深（1 = 根层，≥2 = 嵌套层）；未打开时为 0。
   *
   * 用于跳过「嵌套层 draft 写回」引发的无收益重建：非根层子配置（L2 manifest / L3 spawn config）
   * 在 creative 预览下没有消费方（NPC 模块未装配、永不加载），其草稿写回只改 FileBundle 内容，
   * 整场重建不产生任何可见变化。详见 shouldSkipRebuildForNestedDraft()。
   */
  editingConfigDepth?: number;
}>();

const containerRef = ref<HTMLDivElement | null>(null);

/** 点击预览面板时失焦属性面板输入框，避免输入框残留焦点 */
function onPanelPointerDown(): void {
  const el = document.activeElement;
  if (el && el instanceof HTMLInputElement && el.tagName === 'INPUT') {
    el.blur();
  }
}

// ==================== 渲染状态 ====================

type RenderStatus = 'idle' | 'loading' | 'ready' | 'error' | 'unconfigured';
const status = ref<RenderStatus>('unconfigured');
const errorMessage = ref<string>('');

const statusLabel = computed(() => {
  switch (status.value) {
    case 'unconfigured':
      return '尚未配置高斯泼溅场景';
    case 'loading':
      return '加载场景中...';
    case 'ready':
      return '实时预览';
    case 'error':
      return '渲染异常';
    default:
      return '空闲';
  }
});

const statusDotClass = computed(() => {
  switch (status.value) {
    case 'ready':
      return 'ok pulse';
    case 'loading':
      return 'loading pulse';
    case 'error':
      return 'err';
    default:
      return 'idle';
  }
});

const backendLabel = computed(() => props.value?.gaussianSplatting?.gaussianComponentType || '-');

const renderModeLabel = computed(() => {
  const gs = props.value?.gaussianSplatting;
  if (!gs) return '未配置';
  if (gs.singleSceneConfigPath) return '单场景 (singleScene)';
  if (gs.regionReplaceConfigPath) return '区域替换 (regionReplace)';
  return '未配置 GS 路径';
});

/** 遮罩状态：null 表示不显示遮罩；其它值显示对应内容 */
type OverlayState = null | 'unconfigured' | 'loading' | 'error';
const overlayState = computed<OverlayState>(() => {
  if (status.value === 'unconfigured') return 'unconfigured';
  if (status.value === 'error') return 'error';
  if (status.value === 'loading') return 'loading';
  return null;
});

const overlayIcon = computed(() => {
  if (overlayState.value === 'error') return AlertTriangle;
  if (overlayState.value === 'unconfigured') return MousePointer2;
  return Sparkles;
});

const overlayTitle = computed(() => {
  switch (overlayState.value) {
    case 'unconfigured':
      return '高斯泼溅 3D 预览';
    case 'loading':
      return '正在加载场景';
    case 'error':
      return '渲染失败';
    default:
      return '';
  }
});

const overlayDesc = computed(() => {
  switch (overlayState.value) {
    case 'unconfigured':
      return [
        '请在 gaussianSplatting 中配置:',
        '<b>singleSceneConfigPath</b> 单场景路径，或',
        '<b>regionReplaceConfigPath</b> 区域替换 JSON',
      ].join('<br/>');
    case 'loading':
      return '首次加载需要解析高斯泼溅配置和拉取场景资源...';
    case 'error': {
      // 错误消息可能含 \n（如本地 .rad 不支持的提示），需要转 <br/> 让 v-html 正确换行；
      // 同时简单转义 < > 防止用户的错误消息含 HTML 注入风险（Error.message 通常不含 HTML，
      // 但保险起见——这里只为 PreviewPanel 自己的 throw 消息服务）
      const raw = errorMessage.value || '请查看控制台日志获取详情';
      return raw.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br/>');
    }
    default:
      return '';
  }
});

// ==================== SDK 生命周期 ====================

/**
 * SDK 实例与持有的资源。
 *
 * 用 shallowRef 而非 ref：SDK 实例自身有大量内部状态/Three.js 引用，深响应化既无意义
 * 又有性能风险（Vue 会递归代理所有属性）。我们只关心引用替换，不关心内部字段变更。
 */
const sdkRef = shallowRef<ViewerSDK | null>(null);

// v20260814（thirdroom ctx 对齐）：engineCtxRef 是 ctx 的「唯一原始供料点」，
// rebuildSdk 内 await sdk.init() + sdk.animate() 后写入 ctx，provideEngineContext
// 注入给下游子组件 / composable useEngineContext() 消费。
// 当前 PreviewPanel 内部 SDK 使用完全内聚（无 ctx 下传），本字段为「未来扩展锚点」
// 铺路：meta-editor 若引入下游子组件消费 ctx（如 DebugPanel 类似的 ECS state 直读面板），
// 直接 useEngineContext() 即可拿到 ctx，与 sdk 实例完全解耦。
const engineCtxRef = ref<EngineContext | undefined>(undefined);
provideEngineContext(engineCtxRef);
/** 当前活动的 blob URL 列表（meta.json + 各资源 blob），重建时统一 revoke */
let activeBlobUrls: string[] = [];

/**
 * 判定 meta 是否"足够渲染高斯泼溅场景"。
 *
 * 条件：gaussianSplatting 存在，且至少有 singleSceneConfigPath 或 regionReplaceConfigPath
 * 任一非空字符串。
 */
function canRender(meta: any): boolean {
  const gs = meta?.gaussianSplatting;
  if (!gs || typeof gs !== 'object') return false;
  const single = typeof gs.singleSceneConfigPath === 'string' && gs.singleSceneConfigPath.trim();
  const region = typeof gs.regionReplaceConfigPath === 'string' && gs.regionReplaceConfigPath.trim();
  return Boolean(single || region);
}

function toVec3Tuple(value: unknown, fallback: [number, number, number]): [number, number, number] {
  if (Array.isArray(value)) {
    return [
      numberOrFallback(value[0], fallback[0]),
      numberOrFallback(value[1], fallback[1]),
      numberOrFallback(value[2], fallback[2]),
    ];
  }
  if (value && typeof value === 'object') {
    const v = value as Record<string, unknown>;
    return [numberOrFallback(v.x, fallback[0]), numberOrFallback(v.y, fallback[1]), numberOrFallback(v.z, fallback[2])];
  }
  return fallback;
}

function numberOrFallback(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

/**
 * 把 meta 中支持本地的字段从相对路径替换成 blob URL（FileBundle 里有对应文件时）。
 *
 * **关键**：SDK 的 ConfigManager.resolveUrl 看到 blob:/http(s):/data: 前缀会直接返回，
 * 不会再做 baseUrl 拼接。所以只要我们提前把所有本地路径转成 blob URL，SDK 就能直接 fetch。
 *
 * 远程 URL（http(s)://）保持原样不动。
 *
 * @returns 处理后的 config 副本 + 新创建的 blob URL 列表（用于 revoke）
 */
/**
 * 在 SDK config 副本上补"渲染必选"字段的默认值。
 *
 * 仅作用于传给 SDK 的 deep-clone 副本，**不修改 meta**，因此不会污染用户的原始配置；
 * 用户在属性面板里看到的还是原汁原味的 meta，导出也是 meta。
 *
 * 必选清单来源：scripts 目录下的"必选字段分析报告"；以下字段在 SDK creative 模式下必须存在：
 * - `name` / `rendererScale` / `debugger` / `meterScale`：ConfigManager 直接读
 * - `gaussianSplatting.gaussianComponentType`：策略选择
 * - `gaussianSplatting.transform.{position,rotation,scale}`：Three.js 矩阵直接 join
 * - `initial.player.transform.{position,rotation,scale}`：玩家初始 transform
 *
 * 互斥字段（singleSceneConfigPath / regionReplaceConfigPath）不补——这是用户必须显式配置的；
 * 缺失时 canRender 会先短路返回，根本不会进到这里。
 */
function applyRenderDefaults(config: any): void {
  if (!config || typeof config !== 'object') return;

  if (typeof config.name !== 'string') config.name = '未命名';
  if (typeof config.rendererScale !== 'number') config.rendererScale = 1;
  if (typeof config.debugger !== 'boolean') config.debugger = false;
  if (typeof config.meterScale !== 'number') config.meterScale = 1;

  // v1.21.0：编辑器预览禁用 official program（返回按钮 / 全屏按钮 / debug 面板 / Toast-Confirm overlay）。
  // SDK zero-config：config.programs 缺省时自动注入 official（sdk/index.ts ~1197）。编辑器预览不需要这些
  // H5 场景页 UI（且 creative 模式角色不加载，debug 面板无意义）。空对象 {} 是 truthy，会让 SDK 走
  // `config.programs || {official}` 时取到 {} → programHost.init({}) 零 program 注册。
  // 仅作用于本函数的 config 副本（transformLocalPathsToBlobUrls 深拷贝产物），不回写 meta——
  // 导出的 meta.json 不含 programs 字段，H5 场景页仍走 zero-config 加载 official，按钮不受影响。
  config.programs = {};

  // gaussianSplatting 子树
  const gs = config.gaussianSplatting;
  if (gs && typeof gs === 'object') {
    if (typeof gs.gaussianComponentType !== 'string' || !gs.gaussianComponentType) {
      gs.gaussianComponentType = 'spark';
    }
    if (!gs.transform || typeof gs.transform !== 'object') gs.transform = {};
    if (!Array.isArray(gs.transform.position)) gs.transform.position = [0, 0, 0];
    if (!Array.isArray(gs.transform.rotation)) gs.transform.rotation = [0, 0, 0];
    if (!Array.isArray(gs.transform.scale)) gs.transform.scale = [1, 1, 1];
    // SDK 还会读 renderOrder/sphericalHarmonicsDegree/showLoadingUI（虽然类型必选但有兜底）
    if (typeof gs.renderOrder !== 'number') gs.renderOrder = 0;
    if (typeof gs.sphericalHarmonicsDegree !== 'number') gs.sphericalHarmonicsDegree = 2;
    if (typeof gs.showLoadingUI !== 'boolean') gs.showLoadingUI = true;
  }

  // initial.player.transform：预览副本里兜底新格式，同时兼容旧 position/rotation 输入。
  if (!config.initial || typeof config.initial !== 'object') config.initial = {};
  const initial = config.initial;
  if (!initial.player || typeof initial.player !== 'object') initial.player = {};
  const player = initial.player;
  if (!player.transform || typeof player.transform !== 'object' || Array.isArray(player.transform)) {
    player.transform = {};
  }
  player.transform.position = toVec3Tuple(player.transform.position, toVec3Tuple(player.position, [0, 0, 0]));
  player.transform.rotation = toVec3Tuple(player.transform.rotation, toVec3Tuple(player.rotation, [0, 0, 0]));
  player.transform.scale = toVec3Tuple(player.transform.scale, [1, 1, 1]);
  delete player.position;
  delete player.rotation;
}

/**
 * 提取路径的扩展名（含 .），如 'single-scene/scene.splat' → '.splat'。
 * 取不到（如纯目录名）返回空字符串。
 */
function extractExtension(path: string): string {
  const last = path.split(/[\\/]/).pop() || '';
  const dot = last.lastIndexOf('.');
  return dot > 0 ? last.slice(dot) : '';
}

/**
 * 该格式是否需要"真实 URL"（不能用 blob URL）。
 *
 * spark 的 PagedSplats（处理 .rad/.radc 流式 LOD）通过 `rootUrl` 按约定请求分块文件
 * （如 `rootUrl/page0.rad`、`rootUrl/page1.rad`），blob URL 没有"目录语义"也没有可拼接的
 * 路径段，导致：
 * - rootUrl 末尾没扩展名 → 内部 getFileExtension 返回空 → throw "Unable to determine file type"
 * - 即使绕过格式识别，分块请求也会构造出非法 URL（blob:http://.../uuid/page0.rad）
 *
 * 所以这类格式必须用真实的 absolute URL（http(s)://...），由 dev server / CDN 提供分块。
 *
 * 当前判定列表：rad / radc。其它格式（splat/ply/ksplat/spz）单文件加载，blob URL 仍可用。
 */
function isStreamingLodFormat(path: string): boolean {
  const ext = extractExtension(path).toLowerCase();
  return ext === '.rad' || ext === '.radc';
}

/**
 * 去掉路径中的目录前缀，只保留文件名（如 'single-scene/x.splat' → 'x.splat'）。
 * 用于构造 blob URL 的 hash 提示，让 SDK 的 endsWith 识别能通过。
 */
function stripDirPrefix(path: string): string {
  return path.split(/[\\/]/).pop() || path;
}

/**
 * 把 meta 中支持本地的字段从相对路径替换成 SDK 能直接 fetch 的绝对 URL。
 *
 * **关键**：SDK 拿到的 sceneUrl 是个 blob URL（meta.json blob），它的 baseUrl 提取结果是
 * `blob:<origin>/`——若字段值是相对路径如 `./xxx/y.splat`，
 * `new URL('./xxx', 'blob:http://localhost/abc')` 会产出非法拼接（如 `blob:http://localhost/xxx/y.splat`），
 * fetch 必败。所以**任何相对路径**都必须在传给 SDK 之前转成 absolute URL。
 *
 * 策略（按优先级）：
 * 1) FileBundle 中有文件 → `URL.createObjectURL(file)` 转 blob URL（无网请求，最可靠）
 * 2) FileBundle 没文件但路径是"本地路径形态"（不是 http/blob）：
 *    a) 用 `document.baseURI` 解析为 absolute URL
 *    b) HEAD 探测：若响应是 HTML（被 SPA 路由兜底），视为不可用 → 清空字段
 *       （否则 SDK 会拿到 HTML 当 splat 数据解析，触发 THREE.DataUtils 崩溃）
 *    c) 探测通过 → 用 absolute URL 替换字段值
 * 3) 已经是 absolute URL（http(s)/blob/data） → 不动
 *
 * **异步**：因为 HEAD 探测涉及网络请求，整个函数返回 Promise。
 *
 * @returns 处理后的 config 副本 + 新创建的 blob URL 列表（用于 revoke）
 */
async function transformLocalPathsToBlobUrls(meta: any): Promise<{
  config: any;
  blobUrls: string[];
}> {
  const config = JSON.parse(JSON.stringify(meta));
  // 关键：渲染前补必选字段（仅作用于本次 SDK 用的 config 副本，不回写 meta）
  // 这一步与编辑器属性面板"显示即数据"契约**解耦**——属性面板里用户看到什么就只编辑什么；
  // SDK 渲染需要某些字段（即使用户没填）必须有兜底值，否则 init 会抛错。
  applyRenderDefaults(config);
  // unified-shape-trigger-ecs 阶段一：Shape 归一化（shape ↔ geometry/model、center/radius/size 双向同步）。
  // SDK 运行时（阶段三前）仍消费旧字段，副本上补齐保证预览与导出语义一致。
  normalizeShapeNodes(config);
  const blobUrls: string[] = [];

  /** 探测一个 absolute URL 是否真实可用：HEAD 判 200 + Content-Type 不是 HTML */
  const probeUrl = async (url: string): Promise<boolean> => {
    try {
      // 优先 HEAD（轻量），dev server 不支持 HEAD 时回落到 Range GET（拉 1 字节）
      let resp = await fetch(url, { method: 'HEAD' });
      // 某些 dev server（比如 vite）对 HEAD 仍走 SPA fallback 返回 200 + HTML，
      // 所以即使 200 也要看 Content-Type
      if (!resp.ok) return false;
      let ct = resp.headers.get('content-type') || '';
      if (/^text\/html\b/i.test(ct)) return false;
      // HEAD 拿不到正确 ct（部分服务器返回空）→ 用 Range GET 试探一下
      if (!ct) {
        resp = await fetch(url, { headers: { Range: 'bytes=0-1' } });
        if (!resp.ok && resp.status !== 206) return false;
        ct = resp.headers.get('content-type') || '';
        if (/^text\/html\b/i.test(ct)) return false;
      }
      return true;
    } catch {
      return false;
    }
  };

  const tryReplace = async (pathRef: { obj: any; key: string }) => {
    const value = pathRef.obj[pathRef.key];
    if (typeof value !== 'string' || !value) return;
    if (!FileBundle.isLocalPath(value)) return; // 已是 http(s)/blob/data → 不动

    // 优先确定 baseUrl：远程导入时 FileBundle.getAssetsBaseUrl() 会有值（.json 所在目录），
    // 否则回落到 document.baseURI（dev server 根 / 本地导入场景）
    const assetsBase = FileBundle.getAssetsBaseUrl();
    const baseUrl = assetsBase || document.baseURI;

    // ============= 流式 LOD 格式（rad/radc）：必须走真实 URL =============
    // spark 的 PagedSplats 拒绝接受 blob URL（参见 isStreamingLodFormat 注释）。
    // 即使 FileBundle 里有这个文件，我们也不能给 SDK blob URL——只能拼 absolute URL，
    // 让 SDK 自己去 dev server / CDN 请求（分块加载）。
    // FileBundle 里的副本仍然保留，作为"导出 zip 的来源"，不影响导出。
    //
    // **本地导入场景的特殊处理**：本地磁盘上的 .rad 没有 HTTP 服务托管，spark 的分块
    // range 请求无处可发——这种情况无法预览。提前抛错给外层 catch，转入"渲染失败"
    // 状态并显示明确提示，避免让用户对着空白场景一头雾水。
    if (isStreamingLodFormat(value)) {
      // 判定"是否能给出可访问的 absolute URL"：
      // - 远程导入：assetsBaseUrl 是 http(s)://...，可以拼出真实 URL
      // - 本地（webkitdir / FS Access API）：FileBundle 有字节，但没有 HTTP 路径
      // - dev server 静态托管：document.baseURI 是 http(s)://localhost/...，能尝试拼，HEAD 探测决定
      const hasRemoteBase = !!assetsBase && /^https?:\/\//i.test(assetsBase);
      const hasFileBundleEntry = FileBundle.has(value);

      // 本地导入场景：FileBundle 有，但没有可用的 HTTP base URL
      // → 直接进入失败态，用户友好提示
      if (hasFileBundleEntry && !hasRemoteBase) {
        const fileName = stripDirPrefix(value);
        throw new Error(
          `本地导入暂不支持流式 LOD 格式（${fileName}）。\n` +
            `${extractExtension(value).toUpperCase().slice(1) || 'RAD'} 文件采用按需分块加载，需要文件托管在 HTTP 服务器上才能播放。\n\n` +
            `解决方法（任选其一）：\n` +
            `· 把项目托管到本地 dev server / CDN，再用"远程 URL 导入"\n` +
            `· 用 "${fileName.replace(/\.radc?$/i, '')}.splat" 等单文件格式替代 .rad`,
        );
      }

      let absoluteUrl: string;
      try {
        absoluteUrl = new URL(value, baseUrl).href;
      } catch {
        pathRef.obj[pathRef.key] = '';
        // eslint-disable-next-line no-console
        console.warn(`[PreviewPanel] 字段 ${pathRef.key} 路径无法解析为 URL："${value}"，已清空`);
        return;
      }

      const ok = await probeUrl(absoluteUrl);
      if (!ok) {
        pathRef.obj[pathRef.key] = '';
        // eslint-disable-next-line no-console
        console.warn(
          `[PreviewPanel] 字段 ${pathRef.key} = "${value}" 在 ${baseUrl} 上不可用` +
            `（HEAD 探测失败 / 返回 HTML），已清空。\n` +
            `rad/radc 格式必须真实托管在可访问的 URL 上（spark PagedSplats 不接受 blob URL）。`,
        );
        return;
      }
      pathRef.obj[pathRef.key] = absoluteUrl;
      return;
    }

    // ============= 其它格式（splat/ply/ksplat/spz/glb 等）：FileBundle blob 优先 =============

    // Path 1：FileBundle 中有 → blob URL
    const file = FileBundle.get(value);
    if (file) {
      const blob = file instanceof Blob ? file : new Blob([file as BlobPart], { type: 'application/octet-stream' });
      let url = URL.createObjectURL(blob);

      // **关键 hack**：SDK 的 SparkComponent.detectResourceHint 用 url.endsWith('.splat'/.ply/...)
      // 判断格式。blob URL 是 `blob:http://.../uuid` 不带扩展名 → 识别为 'unknown' →
      // 后续 PackedSplats 拿到 fileType=undefined 抛 "Unknown splat file type: undefined"。
      //
      // 解决：把 FileBundle 路径的扩展名（如 'single-scene/scene.splat' 的 '.splat'）作为
      // hash 附加到 blob URL 末尾。SDK 内部 split('?')[0] 不会去掉 hash，endsWith 仍能命中。
      // 浏览器 fetch blob URL 时 hash 会被忽略，正常拿到内容。
      //
      // 注：流式 LOD 格式（rad/radc）已经在上面走 absolute URL 分支返回了，不会到这里。
      const ext = extractExtension(value);
      if (ext) url = `${url}#${encodeURIComponent(stripDirPrefix(value))}`;

      blobUrls.push(url);
      pathRef.obj[pathRef.key] = url;
      return;
    }

    // Path 2：FileBundle 没有 → 解析为 absolute URL 并探测
    let absoluteUrl: string;
    try {
      absoluteUrl = new URL(value, baseUrl).href;
    } catch {
      pathRef.obj[pathRef.key] = '';
      // eslint-disable-next-line no-console
      console.warn(`[PreviewPanel] 字段 ${pathRef.key} 路径无法解析为 URL："${value}"，已清空`);
      return;
    }

    const ok = await probeUrl(absoluteUrl);
    if (!ok) {
      pathRef.obj[pathRef.key] = '';
      // eslint-disable-next-line no-console
      console.warn(
        `[PreviewPanel] 字段 ${pathRef.key} = "${value}" 在 ${baseUrl} 上不可用` +
          `（HEAD 探测失败 / 返回 HTML），已清空。\n` +
          `请在编辑器里手工上传该文件，或确保 dev server 静态托管了对应资源。`,
      );
      return;
    }

    pathRef.obj[pathRef.key] = absoluteUrl;
    // eslint-disable-next-line no-console
    console.info(`[PreviewPanel] 字段 ${pathRef.key} 在 FileBundle 中未找到，回落到 absolute URL：${absoluteUrl}`);
  };

  /**
   * region-replace-config.json 的本地预览：内容改写（v1.21.0）。
   *
   * 与单文件 tryReplace 不同，region-replace 是「目录型引用」配置：
   * - 仅把 config.json 转 blob 不够——config 内部 modules[].ply_name / collision_name /
   *   mortonConfig 相对 config.baseUrl 引用各地块文件，blob URL 没有目录语义，
   *   SDK 基于 blob 基地址解析相对路径必然失败（fetch 404）。
   * - 因此读取 config 内容，把内部引用的本地资源改写为 blob URL
   *   （SDK resolveFileSegToUrl 对绝对 URL 原样透传），再序列化回 blob。
   * - 流式 LOD 格式（rad/radc）spark 拒绝 blob URL，保持相对路径原样：
   *   该地块 SDK 加载失败，但其余 splat/glb 地块可正常预览。
   */
  const tryReplaceRegionReplaceConfig = async (pathRef: { obj: any; key: string }): Promise<void> => {
    const rrValue = pathRef.obj[pathRef.key];
    if (typeof rrValue !== 'string' || !rrValue) return;
    if (!FileBundle.isLocalPath(rrValue)) return;
    const rrFile = FileBundle.get(rrValue);
    if (!rrFile) {
      // config 未登记：回落单文件 absolute URL 探测
      await tryReplace(pathRef);
      return;
    }
    let text: string;
    try {
      text =
        rrFile instanceof Blob
          ? await new Response(rrFile).text()
          : new TextDecoder('utf-8').decode(rrFile as Uint8Array);
    } catch {
      await tryReplace(pathRef);
      return;
    }
    let parsed: any;
    try {
      parsed = JSON.parse(text);
    } catch {
      await tryReplace(pathRef);
      return;
    }
    if (!parsed || typeof parsed !== 'object' || !Array.isArray(parsed.modules)) {
      await tryReplace(pathRef);
      return;
    }

    const rrDirBase = FileBundle.dirname(rrValue);
    const rrBase = FileBundle.joinRelativePath(rrDirBase, typeof parsed.baseUrl === 'string' ? parsed.baseUrl : './');
    const rrFileType = typeof parsed.fileType === 'string' ? parsed.fileType : '';

    /** 单个资源段 → 本地 blob URL；非本地 / 流式格式 / FileBundle 缺失 → 原样保留 */
    const rewrite = (seg: string): string => {
      if (typeof seg !== 'string' || !seg) return seg;
      const rel = FileBundle.resolveFileSegToRelPath(seg, rrBase, rrFileType);
      if (!rel) return seg; // 绝对 URL → 原样
      const target = FileBundle.get(rel);
      if (!target) {
        // v2.34.1 托管模式：meta 目录即真相源，未登记 = 磁盘缺失 → 清空资源段，
        // 让 SDK 跳过该地块，避免拼真实路径请求产生 404 网络报错噪音。
        // （缺失提示已由 MetaEditor 补读阶段的 toast「配置内部资源缺失」承担，这里静默。）
        if (isWorkspaceMode()) return '';
        // v1.23.0：未登记 → 明确日志，引导用户授权目录加载 config 内部资源
        // （属性面板单独上传 config.json 时内部地块文件未登记，需走授权补读）。
        console.warn(
          `[PreviewPanel] region-replace 内部资源未登记（无法改写为 blob）：${rel}\n` +
            '如已通过属性面板上传 config，请按提示授权目录加载地块资源。',
        );
        return seg; // 原样保留（SDK 尝试按真实路径加载）
      }
      if (isStreamingLodFormat(rel)) return seg; // rad/radc 拒绝 blob URL
      const blob =
        target instanceof Blob ? target : new Blob([target as BlobPart], { type: 'application/octet-stream' });
      const url = URL.createObjectURL(blob);
      blobUrls.push(url);
      // 附扩展名 hash，让 SDK 的 detectResourceHint（url.endsWith('.splat'...)）能识别格式
      return `${url}#${encodeURIComponent(FileBundle.normalizePath(rel))}`;
    };

    for (const mod of parsed.modules as any[]) {
      if (!mod || typeof mod !== 'object') continue;
      const name = typeof mod.name === 'string' ? mod.name : '';
      // ply_name：数组 / 字符串 / 缺省回退 name
      if (Array.isArray(mod.ply_name)) {
        mod.ply_name = mod.ply_name.map(rewrite).filter((s: string) => s !== '');
      } else if (typeof mod.ply_name === 'string') {
        mod.ply_name = rewrite(mod.ply_name);
      } else if (name) {
        mod.ply_name = rewrite(name);
      }
      // collision_name：碰撞 GLB。
      // 托管模式缺失段被 rewrite 清空成 ''，必须过滤掉空段——SDK tryLoadRegionCollisionModules
      // 对 collision_name 不过滤空值，空串经 resolveCollisionUrl('') → new URL('', baseUrl)
      // 会解析成 baseUrl 目录本身（请求目录 → 404），而非目标 .glb 文件。
      if (Array.isArray(mod.collision_name)) {
        mod.collision_name = mod.collision_name.map(rewrite).filter((s: string) => s !== '');
      }
      // mortonConfig
      if (typeof mod.mortonConfig === 'string' && mod.mortonConfig) {
        mod.mortonConfig = rewrite(mod.mortonConfig);
      }
    }

    // 改写后序列化 → blob URL（config 本体）
    const configBlob = new Blob([JSON.stringify(parsed)], { type: 'application/json' });
    const configUrl = URL.createObjectURL(configBlob);
    blobUrls.push(configUrl);
    pathRef.obj[pathRef.key] = configUrl;
  };

  /**
   * npcs.configFile 的本地预览：内容改写（v1.22.0）。
   *
   * 与 region-replace 同理：config 内部 models[].modelFilePath / imagePath 相对 config
   * 所在目录引用，blob URL 无目录语义——需读取 config 内容，把白名单字段（复用
   * resolveResourceBundleDir 单一真相源）引用的本地资源改写为 blob URL，再序列化回 blob。
   * SDK loadNPCsConfigFile fetch(blobUrl) 拿到改写后的 config，模型/贴图 URL 均绝对可加载。
   */
  const tryReplaceNpcsConfig = async (pathRef: { obj: any; key: string }): Promise<void> => {
    const cfgValue = pathRef.obj[pathRef.key];
    if (typeof cfgValue !== 'string' || !cfgValue) return;
    if (!FileBundle.isLocalPath(cfgValue)) return;
    const cfgFile = FileBundle.get(cfgValue);
    if (!cfgFile) {
      await tryReplace(pathRef);
      return;
    }
    let text: string;
    try {
      text =
        cfgFile instanceof Blob
          ? await new Response(cfgFile).text()
          : new TextDecoder('utf-8').decode(cfgFile as Uint8Array);
    } catch {
      await tryReplace(pathRef);
      return;
    }
    let parsed: any;
    try {
      parsed = JSON.parse(text);
    } catch {
      await tryReplace(pathRef);
      return;
    }
    if (!parsed || typeof parsed !== 'object') {
      await tryReplace(pathRef);
      return;
    }

    const baseDir = FileBundle.dirname(cfgValue);
    const stack: unknown[] = [parsed];
    const visited = new Set<object>();
    while (stack.length > 0) {
      const node = stack.pop();
      if (!node || typeof node !== 'object') continue;
      if (visited.has(node as object)) continue;
      visited.add(node as object);
      if (Array.isArray(node)) {
        for (const item of node) stack.push(item);
        continue;
      }
      for (const [field, v] of Object.entries(node as Record<string, unknown>)) {
        if (v !== null && typeof v === 'object') {
          stack.push(v);
          continue;
        }
        if (typeof v !== 'string' || !v) continue;
        if (resolveResourceBundleDir(field.toLowerCase()) === null) continue;
        const rel = FileBundle.isLocalPath(v) ? FileBundle.joinRelativePath(baseDir, v) : v;
        if (!FileBundle.isLocalPath(rel)) continue;
        const target = FileBundle.get(rel);
        if (!target) continue;
        if (isStreamingLodFormat(rel)) continue; // 防御：NPC 模型无 rad，但保持统一策略
        const blob =
          target instanceof Blob ? target : new Blob([target as BlobPart], { type: 'application/octet-stream' });
        const url = URL.createObjectURL(blob);
        blobUrls.push(url);
        (node as Record<string, unknown>)[field] = `${url}#${encodeURIComponent(FileBundle.normalizePath(rel))}`;
      }
    }

    const configBlob = new Blob([JSON.stringify(parsed)], { type: 'application/json' });
    const configUrl = URL.createObjectURL(configBlob);
    blobUrls.push(configUrl);
    pathRef.obj[pathRef.key] = configUrl;
  };

  /**
   * 深度遍历 JSON 子树，把「资源字段」（复用 resolveResourceBundleDir 单一真相源）引用的
   * 本地相对路径改写为 blob URL。与 tryReplaceNpcsConfig 内部遍历同逻辑，抽取供 chunked
   * npcs 的 configFile 第二层复用。
   *
   * @param root 遍历起点（通常是 config 解析对象）
   * @param baseDir 相对路径的基准目录（FileBundle key）
   * @returns 是否发生了任何改写（调用方据此决定是否重新序列化）
   */
  const rewriteLocalResourceRefsDeep = (root: unknown, baseDir: string): boolean => {
    let changed = false;
    const stack: unknown[] = [root];
    const visited = new Set<object>();
    while (stack.length > 0) {
      const node = stack.pop();
      if (!node || typeof node !== 'object') continue;
      if (visited.has(node as object)) continue;
      visited.add(node as object);
      if (Array.isArray(node)) {
        for (const item of node) stack.push(item);
        continue;
      }
      for (const [field, v] of Object.entries(node as Record<string, unknown>)) {
        if (v !== null && typeof v === 'object') {
          stack.push(v);
          continue;
        }
        if (typeof v !== 'string' || !v) continue;
        if (resolveResourceBundleDir(field.toLowerCase()) === null) continue;
        const rel = FileBundle.isLocalPath(v) ? FileBundle.joinRelativePath(baseDir, v) : v;
        if (!FileBundle.isLocalPath(rel)) continue;
        const target = FileBundle.get(rel);
        if (!target) continue;
        if (isStreamingLodFormat(rel)) continue; // rad/radc 拒绝 blob URL
        const blob =
          target instanceof Blob ? target : new Blob([target as BlobPart], { type: 'application/octet-stream' });
        const url = URL.createObjectURL(blob);
        blobUrls.push(url);
        (node as Record<string, unknown>)[field] = `${url}#${encodeURIComponent(FileBundle.normalizePath(rel))}`;
        changed = true;
      }
    }
    return changed;
  };

  /**
   * chunked 分块清单（collision / terrain / npcs）的本地预览：内容改写（v1.29.0）。
   *
   * 背景：chunkedUrl 只把 manifest 转 blob 不够——SDK ChunkedLoadStrategy fetch(manifestUrl)
   * 拿到清单后，模块 URL 按 `baseUrl + url` **纯前缀拼接**（collision-dimension / terrain
   * dimension / npc buildChunkModule），不消化 ../、不认 blob: 开头的绝对 URL。因此：
   * - manifest.baseUrl 已本地化（导出前改写为相对镜像路径，zip 导入后也是相对值）：
   *   逐模块段推导镜像 key（与 collect 端 extractChunkedManifestResourcePaths 同
   *   joinRelativePath），FileBundle 命中 → 段改写为 blob URL，并把 manifest.baseUrl 置空串
   *   （SDK 拼接 `'' + blob:` = blob URL 可 fetch）；相对段全部命中才置空 baseUrl。
   * - manifest.baseUrl 仍为绝对 CDN（未本地化 / 远程引用）：不改写内部模块（SDK 按远程
   *   baseUrl fetch），仅把 manifest 转 blob 交给 SDK。
   * - npcs：regions[].configFile 是第二层区域清单 JSON——configFile 若镜像命中，改写成
   *   blob URL（SDK fetch 到 blob 后走 resolveNPCFileConfigPaths），并把其内部
   *   modelFilePath/imagePath 经 rewriteLocalResourceRefsDeep 改写（相对 configFile
   *   所在目录）。
   */
  const tryReplaceChunkedManifest = async (pathRef: { obj: any; key: string }): Promise<void> => {
    const chunkedValue = pathRef.obj[pathRef.key];
    if (typeof chunkedValue !== 'string' || !chunkedValue) return;
    if (!FileBundle.isLocalPath(chunkedValue)) return;
    const manifestFile = FileBundle.get(chunkedValue);
    if (!manifestFile) {
      await tryReplace(pathRef);
      return;
    }
    let text: string;
    try {
      text =
        manifestFile instanceof Blob
          ? await new Response(manifestFile).text()
          : new TextDecoder('utf-8').decode(manifestFile as Uint8Array);
    } catch {
      await tryReplace(pathRef);
      return;
    }
    let parsed: any;
    try {
      parsed = JSON.parse(text);
    } catch {
      await tryReplace(pathRef);
      return;
    }
    if (!parsed || typeof parsed !== 'object') {
      await tryReplace(pathRef);
      return;
    }

    const rawBaseUrl = typeof parsed.baseUrl === 'string' ? parsed.baseUrl : '';
    const mods = Array.isArray(parsed.modules) ? parsed.modules : [];
    const regions = Array.isArray(parsed.regions) ? parsed.regions : [];

    // v1.33.0 对齐 SDK chunked 纯前缀拼接语义：baseUrl 相对授权根（页面根）而非 manifest
    // 目录（SDK buildChunkModule `baseUrl + seg` 原样拼接不 resolveUrl），故 mirrorBase 不拼
    // manifestDir。baseUrl 相对时 = rawBaseUrl（缺省授权根）；绝对时无本地镜像语义 = null。
    const mirrorBase = FileBundle.isAbsoluteUrl(rawBaseUrl) ? null : rawBaseUrl || '';

    /** 解析单段：镜像命中 → blob URL；托管缺失 → 清空；否则原样（远程/未登记） */
    const rewriteSeg = (seg: unknown): string => {
      if (typeof seg !== 'string' || !seg) return '';
      // 绝对 URL（http/data/blob）→ SDK 直连，原样保留
      if (/^(https?:\/\/|data:|blob:)/i.test(seg)) return seg;
      if (!mirrorBase) return seg; // baseUrl 远程：模块走 CDN，不本地改写
      const rel = FileBundle.joinRelativePath(mirrorBase, seg);
      if (!FileBundle.isLocalPath(rel)) return seg;
      const target = FileBundle.get(rel);
      if (!target) {
        // v2.34.1 托管模式：未命中 = 磁盘缺失 → 清空段（外层把该模块从 manifest 移除，
        // 避免 SDK 拼 baseUrl+相对路径发 404 请求）；非托管维持原样（可能远程/静态托管）。
        return isWorkspaceMode() ? '' : seg;
      }
      if (isStreamingLodFormat(rel)) return seg;
      const blob =
        target instanceof Blob ? target : new Blob([target as BlobPart], { type: 'application/octet-stream' });
      const url = URL.createObjectURL(blob);
      blobUrls.push(url);
      return `${url}#${encodeURIComponent(FileBundle.normalizePath(rel))}`;
    };

    // collision / terrain：modules[].url（+ terrain 顶层 r16Url）
    let hitCount = 0;
    const totalRefs: Array<{ parent: any; field: string }> = [];
    if (mods.length > 0) {
      for (const mod of mods) {
        if (!mod || typeof mod !== 'object') continue;
        totalRefs.push({ parent: mod, field: 'url' });
      }
    }
    if (typeof parsed.r16Url === 'string' && parsed.r16Url) {
      totalRefs.push({ parent: parsed, field: 'r16Url' });
    }
    // npcs：regions[].configFile（第二层区域清单）
    const configFileRefs: Array<{ parent: any }> = [];
    if (regions.length > 0) {
      for (const region of regions) {
        if (!region || typeof region !== 'object') continue;
        if (typeof region.configFile === 'string' && region.configFile) {
          configFileRefs.push({ parent: region });
        }
      }
    }

    let allLocalized = true;
    /** 托管模式：url 被清空（缺失）的模块，循环后从 manifest 移除（避免 SDK 拼 baseUrl 发 404） */
    const missingMods = new Set<Record<string, unknown>>();
    for (const { parent, field } of totalRefs) {
      const original = parent[field];
      const rewritten = rewriteSeg(original);
      if (rewritten !== original) hitCount++;
      if (rewritten === original && mirrorBase) allLocalized = false;
      parent[field] = rewritten;
      // 仅「原本有值、改写后清空」才算真实缺失并移除模块。terrain single 模式 modules[].url
      // 本就是空串占位（R16 来源走 r16Url），空串经 rewriteSeg 原样返回 ''，若不加 original
      // 判断会误把占位模块移除，导致 terrain single 无法加载 R16。
      if (isWorkspaceMode() && field === 'url' && original && rewritten === '') {
        missingMods.add(parent as unknown as Record<string, unknown>);
      }
    }
    if (isWorkspaceMode() && missingMods.size > 0 && Array.isArray(parsed.modules)) {
      parsed.modules = parsed.modules.filter((m: Record<string, unknown>) => !missingMods.has(m));
    }

    // npcs configFile：改写为 blob + 递归内部资源引用（相对 configFile 镜像 key 目录）
    const missingRegions = new Set<Record<string, unknown>>();
    for (const { parent } of configFileRefs) {
      const seg = parent.configFile as string;
      const rewritten = rewriteSeg(seg);
      if (rewritten !== seg) hitCount++;
      if (rewritten === seg && mirrorBase) allLocalized = false;
      parent.configFile = rewritten;
      if (isWorkspaceMode() && rewritten === '') {
        missingRegions.add(parent as unknown as Record<string, unknown>);
      }
      // configFile 改写成 blob 后，内部 modelFilePath/imagePath 相对 blob 无目录语义——
      // 需直接改写第二层内容。configFile 镜像 key 在 FileBundle 中可读时，深度改写其资源字段。
      if (!mirrorBase) continue;
      const cfgRel = FileBundle.joinRelativePath(mirrorBase, seg);
      if (!FileBundle.isLocalPath(cfgRel)) continue;
      const cfgEntry = FileBundle.get(cfgRel);
      if (!cfgEntry) continue;
      let cfgText: string;
      try {
        cfgText =
          cfgEntry instanceof Blob
            ? await new Response(cfgEntry).text()
            : new TextDecoder('utf-8').decode(cfgEntry as Uint8Array);
      } catch {
        continue;
      }
      let cfgParsed: unknown;
      try {
        cfgParsed = JSON.parse(cfgText);
      } catch {
        continue;
      }
      if (!cfgParsed || typeof cfgParsed !== 'object') continue;
      if (rewriteLocalResourceRefsDeep(cfgParsed, FileBundle.dirname(cfgRel))) {
        const cfgBlob = new Blob([JSON.stringify(cfgParsed)], { type: 'application/json' });
        const cfgUrl = URL.createObjectURL(cfgBlob);
        blobUrls.push(cfgUrl);
        parent.configFile = cfgUrl;
        hitCount++;
      }
    }
    if (isWorkspaceMode() && missingRegions.size > 0 && Array.isArray(parsed.regions)) {
      parsed.regions = parsed.regions.filter((r: Record<string, unknown>) => !missingRegions.has(r));
    }

    // 本地化清单：本地段全部命中 → baseUrl 置空串（SDK 拼接 ''+blob 可加载），避免它
    // 把相对镜像路径拼到 blob URL 前。存在未命中（远程段）时保留 baseUrl 原样。
    // 托管模式：缺失段已清空（不再保留相对路径拼 baseUrl），故只要 mirrorBase 存在且有
    // 改写/清空即置空 baseUrl（绝对 URL 段 SDK 直连不受影响）。
    if (mirrorBase && (allLocalized || isWorkspaceMode()) && hitCount > 0) {
      parsed.baseUrl = '';
    }

    const manifestBlob = new Blob([JSON.stringify(parsed)], { type: 'application/json' });
    const manifestUrl = URL.createObjectURL(manifestBlob);
    blobUrls.push(manifestUrl);
    pathRef.obj[pathRef.key] = manifestUrl;
  };

  const tasks: Promise<void>[] = [];
  if (config.gaussianSplatting) {
    tasks.push(tryReplace({ obj: config.gaussianSplatting, key: 'singleSceneConfigPath' }));
    tasks.push(tryReplaceRegionReplaceConfig({ obj: config.gaussianSplatting, key: 'regionReplaceConfigPath' }));
  }
  if (config.npcs) {
    tasks.push(tryReplaceNpcsConfig({ obj: config.npcs, key: 'configFile' }));
  }
  if (config.collision) {
    tasks.push(tryReplace({ obj: config.collision, key: 'url' }));
  }
  // chunked 分块清单（v1.29.0）：collision/terrain/npcs 的 chunkedUrl（远程 CDN 本地化 /
  // zip 导入本地布局）预览内容改写——与 regionReplace/npcs.configFile 同构
  if (config.collision) {
    tasks.push(tryReplaceChunkedManifest({ obj: config.collision, key: 'chunkedUrl' }));
  }
  if (config.terrain) {
    tasks.push(tryReplaceChunkedManifest({ obj: config.terrain, key: 'chunkedUrl' }));
  }
  if (config.npcs) {
    tasks.push(tryReplaceChunkedManifest({ obj: config.npcs, key: 'chunkedUrl' }));
  }
  // InteractionZone 模型 URL（v2 格式 zone.model.url；v3 统一 Shape triangleMesh.mesh.url）
  if (config.interactionZones) {
    const zones = config.interactionZones;
    const zoneList = Array.isArray(zones) ? zones : Object.values(zones);
    for (const zone of zoneList) {
      if (zone?.model && typeof zone.model === 'object' && typeof zone.model.url === 'string') {
        tasks.push(tryReplace({ obj: zone.model, key: 'url' }));
      }
      if (zone?.shape?.type === 'triangleMesh' && typeof zone.shape.mesh?.url === 'string') {
        tasks.push(tryReplace({ obj: zone.shape.mesh, key: 'url' }));
      }
    }
  }
  // 单个 interaction zone（v2 格式）
  if (
    config.interaction?.model &&
    typeof config.interaction.model === 'object' &&
    typeof config.interaction.model.url === 'string'
  ) {
    tasks.push(tryReplace({ obj: config.interaction.model, key: 'url' }));
  }
  if (config.interaction?.shape?.type === 'triangleMesh' && typeof config.interaction.shape.mesh?.url === 'string') {
    tasks.push(tryReplace({ obj: config.interaction.shape.mesh, key: 'url' }));
  }
  await Promise.all(tasks);

  return { config, blobUrls };
}

/**
 * 把 ProjectConfig 序列化成 application/json 的 blob URL。
 *
 * 这样 SDK 就能用它当 sceneUrl，调用方等同于"meta.json 托管在某个 blob 协议下"。
 * 注意：blob URL 没有"目录"语义，所以 SDK 内部的 baseUrl 提取会得到 'blob:'，
 * 配置里其它相对路径在这种基准下解析会出错——这就是为什么我们要在 transformLocalPathsToBlobUrls
 * 里把所有本地路径**全部**转成 absolute（blob:）形式。
 */
function configToBlobUrl(config: any): string {
  const blob = new Blob([JSON.stringify(config)], { type: 'application/json' });
  return URL.createObjectURL(blob);
}

/**
 * 销毁当前 SDK 实例并 revoke 所有持有的 blob URL。
 *
 * 注意：SDK 的 dispose / destroy 方法名待确认；我们尽量调用常见命名，捕获异常容错。
 * 若 SDK 没有完善的 dispose，至少 revoke blob URL 释放浏览器内存。
 */
async function teardownSdk(): Promise<void> {
  // gizmo 依赖 SDK 的 scene/camera，必须在 SDK 销毁前先拆掉
  teardownGizmo();
  // 打点拾取：解绑监听 + 恢复相机（避免残留到新场景）
  teardownPickListeners();
  const sdk = sdkRef.value;
  if (sdk) {
    try {
      // SDK 的销毁 API：尝试常见命名
      const anySdk = sdk as any;
      if (typeof anySdk.dispose === 'function') anySdk.dispose();
      else if (typeof anySdk.destroy === 'function') anySdk.destroy();
      else if (typeof anySdk.stop === 'function') anySdk.stop();
    } catch (err) {
      // eslint-disable-next-line no-console
      console.warn('[PreviewPanel] SDK dispose 抛错（忽略）:', err);
    }
  }
  sdkRef.value = null;
  // v20260814：同步清空 engineCtxRef，让下游 inject 消费者看到 ctx 未就绪
  engineCtxRef.value = undefined;

  // revoke blob URL，避免内存泄漏
  for (const url of activeBlobUrls) {
    try {
      // 我们生成的 blob URL 可能附加了 #fileName.ext 作为格式提示（避免 SDK
      // 把 blob URL 识别为 'Unknown splat file type'）。revokeObjectURL 在 Chromium 上
      // 会忽略 hash 正常释放，但其它浏览器实现可能严格匹配——保险起见 strip hash 后再 revoke。
      URL.revokeObjectURL(url.split('#')[0]);
    } catch {
      /* noop */
    }
  }
  activeBlobUrls = [];

  // 清空容器内残留的 canvas（保险起见，避免 SDK 重建时叠加）
  const c = containerRef.value;
  if (c) {
    while (c.firstChild) c.removeChild(c.firstChild);
  }
}

/**
 * 上一次重建前的相机状态缓存（position + quaternion）。
 *
 * 每次 rebuildSdk 在 teardown 之前保存当前相机的位置和朝向，
 * 新 SDK init 完成后通过 FlyCameraController.setCameraState 恢复，
 * 使场景刷新时相机停留在用户上次操作的位置，而不是回到初始位置。
 *
 * 仅在"重建"（旧 SDK 存在时）才恢复；首次加载不恢复。
 */
let savedCameraState: {
  position: { x: number; y: number; z: number };
  quaternion: { x: number; y: number; z: number; w: number };
} | null = null;

/**
 * 用当前 meta 重建 SDK 实例。
 *
 * 流程：teardown 旧的 → 处理本地路径 → 序列化 config → init('creative') → animate()
 *
 * 失败时把状态置为 'error'，错误信息写入 errorMessage 供遮罩展示。
 *
 * **竞态保护**：用单调递增的 buildToken 做"过期检查"。如果 init 还在 await 中
 * 又来了新的 rebuildSdk 调用，token 会被自增；旧 init 完成后发现 token 不匹配，
 * 立即 dispose 自己（避免出现 sdkRef 指向新实例但旧实例还在跑动画的双开局面）。
 */
let buildToken = 0;
async function rebuildSdk(meta: any): Promise<void> {
  if (!containerRef.value) return;
  if (!canRender(meta)) {
    await teardownSdk();
    status.value = 'unconfigured';
    return;
  }

  const myToken = ++buildToken;

  // 在 teardown 前保存当前相机状态（仅当旧 SDK 存在时，即"重建"而非"首次加载"）
  // v2.0.0 Breaking: SDK.getCamera() 已删除，改走 ECS 直读 (cameraModule state)
  // v20260819（thirdroom ctx 对齐）：SDK 门面 getSceneManager() 已删除，改走 sdk.getContext()
  const oldSdk = sdkRef.value;
  if (oldSdk) {
    try {
      const ctx = oldSdk.getContext();
      const camera = ctx ? (getModule<CameraModuleState>(ctx, cameraModule)?.camera ?? null) : null;
      if (camera) {
        savedCameraState = {
          position: { x: camera.position.x, y: camera.position.y, z: camera.position.z },
          quaternion: {
            x: camera.quaternion.x,
            y: camera.quaternion.y,
            z: camera.quaternion.z,
            w: camera.quaternion.w,
          },
        };
      }
    } catch {
      // 旧 SDK 可能已处于异常状态，忽略取相机失败
    }
  }

  await teardownSdk();
  status.value = 'loading';
  errorMessage.value = '';

  try {
    const { config, blobUrls } = await transformLocalPathsToBlobUrls(meta);
    const sceneUrl = configToBlobUrl(config);
    const allBlobs = [...blobUrls, sceneUrl];

    // 期间被打断 → 立即清理并退出
    if (myToken !== buildToken) {
      for (const u of allBlobs) URL.revokeObjectURL(u);
      return;
    }

    activeBlobUrls = allBlobs;

    const sdk = new ViewerSDK();

    await sdk.init({
      container: containerRef.value,
      sceneUrl,
      // 创造模式不需要 dialog 引用
      // @ts-ignore SDK 类型上 interactionRef 为必填，创造模式下传 null 即可
      interactionRef: null,
      defaultOperationMode: 'dual',
      enableCliffDetection: false,
      mode: 'creative',
      extraModules: [lightModule],
      showInteractionZone: false,
    });

    // init 完成后再次检查 token：期间若被打断，这个 sdk 是孤儿，立即 dispose
    if (myToken !== buildToken) {
      try {
        sdk.dispose();
      } catch {
        /* noop */
      }
      return;
    }

    // 恢复上次的相机位置和朝向（仅重建时，首次加载不恢复）
    //
    // 关键时序：SceneManager.init() 里 this.loadScene() 没有 await（fire-and-forget），
    // 所以 sdk.init() 返回时 CreativeModeManager 可能还没创建。必须等场景就绪事件
    // （loadScene 末尾 triggerSceneReady）后才能安全恢复相机状态。
    //
    // v20260819（thirdroom ctx 对齐）：SDK 门面 getSceneManager() / onSceneReady / getFlyCameraController
    // 全部已删除，改走 ECS 直读：getModule<SceneState>(ctx, sceneModule).onSceneReady(cb)
    // + getModule<CameraModuleState>(ctx, cameraModule).flyController
    if (savedCameraState) {
      const state = savedCameraState;
      savedCameraState = null;
      const ctx = sdk.getContext();
      if (ctx) {
        getModule<SceneState>(ctx, sceneModule).onSceneReady(() => {
          try {
            const flyCtrl = getModule<CameraModuleState>(ctx, cameraModule)?.flyController ?? null;
            if (flyCtrl) {
              flyCtrl.setCameraState(
                new THREE.Vector3(state.position.x, state.position.y, state.position.z),
                new THREE.Quaternion(state.quaternion.x, state.quaternion.y, state.quaternion.z, state.quaternion.w),
              );
            }
          } catch {
            // 恢复失败不影响正常渲染，仅丢失上次位置
          }
        });
      }
    }

    // 始终注册 onSceneReady：通知 gizmo bridge 场景已就绪，
    // 供 MetaEditor 延迟激活 gizmo 时等待（避免 zone 对象尚未创建就激活 gizmo）
    {
      const ctx = sdk.getContext();
      if (ctx) {
        getModule<SceneState>(ctx, sceneModule).onSceneReady(() => {
          notifySceneReady();
          // v1.2.0：场景重建（导入新的 singleSceneConfigPath / regionReplaceConfigPath 等）后，
          // rebuildSdk → teardownSdk → teardownGizmo 已销毁全部 gizmo 实例，但 activeGizmoEntries
          // 仍保持激活（左侧开关仍显示开启）。若不在此用新 scene 重新 setupGizmo：
          // ① 3D 场景中 gizmo 控件消失；② 数值面板修改 transform 时 watch(gizmoSyncTarget)
          //    因 gizmoInstances 为空直接 return → 画面不更新（只有"关闭再开启"才能生效）。
          // audio zone 预览网格只在 gizmo 激活时创建（由 setupGizmo 内部 syncAudioZonePreviews
          // 负责），与 interactionZones 的网格显隐行为保持一致。
          restoreGizmoAfterSceneReady();
        });
      }
    }

    sdkRef.value = sdk;
    // SDK init 不会自动启动渲染循环，必须显式调用
    sdk.animate();

    // v20260814（thirdroom ctx 对齐）：ctx 唯一原始供料点 —— sdk.getContext() 直接写 engineCtxRef
    // 下游子组件 / composable 通过 useEngineContext() / useEngineContextGetter() inject 拿最新 ctx，
    // 与 SDK 实例完全解耦。
    engineCtxRef.value = sdk.getContext() ?? undefined;

    status.value = 'ready';
  } catch (err) {
    if (myToken !== buildToken) return; // 已被新一轮覆盖，旧错误忽略
    // eslint-disable-next-line no-console
    console.error('[PreviewPanel] SDK 初始化失败:', err);
    errorMessage.value = (err as Error).message || String(err);
    status.value = 'error';
    // 失败也要清理已分配的 blob（避免泄漏）
    await teardownSdk();
  }
}

// ==================== Gizmo（TransformControls 3D 拖动编辑） ====================

/**
 * gizmo 绑定到不可见 proxyGroup，拖拽只改数值（回写 meta）。
 * 同时把 transform 直接应用到场景中对应的真实物体（splat mesh / 角色模型 / 碰撞阴影网格），
 * 实现即时视觉反馈，不走全量 SDK 重建。
 * 支持 translate / rotate / scale 三种模式切换。
 */

const {
  activeGizmoEntries,
  gizmoModeVersion,
  suppressRebuild,
  flyToTarget,
  gizmoSyncTarget,
  geometrySyncTarget,
  gizmoModesVersion,
  pickRequest,
} = useGizmoBridge();

/** 拖拽开始时的完整状态快照（proxy + 场景物体 + meta 原始值），用于增量应用 */
interface DragStartState {
  /** proxy 在拖拽开始时的 transform（度数制） */
  proxy: { pos: THREE.Vector3; rot: THREE.Euler; scale: THREE.Vector3 };
  /** 场景物体在拖拽开始时的 local transform */
  sceneTarget: { pos: THREE.Vector3; rot: THREE.Euler; scale: THREE.Vector3 } | null;
  /** 拖拽开始时 meta 中的 transform 原始值（interactionZones 增量回写用） */
  metaTransform: { position: number[]; rotation: number[]; scale: number[] } | null;
}

/** 单个 gizmo 实例的运行时状态 */
interface GizmoInstance {
  controls: TransformControls;
  proxy: THREE.Group;
  helper: THREE.Object3D;
  /** 该 gizmo 对应的 meta 绝对路径（source='draft' 时为草稿内相对路径） */
  path: string;
  /**
   * 条目来源（缺省 'meta'）。
   * 'draft' 表示子编辑器草稿路径，与 3D 场景对象无对应关系：
   * sceneTarget 恒为 null，且不参与「未绑定重试」（否则会无限空转）。
   */
  source: GizmoSource;
  /** 该 gizmo 编辑的真实场景物体（transform 直接应用到此对象）；draft 来源恒为 null */
  sceneTarget: THREE.Object3D | null;
  /** 拖拽开始时的完整状态快照 */
  dragStart: DragStartState | null;
}

let gizmoInstances: GizmoInstance[] = [];
let gizmoScene: THREE.Scene | null = null;
let flyCameraWasEnabled = false;
/** 当前正在拖拽的 gizmo 数量（引用计数，防止多 gizmo 重叠时相机卡死） */
let gizmoDragCount = 0;
/** gizmo 激活标志：防止激活时 gizmoSyncTarget watcher 用 meta 值覆盖真实物体 */
let gizmoActivating = false;
/**
 * v1.26.0：restoreGizmoAfterSceneReady 未就绪时的自调度重试句柄。
 *
 * 场景：添加 interactionZones shape 的延迟激活路径里，waitForSdkRefresh 在 onSceneReady
 * 触发后立即激活 gizmo，但 SDK 的 zone 网格由 zone-module.init 的 fire-and-forget
 * attachInteractionZones 创建（内部有 800ms 兜底延时）——onSceneReady 时网格可能尚未创建。
 * 此时 createGizmoInstance 的 sceneTarget=null（仅改数值不应用视觉）。
 * watch(sdkRef) 轮询兜底恰好错过：sdkRef.value 赋值时 activeGizmoEntries 已被清空
 * （延迟激活先 deactivateGizmo）→ 轮询直接 return 不启动。故 restore 内部自调度重试，
 * 直到所有 sceneTarget 可找到或 gizmo 失活。
 */
let gizmoRestoreRetryTimer: number | null = null;
let gizmoRestoreRetryAttempts = 0;
const GIZMO_RESTORE_MAX_ATTEMPTS = 25; // 25 × 300ms ≈ 7.5s（覆盖 800ms 兜底 + 网络波动）

function normalizeDeltaDeg(deg: number): number {
  return ((((deg + 180) % 360) + 360) % 360) - 180;
}

function normalizeRotationDeg(deg: number): number {
  return (((((deg % 360) + 360) % 360) + 180) % 360) - 180;
}

function getActiveRotateAxisIndex(controls: TransformControls | null): 0 | 1 | 2 | null {
  const axis = (controls as unknown as { axis?: string | null } | null)?.axis;
  if (axis === 'X') return 0;
  if (axis === 'Y') return 1;
  if (axis === 'Z') return 2;
  return null;
}

function applyTransformToObject(
  target: THREE.Object3D,
  transform: { position: number[]; rotation: number[]; scale: number[] },
): void {
  target.position.set(transform.position[0], transform.position[1], transform.position[2]);
  target.rotation.set(
    THREE.MathUtils.degToRad(transform.rotation[0]),
    THREE.MathUtils.degToRad(transform.rotation[1]),
    THREE.MathUtils.degToRad(transform.rotation[2]),
  );
  target.scale.set(transform.scale[0], transform.scale[1], transform.scale[2]);
  target.updateMatrixWorld(true);
}

function parseInteractionZonePath(
  metaPath: string,
): { zoneKey: string | number; zoneName: string; target: 'geometry' | 'model' | 'shape' } | null {
  const segments = parsePath(metaPath);
  if (segments[0] !== 'interactionZones' || segments.length < 3) return null;
  const zoneKey = segments[1];
  if (typeof zoneKey !== 'string' && typeof zoneKey !== 'number') return null;

  const field = segments[2];
  const subField = segments[3];
  const isGeometryPath = field === 'geometryTransform' || (field === 'geometry' && subField === 'transform');
  const isModelPath =
    field === 'modelTransform' || field === 'transform' || (field === 'model' && subField === 'transform');
  // v3 统一 Shape 节点：interactionZones[<key>].shape.transform
  const isShapePath = field === 'shape' && subField === 'transform';
  if (!isGeometryPath && !isModelPath && !isShapePath) return null;

  return {
    zoneKey,
    zoneName: typeof zoneKey === 'number' ? `zone_${zoneKey}` : zoneKey,
    target: isGeometryPath ? 'geometry' : isShapePath ? 'shape' : 'model',
  };
}

function getInteractionZoneValue(zoneKey: string | number): any {
  const zones = props.value?.interactionZones;
  if (!zones) return undefined;
  return Array.isArray(zones) && typeof zoneKey === 'number' ? zones[zoneKey] : zones[String(zoneKey)];
}

/**
 * 解析 audio zone 的 meta 路径：`audio.audioZones[<index>].shape.transform`。
 * audio zone 在 SDK 运行时不渲染网格（仅触发音频），编辑器侧为可视化预览单独建网格。
 */
function parseAudioZonePath(metaPath: string): { zoneIndex: number; zoneName: string } | null {
  const segments = parsePath(metaPath);
  if (segments[0] !== 'audio' || segments[1] !== 'audioZones' || segments.length < 4) return null;
  const zoneIndex = segments[2];
  if (typeof zoneIndex !== 'number') return null;
  return { zoneIndex, zoneName: `audioZone_${zoneIndex}` };
}

function getAudioZoneValue(zoneIndex: number): any {
  const zones = props.value?.audio?.audioZones;
  if (!Array.isArray(zones)) return undefined;
  return zones[zoneIndex];
}

/**
 * 在 gizmoScene 中创建/更新 audio zone 的半透明预览网格（仅编辑器可视化）。
 *
 * SDK 设计上 audio zone 不渲染网格（只做 isPointInZone 触发检测），
 * 但编辑器需要可视化触发边界方便摆放。此网格挂在 gizmoScene（编辑器场景），
 * 标记 userData.isAudioZonePreview，gizmo 绑定与 findSceneObjectByPath 均可定位。
 *
 * 实现委托给 audioProvider.ensureMesh（统一注册表单一实现源）。
 */
function ensureAudioZonePreviewMesh(zoneIndex: number): THREE.Mesh | null {
  const zone = getAudioZoneValue(zoneIndex);
  if (!zone) return null;
  return audioProvider.ensureMesh(`audioZone_${zoneIndex}`, zone) as THREE.Mesh | null;
}

/**
 * 按当前激活的 gizmo 条目同步所有 zone 网格（统一注册表驱动）：
 * - 激活条目对应 zone → 创建/更新网格（ensureMesh）+ 显示（setVisible）
 * - 未激活（含被移除/切换走的）zone → 移除网格（编辑器自建）/ 隐藏（SDK 网格）
 *
 * interactionZones + audio.audioZones + 未来任何 zone 控件统一行为：
 * 只有对应 gizmo 条目激活时才显示。
 */
function syncZoneGridsByActiveEntries(): void {
  if (!gizmoScene) return;

  // 当前激活的 zone 集合：providerId → Set<zoneName>
  const activeZonesByProvider = new Map<string, Set<string>>();
  for (const entry of activeGizmoEntries.value) {
    const hit = parseZoneGridPath(entry.path);
    if (!hit) continue;
    let names = activeZonesByProvider.get(hit.provider.id);
    if (!names) {
      names = new Set<string>();
      activeZonesByProvider.set(hit.provider.id, names);
    }
    names.add(hit.parsed.zoneName);
  }

  for (const provider of zoneGridProviders) {
    const activeNames = activeZonesByProvider.get(provider.id);
    // 1. 创建/更新激活 zone 的网格 + 显示
    if (activeNames) {
      for (const zoneName of activeNames) {
        // 从激活条目找对应 parsed + zone
        const entry = activeGizmoEntries.value.find((e) => {
          const h = parseZoneGridPath(e.path);
          return h?.provider.id === provider.id && h.parsed.zoneName === zoneName;
        });
        if (!entry) continue;
        const hit = parseZoneGridPath(entry.path);
        if (!hit) continue;
        const zone = provider.getZone(hit.parsed);
        provider.ensureMesh(zoneName, zone);
        provider.setVisible(hit.parsed, zone, true);
        // v1.17.0：triangleMesh 激活 gizmo 时触发 GLB 线框加载。
        // SDK 对 triangleMesh 只建 1×1×1 box 占位网格，真实形状线框需异步加载 GLB 替换；
        // rebuildMesh 内部有「已加载且 url 未变」短路，重复激活不会闪烁/重复加载。
        if (provider.id === 'interactionZones' && zone?.shape?.type === 'triangleMesh') {
          provider.rebuildMesh(entry.path, hit.parsed, zone);
        }
      }
    }
    // 2. 清理未激活 zone 的网格：
    //    - 编辑器自建网格（audio 等）→ 从场景移除并 dispose
    //    - SDK 管理的网格（interactionZones 的 geometry）→ 仅隐藏（visible=false），
    //      SDK 重建时才真正销毁，编辑器不应移除 SDK 自有场景对象
    for (const child of [...gizmoScene.children]) {
      if (!provider.ownsMeshObject(child)) continue;
      const zoneName = child.userData?.zoneName as string | undefined;
      if (zoneName && !activeNames?.has(zoneName)) {
        if (child.userData?.isAudioZonePreview === true) {
          gizmoScene.remove(child);
          if (child instanceof THREE.Mesh) child.geometry.dispose();
        } else {
          child.visible = false;
        }
      }
    }
  }
}

/**
 * 统一 Shape 节点绑定的场景对象类型：
 * - triangleMesh → model（GLTF 模型对象）
 * - 其余基础形状 → geometry（碰撞框 mesh）
 */
function resolveShapeTarget(zoneKey: string | number): 'geometry' | 'model' {
  // v1.11.0：triangleMesh 统一绑定 geometry 占位线框（与其他类型一致）——
  // 不再返回 'model'（triangleMesh 无展示模型语义，mesh 是碰撞几何，仅线框可视化）。
  return 'geometry';
}

function getTransformWithDefaults(value: any): { position: number[]; rotation: number[]; scale: number[] } {
  return {
    position: [value?.position?.[0] ?? 0, value?.position?.[1] ?? 0, value?.position?.[2] ?? 0],
    rotation: [value?.rotation?.[0] ?? 0, value?.rotation?.[1] ?? 0, value?.rotation?.[2] ?? 0],
    scale: [value?.scale?.[0] ?? 1, value?.scale?.[1] ?? 1, value?.scale?.[2] ?? 1],
  };
}

function composeInteractionZoneModelTransform(
  geometryTransform: { position: number[]; rotation: number[]; scale: number[] },
  modelTransform: { position: number[]; rotation: number[]; scale: number[] },
): { position: number[]; rotation: number[]; scale: number[] } {
  const geoEuler = new THREE.Euler(
    THREE.MathUtils.degToRad(geometryTransform.rotation[0]),
    THREE.MathUtils.degToRad(geometryTransform.rotation[1]),
    THREE.MathUtils.degToRad(geometryTransform.rotation[2]),
    'XYZ',
  );
  const offset = new THREE.Vector3(
    modelTransform.position[0],
    modelTransform.position[1],
    modelTransform.position[2],
  ).applyEuler(geoEuler);
  const geoQuat = new THREE.Quaternion().setFromEuler(geoEuler);
  const modelQuat = new THREE.Quaternion().setFromEuler(
    new THREE.Euler(
      THREE.MathUtils.degToRad(modelTransform.rotation[0]),
      THREE.MathUtils.degToRad(modelTransform.rotation[1]),
      THREE.MathUtils.degToRad(modelTransform.rotation[2]),
    ),
  );
  const composedEuler = new THREE.Euler().setFromQuaternion(geoQuat.multiply(modelQuat));
  return {
    position: [
      geometryTransform.position[0] + offset.x,
      geometryTransform.position[1] + offset.y,
      geometryTransform.position[2] + offset.z,
    ],
    rotation: [
      THREE.MathUtils.radToDeg(composedEuler.x),
      THREE.MathUtils.radToDeg(composedEuler.y),
      THREE.MathUtils.radToDeg(composedEuler.z),
    ],
    scale: modelTransform.scale,
  };
}

/** 收集所有 gizmo proxy/helper 对象，用于在遍历场景 children 时跳过 */
function isGizmoObject(obj: THREE.Object3D): boolean {
  return gizmoInstances.some((inst) => inst.proxy === obj || inst.helper === obj);
}

function findInteractionZoneObject(
  scene: THREE.Scene,
  zoneName: string,
  target: 'geometry' | 'model' | 'geometryHelper',
): THREE.Object3D | null {
  for (const child of scene.children) {
    if (isGizmoObject(child)) continue;
    if (child.userData?.zoneName !== zoneName) continue;
    if (target === 'geometry' && child.userData?.isInteractionZoneGeometry === true) return child;
    if (target === 'model' && child.userData?.isClickable === true) return child;
    if (target === 'geometryHelper' && child.userData?.isInteractionZoneGeometryHelper === true) return child;
  }
  return null;
}

function syncInteractionZoneRuntimeObjects(metaPath: string): void {
  if (!gizmoScene) return;
  const parsed = parseInteractionZonePath(metaPath);
  if (!parsed) return;
  const zone = getInteractionZoneValue(parsed.zoneKey);
  // v3 统一 Shape 节点优先（shape.transform 为权威摆放变换），geometry/model 为归一化同步产物。
  // triangleMesh 的 geometry 占位线框 transform 同样以 shape.transform 为权威（拖拽更新的是
  // shape.transform，若读 geometry.transform 则把线框拉回旧位置 → 表现为"拖一下线框消失"）。
  // v1.16.0：geometry 以 shape.transform 为权威；model 始终读 zone.model.transform
  // （独立展示物的相对偏移）——triangleMesh + model 双配置时，model 是独立展示物，
  // 其 transform 是相对 geometry 的偏移，不能复用 shape.transform（否则 compose 双倍偏移 → 模型漂移/消失）。
  const geometryTransformValue = getTransformWithDefaults(
    zone?.shape?.type ? zone?.shape?.transform : (zone?.geometry?.transform ?? zone?.geometryTransform),
  );
  const modelTransform = getTransformWithDefaults(zone?.model?.transform ?? zone?.modelTransform ?? zone?.transform);

  const geometryObject = findInteractionZoneObject(gizmoScene, parsed.zoneName, 'geometry');
  if (geometryObject) {
    applyTransformToObject(geometryObject, geometryTransformValue);
    const helper = findInteractionZoneObject(gizmoScene, parsed.zoneName, 'geometryHelper') as
      (THREE.Object3D & { box?: THREE.Box3 }) | null;
    if (helper?.box) {
      helper.box.setFromObject(geometryObject);
      helper.updateMatrixWorld(true);
    }
  }

  const modelObject = findInteractionZoneObject(gizmoScene, parsed.zoneName, 'model');
  const composedModelTransform = composeInteractionZoneModelTransform(geometryTransformValue, modelTransform);
  if (modelObject) applyTransformToObject(modelObject, composedModelTransform);

  // 同步同 zone 的 model gizmo proxy 到「组合后的绝对位置」。
  // 无论当前改动的是 geometry/shape（model 跟随）还是 model 自身（gizmo 拖拽 /
  // 数值编辑 / 打点回填），只要 model gizmo 未在拖拽中，都同步到 composed。
  // 打点回填 model.transform.position 时，watch(gizmoSyncTarget) 先用相对偏移
  // 设错了 proxy 位置，此处必须无条件纠正——否则 model 箭头停在相对偏移（近原点）、
  // 与移动到命中点的模型脱节（需重拖 shape 或重开开关才恢复）。
  for (const inst of gizmoInstances) {
    const instParsed = parseInteractionZonePath(inst.path);
    if (!instParsed || instParsed.zoneKey !== parsed.zoneKey || instParsed.target !== 'model') continue;
    if (inst.controls.dragging) continue;
    inst.proxy.position.set(
      composedModelTransform.position[0],
      composedModelTransform.position[1],
      composedModelTransform.position[2],
    );
    inst.proxy.rotation.set(
      THREE.MathUtils.degToRad(composedModelTransform.rotation[0]),
      THREE.MathUtils.degToRad(composedModelTransform.rotation[1]),
      THREE.MathUtils.degToRad(composedModelTransform.rotation[2]),
    );
    inst.proxy.scale.set(
      composedModelTransform.scale[0],
      composedModelTransform.scale[1],
      composedModelTransform.scale[2],
    );
    // three r180：Controls.update(delta) 参数必填，这里仅刷新 gizmo 渲染，delta 无实际意义
    inst.controls.update(0);
  }
}

/**
 * 各 type 的默认 size 参数（与 gs.schema.ts 注释 + SDK 一致）。
 * 切换 type 时用此表自动调整 size 数组长度。
 */
const DEFAULT_ZONE_SIZE: Record<string, number[]> = {
  box: [1, 1, 1], // [width, height, depth]
  sphere: [0.5], // [radius]
  cylinder: [0.5, 0.5, 1], // [radiusTop, radiusBottom, height]
  capsule: [0.5, 1], // [radius, length]
  cone: [0.5, 1], // [radius, height]
  plane: [1, 1], // [width, height]
  circle: [0.5], // [radius]
  ring: [0.5, 1], // [innerRadius, outerRadius]
  torus: [0.5, 0.15], // [radius, tube]
  torusKnot: [0.5, 0.15], // [radius, tube]
};

/**
 * 在 SDK 用 config 副本上执行 Shape 归一化（shape ↔ geometry/model、center/radius/size 双向同步）。
 *
 * 与 MetaEditor.normalizeMeta 中的 normalizeShapeNodes 语义一致，作用于渲染副本：
 * - interaction / interactionZones → normalizeInteractionZoneShape
 * - audio.audioZones → normalizeAudioZone
 *
 * 保证 SDK 旧运行时（阶段三前消费 geometry/model、center/radius/size）与编辑器 Shape 表单预览一致。
 */
function normalizeShapeNodes(m: Record<string, any>): void {
  if (m.interaction && typeof m.interaction === 'object' && !Array.isArray(m.interaction)) {
    normalizeInteractionZoneShape(m.interaction);
  }
  if (m.interactionZones) {
    const zones = m.interactionZones;
    if (Array.isArray(zones)) {
      zones.forEach((zone: any) => normalizeInteractionZoneShape(zone));
    } else if (typeof zones === 'object' && zones !== null) {
      Object.values(zones).forEach((zone: any) => normalizeInteractionZoneShape(zone));
    }
  }
  const audioZones = m.audio?.audioZones;
  if (Array.isArray(audioZones)) {
    audioZones.forEach((zone: any) => normalizeAudioZone(zone));
  }

  // v1.15.0：编辑器预览不加载 triangleMesh 的 GLB 展示（触发区几何模型）——
  // 编辑器只需要 geometry 占位线框（gizmo 绑定 + 触发区范围可视化），
  // 实际 H5 场景才展示 GLB（第三party-controller addModel 分支 A）。
  // 仅作用于 SDK 渲染副本（m 是 deep-clone），不污染用户 meta。
  const collect = (zones: any) => {
    (Array.isArray(zones) ? zones : Object.values(zones)).forEach((zone: any) => {
      const shape = zone?.shape;
      if (shape && typeof shape === 'object' && shape.type === 'triangleMesh' && shape.mesh) {
        shape.mesh.url = '';
      }
    });
  };
  if (m.interactionZones) collect(m.interactionZones);
  if (m.interaction && typeof m.interaction === 'object' && !Array.isArray(m.interaction)) {
    collect(m.interaction);
  }
}

/**
 * 从 zone 对象提取几何参数（type + size 数组 + 分段参数），兼容两种数据源：
 * - v3 统一 Shape 节点（优先，权威结构）：结构化参数映射为 size 数组 + 分段参数
 * - v2 旧 geometry 节点：{ type, size } 原样读取，无分段参数（阶段三前兼容）
 *
 * 返回 { type, size, params }，缺省回退默认 box。
 */
function getZoneGeometryParams(zone: any): { type: string; size: number[]; params?: ZoneGeometryParams } {
  const shape = zone?.shape;
  if (shape && typeof shape === 'object' && !Array.isArray(shape) && typeof shape.type === 'string') {
    const t = shape.type;
    const params: ZoneGeometryParams = {};
    const pick = (key: keyof ZoneGeometryParams) => {
      if (typeof shape[key] === 'number' && Number.isFinite(shape[key])) params[key] = shape[key];
    };
    pick('segments');
    pick('heightSegments');
    pick('radialSegments');
    pick('capSegments');
    pick('tubularSegments');
    pick('thetaSegments');
    pick('thetaStart');
    pick('thetaLength');
    pick('thickness');
    pick('p');
    pick('q');
    const hasParams = Object.keys(params).length > 0;
    switch (t) {
      case 'box':
        return { type: t, size: [shape.width, shape.height, shape.depth], params: hasParams ? params : undefined };
      case 'sphere':
        return { type: t, size: [shape.radius], params: hasParams ? params : undefined };
      case 'cylinder':
        return {
          type: t,
          size: [shape.radiusTop, shape.radiusBottom, shape.height],
          params: hasParams ? params : undefined,
        };
      case 'capsule':
        return { type: t, size: [shape.radius, shape.length], params: hasParams ? params : undefined };
      case 'cone':
        return { type: t, size: [shape.radius, shape.height], params: hasParams ? params : undefined };
      case 'plane':
        return { type: t, size: [shape.width, shape.depth], params: hasParams ? params : undefined };
      case 'circle':
        return { type: t, size: [shape.radius], params: hasParams ? params : undefined };
      case 'ring':
        return { type: t, size: [shape.innerRadius, shape.outerRadius], params: hasParams ? params : undefined };
      case 'torus':
        return { type: t, size: [shape.radius, shape.tube], params: hasParams ? params : undefined };
      case 'torusKnot':
        return { type: t, size: [shape.radius, shape.tube], params: hasParams ? params : undefined };
      case 'triangleMesh':
        // triangleMesh 无固定几何参数：同步阶段回退默认 box 占位，
        // 异步 GLB 线框加载完成后由 applyTriangleMeshGeometry 替换为真实 mesh 形状
        return { type: 'box', size: [1, 1, 1] };
      default:
        return { type: 'box', size: [1, 1, 1] };
    }
  }

  const geo = zone?.geometry;
  return {
    type: geo?.type ?? 'box',
    size: geo?.size ?? DEFAULT_ZONE_SIZE[geo?.type ?? 'box'] ?? [1, 1, 1],
  };
}

/**
 * resize 模式下各 type 的可拖拽轴。
 * - box: 三轴（width, height, depth 独立）
 * - sphere/circle: 仅 X（半径，均匀缩放）
 * - cylinder: X（半径）+ Y（高度）
 * - cone: X（半径）+ Y（高度）
 * - plane: X（宽度）+ Y（高度）
 * - torus: X（半径）+ Y（管径）
 */
function getResizeAxes(type: string): { x: boolean; y: boolean; z: boolean } {
  switch (type) {
    case 'box':
      return { x: true, y: true, z: true };
    case 'sphere':
    case 'circle':
      return { x: true, y: false, z: false };
    case 'cylinder':
    case 'capsule':
    case 'cone':
    case 'torus':
    case 'plane':
      return { x: true, y: true, z: false };
    default:
      return { x: true, y: true, z: true };
  }
}

/**
 * geometry.size → proxy.scale 映射（resize 模式初始化用）。
 * 不同 type 的 size 项数不同，需映射到三维 scale。
 */
function sizeToProxyScale(type: string, size: number[]): [number, number, number] {
  const s = size.length > 0 ? size : (DEFAULT_ZONE_SIZE[type] ?? [1, 1, 1]);
  switch (type) {
    case 'sphere':
    case 'circle':
      return [s[0] || 0.5, s[0] || 0.5, s[0] || 0.5];
    case 'cylinder':
      return [s[0] || 0.5, s[2] || 1, s[0] || 0.5];
    case 'capsule':
      // capsule: [radius, length] → proxy 轴 = [半径, 圆柱段长度, 半径]
      return [s[0] || 0.5, s[1] || 1, s[0] || 0.5];
    case 'cone':
      return [s[0] || 0.5, s[1] || 1, s[0] || 0.5];
    case 'plane':
      return [s[0] || 1, s[1] || 1, 1];
    case 'torus':
    case 'torusKnot':
      return [s[0] || 0.5, s[1] || 0.15, s[0] || 0.5];
    case 'ring':
      // ring: [innerRadius, outerRadius] → 用 innerRadius 作为基准 X（外半径等比）
      return [s[0] || 0.5, s[0] || 0.5, 1];
    default: // box
      return [s[0] || 1, s[1] || 1, s[2] || 1];
  }
}

/**
 * proxy.scale → geometry.size 映射（resize 模式拖拽回写用）。
 * 逆映射：从三维 scale 还原为各 type 的 size 数组。
 */
function proxyScaleToSize(type: string, scale: [number, number, number]): number[] {
  switch (type) {
    case 'sphere':
    case 'circle':
      return [scale[0]];
    case 'cylinder':
      return [scale[0], scale[0], scale[1]];
    case 'capsule':
      return [scale[0], scale[1]];
    case 'cone':
      return [scale[0], scale[1]];
    case 'plane':
      return [scale[0], scale[1]];
    case 'torus':
    case 'torusKnot':
      return [scale[0], scale[1]];
    case 'ring':
      // ring: innerRadius 为基准，X 轴拖拽等比扩缩内外半径
      return [scale[0]];
    default: // box
      return [scale[0], scale[1], scale[2]];
  }
}

/* ============================================================
 * 统一 Zone 网格注册表（unified-shape-trigger-ecs 阶段一扩展）
 *
 * 目标：任何带 shape/几何的区域控件（interactionZones、audio.audioZones，
 * 未来更多）统一走「注册表驱动」的网格可视化流程，包括：
 * - 路径解析（path → zone 定位 + 绑定目标）
 * - 网格获取/创建/更新（SDK 网格 vs 编辑器自建网格）
 * - gizmo 显隐控制、几何重建、运行时对象同步
 * - gizmo 条目收集
 *
 * 新增控件只需实现一个 ZoneGridProvider 并注册到 zoneGridProviders，
 * PreviewPanel 核心流程无需再改。
 * ============================================================ */

interface ZoneGridParse {
  zoneKey: string | number;
  zoneName: string;
  target: 'geometry' | 'model' | 'shape';
}

interface ZoneGridProvider {
  /** 唯一标识（widget id 或内部名） */
  id: string;
  /** 匹配 meta 路径是否属于本 provider */
  matchPath(metaPath: string): boolean;
  /** 解析 meta 路径 → zone 定位（返回 null 表示不属于本 provider） */
  parse(metaPath: string): ZoneGridParse | null;
  /** 从 meta 读 zone 配置（parse 结果 → zone 值） */
  getZone(parsed: ZoneGridParse): any;
  /** 获取/创建/更新场景网格。编辑器自建网格返回对象；SDK 管理网格返回 null（由 SDK 创建） */
  ensureMesh(zoneName: string, zone: any): THREE.Object3D | null;
  /** 显隐控制（gizmo 激活时 visible=true，关闭/切换时 false） */
  setVisible(parsed: ZoneGridParse, zone: any, visible: boolean): void;
  /** 几何重建（尺寸/type 变化，metaPath 为具体字段路径） */
  rebuildMesh(metaPath: string, parsed: ZoneGridParse, zone: any): void;
  /** gizmo 拖拽后同步运行时对象（默认 no-op） */
  syncRuntime?(metaPath: string, parsed: ZoneGridParse, zone: any): void;
  /** 移除本 provider 的全部网格 */
  removeAll(): void;
  /** 判断对象是否属于本 provider 创建的网格 */
  ownsMeshObject(obj: THREE.Object3D): boolean;
  /** 可选：选中 widget 时收集 gizmo 条目（默认走通用 findTransformsInData） */
  collectEntries?: () => GizmoEntry[];
  /** 可选：查找场景对象（sceneTarget），默认走 findSceneObjectByPath 的 provider 分支 */
  findSceneObject(scene: THREE.Scene, parsed: ZoneGridParse): THREE.Object3D | null;
}

/** 已注册的 zone 网格 providers */
const zoneGridProviders: ZoneGridProvider[] = [];

/** 匹配 meta 路径属于哪个 provider */
function matchZoneGridProvider(metaPath: string): ZoneGridProvider | null {
  return zoneGridProviders.find((p) => p.matchPath(metaPath)) ?? null;
}

/** 解析 meta 路径 → 各 provider 的 ZoneGridParse */
function parseZoneGridPath(metaPath: string): { provider: ZoneGridProvider; parsed: ZoneGridParse } | null {
  const provider = matchZoneGridProvider(metaPath);
  if (!provider) return null;
  const parsed = provider.parse(metaPath);
  if (!parsed) return null;
  return { provider, parsed };
}

/**
 * 统一解析「任意 zone 的 shape 编辑路径」——interactionZones 与 audio.audioZones 共用同一套
 * shape 判别联合，resize 尺寸编辑应对两者一致生效。
 *
 * @returns { basePath, zoneValue, shapeType } 或 null（非 shape 路径 / triangleMesh 无几何参数）
 */
function resolveShapeEditTarget(path: string): { basePath: string; zoneValue: any; shapeType: string } | null {
  const hit = parseZoneGridPath(path);
  if (!hit) return null;
  const { provider, parsed } = hit;
  const zone = provider.getZone(parsed);

  // v2 旧 geometry 路径（interactionZones 专用）：target === 'geometry'
  if (provider.id === 'interactionZones' && parsed.target === 'geometry') {
    return { basePath: path.replace(/\.transform$/, ''), zoneValue: zone, shapeType: zone?.geometry?.type ?? 'box' };
  }

  // v3 统一 Shape：triangleMesh 无几何参数，不支持 resize
  const st = zone?.shape?.type;
  if (typeof st !== 'string' || st === 'triangleMesh') return null;
  return { basePath: path.replace(/\.transform$/, ''), zoneValue: zone, shapeType: st };
}

/**
 * 判断 gizmo 实例路径是否支持 resize 模式（调整几何尺寸而非 transform.scale）。
 * 所有 shape 路径（interactionZones + audio.audioZones）统一支持，triangleMesh 除外。
 */
function isResizeCapablePath(path: string): boolean {
  return resolveShapeEditTarget(path) !== null;
}

/**
 * 为 zone 几何 gizmo 实例应用 resize 模式（interactionZones + audio.audioZones 统一）：
 * 从 meta 读取最新几何参数（shape 或 geometry），设置 proxy.scale 和轴可见性。
 */
function applyResizeMode(inst: GizmoInstance): void {
  const target = resolveShapeEditTarget(inst.path);
  if (!target) {
    // 非 zone 几何路径 — resize 退化为普通 scale
    inst.controls.showX = true;
    inst.controls.showY = true;
    inst.controls.showZ = true;
    return;
  }
  const { type: geoType, size: geoSize } = getZoneGeometryParams(target.zoneValue);
  const [sx, sy, sz] = sizeToProxyScale(geoType, geoSize);
  if (!inst.controls.dragging) {
    inst.proxy.scale.set(sx, sy, sz);
  }
  const axes = getResizeAxes(geoType);
  inst.controls.showX = axes.x;
  inst.controls.showY = axes.y;
  inst.controls.showZ = axes.z;
}

/**
 * Shape 分段/细分参数（对应 shape.schema.ts 各判别分支的可选参数，与 SDK three-shape-factory 同步）。
 * 缺省时工厂保持原硬编码分段，保证 v2 geometry.size 数据源视觉零变化。
 */
interface ZoneGeometryParams {
  segments?: number;
  heightSegments?: number;
  radialSegments?: number;
  capSegments?: number;
  tubularSegments?: number;
  thetaSegments?: number;
  thetaStart?: number;
  thetaLength?: number;
  thickness?: number;
  p?: number;
  q?: number;
}

/** 角度制 → 弧度（Geometry 构造参数）。null/undefined 原样返回（使用 Three.js 默认 0）。 */
function degToRad(v: number | undefined): number {
  return typeof v === 'number' ? (v * Math.PI) / 180 : 0;
}

/**
 * 根据 type + size（可选分段参数）创建 Three.js BufferGeometry。
 * size 语义因 type 而异（见 gs.schema.ts 注释）：
 * - box:      [width, height, depth]
 * - sphere:   [radius]
 * - cylinder: [radiusTop, radiusBottom, height]
 * - cone:     [radius, height]
 * - plane:    [width, height]
 * - circle:   [radius]
 * - torus:    [radius, tube]
 */
function createZoneGeometry(type: string, size: number[], params?: ZoneGeometryParams): THREE.BufferGeometry {
  const s = size.length > 0 ? size : (DEFAULT_ZONE_SIZE[type] ?? [1, 1, 1]);

  switch (type) {
    case 'sphere':
      return new THREE.SphereGeometry(s[0] || 0.5, params?.segments ?? 16, params?.heightSegments ?? 12);
    case 'cylinder':
      return new THREE.CylinderGeometry(s[0] || 0.5, s[1] || 0.5, s[2] || 1, params?.radialSegments ?? 16);
    case 'capsule':
      // CapsuleGeometry(radius, length, capSegments, radialSegments)；
      // 圆柱段长度语义：总高 = length + 2×radius
      return new THREE.CapsuleGeometry(s[0] || 0.5, s[1] || 1, params?.capSegments ?? 8, params?.radialSegments ?? 16);
    case 'cone':
      return new THREE.ConeGeometry(s[0] || 0.5, s[1] || 1, params?.radialSegments ?? 16);
    case 'plane':
      // thickness > 0 时体现为薄 Cuboid（对齐 shape.schema plane.thickness 语义）
      return params?.thickness
        ? new THREE.BoxGeometry(s[0] || 1, params.thickness, s[1] || 1)
        : new THREE.PlaneGeometry(s[0] || 1, s[1] || 1);
    case 'circle':
      // thickness > 0 时体现为薄 Cylinder（对齐 shape.schema circle.thickness 语义）
      return params?.thickness
        ? new THREE.CylinderGeometry(
            s[0] || 0.5,
            s[0] || 0.5,
            params.thickness,
            params?.segments ?? 32,
            1,
            false,
            degToRad(params?.thetaStart ?? 0),
            degToRad(params?.thetaLength ?? 360),
          )
        : new THREE.CircleGeometry(
            s[0] || 0.5,
            params?.segments ?? 32,
            degToRad(params?.thetaStart ?? 0),
            degToRad(params?.thetaLength ?? 360),
          );
    case 'ring': {
      const inner = s[0] ?? 0.5;
      const outer = s[1] ?? 1;
      const thetaSegs = params?.thetaSegments ?? 32;
      const thetaStartRad = degToRad(params?.thetaStart ?? 0);
      const thetaLengthRad = degToRad(params?.thetaLength ?? 360);
      // thickness > 0：薄体积闭合环（内壁/外壁/顶底面），与 SDK rapier scale.z 拉伸语义对齐
      if (params?.thickness && params.thickness > 0) {
        const shape = new THREE.Shape();
        // 外环逆时针（CCW），内环顺时针（CW）挖洞，形成环形截面
        shape.absarc(0, 0, outer, thetaStartRad, thetaStartRad + thetaLengthRad, false);
        shape.absarc(0, 0, inner, thetaStartRad + thetaLengthRad, thetaStartRad, true);
        shape.closePath();
        return new THREE.ExtrudeGeometry(shape, {
          depth: params.thickness,
          bevelEnabled: false,
          curveSegments: thetaSegs,
        });
      }
      // 无 thickness：保持原平面 Ring（v2 数据源视觉零变化）
      return new THREE.RingGeometry(inner, outer, thetaSegs, 1, thetaStartRad, thetaLengthRad);
    }
    case 'torus':
      return new THREE.TorusGeometry(
        s[0] || 0.5,
        s[1] || 0.15,
        params?.radialSegments ?? 12,
        params?.tubularSegments ?? 32,
      );
    case 'torusKnot':
      return new THREE.TorusKnotGeometry(
        s[0] || 0.5,
        s[1] || 0.15,
        params?.tubularSegments ?? 32,
        params?.radialSegments ?? 8,
        params?.p ?? 2,
        params?.q ?? 3,
      );
    case 'box':
    default:
      return new THREE.BoxGeometry(s[0] || 1, s[1] || 1, s[2] || 1);
  }
}

/** triangleMesh 异步线框预览的加载令牌（zoneName → 版本号），防止 url 切换 / SDK 重建竞态 */
const triangleMeshPreviewTokens = new Map<string, number>();

/**
 * triangleMesh 触发区在编辑器里的 GLB 线框预览。
 *
 * SDK 侧对 triangleMesh 只创建 1×1×1 box 占位（createZoneGeometry 回退 default box），
 * 编辑器里看到的是正方体线框，无法反映真实触发区形状。这里异步加载 GLB 合并几何并
 * 替换 zoneMesh 的 geometry（材质保持 SDK 的绿色 wireframe，仅换几何），让编辑器
 * 显示 GLB 实际 mesh 形状的线框，与物理 Trimesh 体积（loadTriangleMesh 同源）一致。
 *
 * 竞态防护：
 * - url 变化（用户改 shape.mesh.url）→ token 递增，旧回调丢弃
 * - SDK 重建（rebuildSdk 清空 scene）→ 重新 find 对象，找不到即放弃
 * - 加载失败 → 保持 box 占位（与旧行为一致）
 *
 * @param zoneKey   interactionZones 的 key（数组下标 / Record key）
 * @param zoneName  scene 对象标记名（zone_N 或 Record key）
 * @param url       GLB 资源地址（本地路径已在 transformLocalPathsToBlobUrls 转成 absolute）
 */
async function applyTriangleMeshGeometry(zoneKey: string | number, zoneName: string, url: string): Promise<void> {
  const token = (triangleMeshPreviewTokens.get(zoneName) ?? 0) + 1;
  triangleMeshPreviewTokens.set(zoneName, token);

  // 与 transformLocalPathsToBlobUrls 一致的资源解析：FileBundle blob 优先，否则按 assetsBase/document.baseURI 拼 absolute。
  // rebuildMesh 拿到的 zone 来自用户 meta（props.value），mesh.url 可能是相对路径，
  // 不解析 GLTFLoader 会相对当前页面路径加载（本地导入场景必然失败）。
  const resolvePreviewUrl = (): string | null => {
    if (!FileBundle.isLocalPath(url)) return url; // 已是 http(s)/blob/data → 直接用
    const file = FileBundle.get(url);
    if (file) {
      const blob = file instanceof Blob ? file : new Blob([file as BlobPart], { type: 'application/octet-stream' });
      return URL.createObjectURL(blob);
    }
    try {
      return new URL(url, FileBundle.getAssetsBaseUrl() || document.baseURI).href;
    } catch {
      return null;
    }
  };
  const loadUrl = resolvePreviewUrl();
  if (!loadUrl) return;
  // 本地导入场景 createObjectURL 产生的 blob URL：加载完成后必须 revoke，否则每次重建泄漏一个 URL。
  // 注意 loadTriangleMesh 内部有按 URL 缓存，revoke 前数据已拷贝进 JS 数组缓存，revoke 后重进缓存命中。
  const isBlobUrl = loadUrl.startsWith('blob:');

  try {
    const data = await loadTriangleMesh(loadUrl);
    if (!data || data.vertices.length === 0 || data.indices.length === 0) {
      // eslint-disable-next-line no-console
      console.warn(`[PreviewPanel] triangleMesh GLB 提取为空 zone=${zoneName} url=${url}`);
      return;
    }

    // 竞态校验：token 过期 / 场景已重建
    if (triangleMeshPreviewTokens.get(zoneName) !== token) {
      // eslint-disable-next-line no-console
      console.warn(`[PreviewPanel] triangleMesh 加载已过期（token）zone=${zoneName}`);
      return;
    }
    // 优先 gizmoScene（gizmo 激活时绑定 SDK scene），否则从 SDK context 兜底取 scene
    const scene = gizmoScene ?? getSdkThreeContext(sdkRef.value).scene;
    if (!scene) {
      // eslint-disable-next-line no-console
      console.warn(`[PreviewPanel] triangleMesh 无 scene zone=${zoneName}`);
      return;
    }
    // 当前 zone 的 url 是否仍是本次加载的 url（防止 url 改后旧回调覆盖）
    const current = getInteractionZoneValue(zoneKey);
    if (current?.shape?.type !== 'triangleMesh' || current?.shape?.mesh?.url !== url) {
      // eslint-disable-next-line no-console
      console.warn(`[PreviewPanel] triangleMesh url 已变化，丢弃旧加载 zone=${zoneName}`);
      return;
    }

    const geometryObject = findInteractionZoneObject(scene, zoneName, 'geometry') as THREE.Mesh | null;
    if (!geometryObject) {
      // eslint-disable-next-line no-console
      console.warn(`[PreviewPanel] triangleMesh 找不到 geometry 对象 zone=${zoneName}`);
      return;
    }

    // GLB 合并几何（loadTriangleMesh 已应用子网格层级变换并缓存）→ 替换占位 box
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(data.vertices, 3));
    if (data.indices.length > 0) {
      geo.setIndex(new THREE.Uint32BufferAttribute(data.indices, 1));
    }
    geo.computeBoundingSphere();
    geometryObject.geometry?.dispose();
    geometryObject.geometry = geo;
    geometryObject.userData.triangleMeshPreviewUrl = url;
    // 显隐完全由 gizmo 激活状态控制（syncZoneGridsByActiveEntries 的 setVisible）：
    // 激活时 setVisible(true) 已先于 rebuildMesh 执行，失活时 setVisible(false) 隐藏，
    // 与 box/sphere 等其他类型行为一致。这里不再强制 visible=true。
    geometryObject.updateMatrixWorld(true);
    // eslint-disable-next-line no-console
    console.log(
      `[PreviewPanel] triangleMesh GLB 线框已替换 zone=${zoneName} 顶点=${data.vertices.length / 3} ` +
        `三角形=${data.indices.length / 3} 包围球半径=${(geo.boundingSphere?.radius ?? 0).toFixed(3)} ` +
        `zone 位置=(${geometryObject.position.x.toFixed(2)}, ${geometryObject.position.y.toFixed(2)}, ${geometryObject.position.z.toFixed(2)})`,
    );

    const helper = findInteractionZoneObject(scene, zoneName, 'geometryHelper') as
      (THREE.Object3D & { box?: THREE.Box3 }) | null;
    if (helper?.box) {
      helper.box.setFromObject(geometryObject);
      helper.updateMatrixWorld(true);
    }
  } catch (e) {
    // 加载失败：保持 box 占位（与旧行为一致）
    // eslint-disable-next-line no-console
    console.warn(`[PreviewPanel] triangleMesh GLB 线框加载失败 zone=${zoneName} url=${url}:`, e);
  } finally {
    if (isBlobUrl) URL.revokeObjectURL(loadUrl);
  }
}

/**
 * interactionZones provider：
 * - 网格由 SDK 创建（InteractionZoneGeometry：zoneName + isInteractionZoneGeometry 标记）
 * - 模型为 SDK 创建的 GLTF（zoneName + isClickable）
 * - gizmo 显隐只控制 geometry（碰撞框），model 是展示模型不参与显隐
 */
const interactionZonesProvider: ZoneGridProvider = {
  id: 'interactionZones',
  matchPath: (metaPath) =>
    parseInteractionZonePath(metaPath) !== null ||
    /^interactionZones\[[\w.-]+\]/.test(metaPath) ||
    /^interactionZones\./.test(metaPath),
  parse: (metaPath) => {
    // 完整路径（含 .transform 等 target 段）：解析 target
    const p = parseInteractionZonePath(metaPath);
    if (p) return { zoneKey: p.zoneKey, zoneName: p.zoneName, target: p.target };
    // 宽松路径（如 interactionZones[0].shape / interactionZones[0] —— union type 切换重建时）
    // 只解析 zone 定位，target 由 rebuildMesh 内部按 zone.shape.type 决定
    const segments = parsePath(metaPath);
    if (segments[0] !== 'interactionZones' || segments.length < 2) return null;
    const zoneKey = segments[1];
    if (typeof zoneKey !== 'string' && typeof zoneKey !== 'number') return null;
    return { zoneKey, zoneName: typeof zoneKey === 'number' ? `zone_${zoneKey}` : zoneKey, target: 'shape' };
  },
  getZone: (parsed) => getInteractionZoneValue(parsed.zoneKey),
  ensureMesh: () => null, // SDK 管理网格，无需编辑器创建
  setVisible: (parsed, zone, visible) => {
    if (!gizmoScene) return;
    // 只控制 geometry（碰撞框可视化）；model 是展示模型（可能是 NPC），不参与 gizmo 显隐。
    // v1.13.0：所有类型（含 triangleMesh）统一走材质控制，无特殊分支。
    const target = parsed.target === 'shape' ? resolveShapeTarget(parsed.zoneKey) : parsed.target;
    if (target === 'model') return;
    const zoneObject = findInteractionZoneObject(gizmoScene, parsed.zoneName, 'geometry') as THREE.Mesh | null;
    if (!zoneObject) return;
    // v1.18.0：meta 编辑器 interaction zone 线框统一为绿色（编辑器视觉约定）。
    // SDK zoneMesh 材质颜色为蓝色（thirdparty-controller v4.5.0，对齐 H5 实际场景
    // debug-manager 触发区蓝色）；编辑器预览复用 SDK zoneMesh 故同为蓝色。
    // 颜色覆盖必须在 setVisible（所有类型激活 gizmo 的统一入口）而非仅 rebuildMesh——
    // syncZoneGridsByActiveEntries 只对 triangleMesh 调用 rebuildMesh，其他类型
    // （box/sphere/cylinder 等）只走 setVisible，若覆盖放在 rebuildMesh 则其他类型
    // 仍显示 SDK 蓝色，视觉不统一。
    const zoneMat = zoneObject.material as THREE.MeshBasicMaterial | THREE.MeshBasicMaterial[] | undefined;
    const mat = Array.isArray(zoneMat) ? zoneMat[0] : zoneMat;
    if (mat instanceof THREE.MeshBasicMaterial) {
      mat.color.setHex(0x00ff00);
    }
    // v1.14.0：SDK zoneMesh 材质已改为不透明 wireframe（transparent:false），
    // 显隐只切 visible 不再改材质——避免 opacity 被置 0 后无法恢复。
    zoneObject.visible = visible;
  },
  rebuildMesh: (metaPath, parsed, zone) => {
    if (!gizmoScene) return;
    const zoneName = parsed.zoneName;
    const geometryObject = findInteractionZoneObject(gizmoScene, zoneName, 'geometry') as THREE.Mesh | null;
    if (!geometryObject) return;

    // 注：绿色线框覆盖只在 setVisible 执行（v1.18.0）——rebuildMesh 恒在
    // setVisible(true) 之后被调用（syncZoneGridsByActiveEntries 1017→1022 行），
    // gizmo 编辑路径（rebuildZoneGridGeometry）也仅在 zone 激活后触发，故无需重复覆盖。

    // v1.17.0：triangleMesh 且已加载同 url 的 GLB 线框 → 直接跳过。
    // 短路必须放在 geometry 重置之前，否则已加载后再次 rebuildMesh 会先把 GLB
    // 几何 dispose 回 box 占位（激活 gizmo 时闪烁一帧正方体再异步替换回来）。
    if (zone?.shape?.type === 'triangleMesh') {
      const url = zone?.shape?.mesh?.url;
      if (typeof url === 'string' && url) {
        if (geometryObject.userData?.triangleMeshPreviewUrl === url) return;
      } else {
        // url 为空（用户清空 GLB）：使在途 GLB 加载失效，保留 box 占位
        triangleMeshPreviewTokens.set(zoneName, (triangleMeshPreviewTokens.get(zoneName) ?? 0) + 1);
      }
    } else {
      // 非 triangleMesh（type 已切换）：使在途 GLB 加载失效，防止旧回调把线框回填到其他 shape
      triangleMeshPreviewTokens.set(zoneName, (triangleMeshPreviewTokens.get(zoneName) ?? 0) + 1);
    }

    const { type: geoType, size: geoSize, params: geoParams } = getZoneGeometryParams(zone);
    geometryObject.geometry?.dispose();
    geometryObject.geometry = createZoneGeometry(geoType, geoSize, geoParams);
    geometryObject.updateMatrixWorld(true);
    const helper = findInteractionZoneObject(gizmoScene, zoneName, 'geometryHelper') as
      (THREE.Object3D & { box?: THREE.Box3 }) | null;
    if (helper?.box) {
      helper.box.setFromObject(geometryObject);
      helper.updateMatrixWorld(true);
    }
    // v1.17.0：triangleMesh → 异步加载 GLB 合并几何，替换 1×1×1 box 占位为真实 mesh 形状线框。
    // 物理 Trimesh（阶段二 trigger）与编辑器预览共用 loadTriangleMesh 的同一份合并几何，
    // 保证"编辑器看到的就是实际触发区体积"。
    if (zone?.shape?.type === 'triangleMesh') {
      const url = zone?.shape?.mesh?.url;
      if (typeof url === 'string' && url) {
        applyTriangleMeshGeometry(parsed.zoneKey, zoneName, url);
      }
    }
  },
  syncRuntime: (metaPath, parsed) => syncInteractionZoneRuntimeObjects(metaPath),
  removeAll: () => {
    // interaction zone 网格由 SDK 管理，编辑器不负责移除（SDK 重建时自动清理）
  },
  ownsMeshObject: (obj) =>
    obj.userData?.isInteractionZoneGeometry === true || obj.userData?.isInteractionZoneGeometryHelper === true,
  findSceneObject: (scene, parsed) => {
    const target =
      parsed.target === 'geometry'
        ? 'geometry'
        : parsed.target === 'shape'
          ? resolveShapeTarget(parsed.zoneKey)
          : 'model';
    return findInteractionZoneObject(scene, parsed.zoneName, target);
  },
};

/**
 * audio provider：
 * - SDK 不渲染 audio zone 网格（仅 isPointInZone 触发检测），编辑器侧自建预览网格
 * - 网格标记 userData.isAudioZonePreview，gizmo 绑定/查找均通过该标记
 */
const audioProvider: ZoneGridProvider = {
  id: 'audio',
  matchPath: (metaPath) => parseAudioZonePath(metaPath) !== null || /^audio\.audioZones\[\d+\]/.test(metaPath),
  parse: (metaPath) => {
    // 完整路径（含 .shape.transform）：走严格解析
    const p = parseAudioZonePath(metaPath);
    if (p) return { zoneKey: p.zoneIndex, zoneName: p.zoneName, target: 'shape' };
    // 宽松路径（audio.audioZones[i] / audio.audioZones[i].shape —— union type 切换重建时）
    const segments = parsePath(metaPath);
    if (segments[0] !== 'audio' || segments[1] !== 'audioZones' || segments.length < 3) return null;
    const zoneIndex = segments[2];
    if (typeof zoneIndex !== 'number') return null;
    return { zoneKey: zoneIndex, zoneName: `audioZone_${zoneIndex}`, target: 'shape' };
  },
  getZone: (parsed) => getAudioZoneValue(parsed.zoneKey as number),
  ensureMesh: (zoneName, zone) => {
    if (!gizmoScene) return null;
    const shape = zone?.shape;
    if (!shape || typeof shape !== 'object' || typeof shape.type !== 'string') return null;
    const zoneIndex = zoneNameToIndex(zoneName);
    let mesh = gizmoScene.children.find(
      (c) => c.userData?.isAudioZonePreview === true && c.userData?.zoneName === zoneName,
    ) as THREE.Mesh | undefined;
    const { type, size, params } = getZoneGeometryParams(zone);
    const geometry = createZoneGeometry(type, size, params);
    if (!mesh) {
      // 与 SDK 的 interaction zone 网格材质完全一致（见 thirdparty-controller
      // InteractionZoneGeometry：绿色 wireframe + 半透明），保证所有 zone 网格视觉统一。
      mesh = new THREE.Mesh(
        geometry,
        new THREE.MeshBasicMaterial({
          color: 0x00ff00,
          transparent: true,
          opacity: 0.3,
          wireframe: true,
        }),
      );
      // 关闭视锥剔除：mesh.scale 承载 shape.transform.scale，
      // 而 boundingSphere 不随 scale/rotation 更新，旋转/缩放后特定角度会被
      // 错误剔除（相机旋转到某角度网格消失）。interaction zone 无此问题是因为
      // 其尺寸烘焙在 geometry 内、mesh.scale 恒为 1。
      mesh.frustumCulled = false;
      mesh.userData.isAudioZonePreview = true;
      mesh.userData.zoneName = zoneName;
      mesh.userData.zoneIndex = zoneIndex;
      gizmoScene.add(mesh);
    } else {
      mesh.geometry.dispose();
      mesh.geometry = geometry;
    }
    const t = shape.transform;
    if (t && typeof t === 'object') {
      const pos = Array.isArray(t.position) ? t.position : [0, 0, 0];
      const rot = Array.isArray(t.rotation) ? t.rotation : [0, 0, 0];
      const sc = Array.isArray(t.scale) ? t.scale : [1, 1, 1];
      mesh.position.set(pos[0] ?? 0, pos[1] ?? 0, pos[2] ?? 0);
      mesh.rotation.set(
        ((rot[0] ?? 0) * Math.PI) / 180,
        ((rot[1] ?? 0) * Math.PI) / 180,
        ((rot[2] ?? 0) * Math.PI) / 180,
      );
      mesh.scale.set(sc[0] ?? 1, sc[1] ?? 1, sc[2] ?? 1);
    }
    mesh.visible = true;
    return mesh;
  },
  setVisible: (parsed, zone, visible) => {
    if (!gizmoScene) return;
    const mesh = gizmoScene.children.find(
      (c) => c.userData?.isAudioZonePreview === true && c.userData?.zoneName === parsed.zoneName,
    );
    if (mesh) mesh.visible = visible;
  },
  rebuildMesh: (_metaPath, parsed, _zone) => {
    if (gizmoScene) ensureAudioZonePreviewMesh(parsed.zoneKey as number);
  },
  removeAll: () => {
    if (!gizmoScene) return;
    for (const child of [...gizmoScene.children]) {
      if (child.userData?.isAudioZonePreview === true) {
        gizmoScene.remove(child);
        if (child instanceof THREE.Mesh) child.geometry.dispose();
      }
    }
  },
  ownsMeshObject: (obj) => obj.userData?.isAudioZonePreview === true,
  findSceneObject: (scene, parsed) => {
    for (const child of scene.children) {
      if (child.userData?.isAudioZonePreview === true && child.userData?.zoneName === parsed.zoneName) {
        return child;
      }
    }
    return null;
  },
};

/** audioZone_<index> → index */
function zoneNameToIndex(zoneName: string): number {
  const m = /^audioZone_(\d+)$/.exec(zoneName);
  return m ? Number(m[1]) : -1;
}

/** 注册全部 zone 网格 providers（幂等，防 HMR 重复注册） */
function registerZoneGridProviders(): void {
  if (zoneGridProviders.length > 0) return;
  zoneGridProviders.push(interactionZonesProvider, audioProvider);
}

registerZoneGridProviders();

/**
 * 统一 zone 网格几何重建（走 ZoneGridProvider 注册表，interactionZones + audio 等统一）。
 *
 * 当用户在数值面板修改 geometry.size / geometry.type / shape 尺寸参数时调用。
 * gizmo 激活状态下 suppressRebuild=true 阻止了 SDK 重建，
 * 此函数让 provider 就地更新场景网格（dispose 旧 geometry + 替换新 geometry）。
 */
function rebuildZoneGridGeometry(metaPath: string): void {
  if (!gizmoScene) return;
  const hit = parseZoneGridPath(metaPath);
  if (!hit) return;
  const { provider, parsed } = hit;
  const zone = provider.getZone(parsed);
  if (!zone) return;
  provider.rebuildMesh(metaPath, parsed, zone);
}

/** 向后兼容别名（保留调用点，行为一致） */
function rebuildInteractionZoneGeometry(metaPath: string): void {
  rebuildZoneGridGeometry(metaPath);
}

/**
 * 统一 zone 网格显隐控制：走 ZoneGridProvider 注册表（interactionZones + audio 等统一）。
 * 调用方只需传 meta 路径 + 显隐标志，具体 provider 决定哪些对象受影响。
 */
function setZoneGridVisible(metaPath: string | null, visible: boolean): void {
  if (!gizmoScene || !metaPath) return;
  const hit = parseZoneGridPath(metaPath);
  if (!hit) return;
  const { provider, parsed } = hit;
  const zone = provider.getZone(parsed);
  provider.setVisible(parsed, zone, visible);
}

/** 向后兼容别名（保留调用点，行为一致） */
function setInteractionZoneGeometryVisible(metaPath: string | null, visible: boolean): void {
  setZoneGridVisible(metaPath, visible);
}

/** 从 SDK ECS state 取 Three.js 三件套（参考 splat-studio sdkThreeContext.ts） */
function getSdkThreeContext(sdk: ViewerSDK | null): {
  scene: THREE.Scene | null;
  camera: THREE.PerspectiveCamera | null;
  domElement: HTMLCanvasElement | null;
} {
  if (!sdk) return { scene: null, camera: null, domElement: null };
  // v20260819：SDK 门面 getSceneManager() 已删除，改走 sdk.getContext()
  const ctx = sdk.getContext();
  if (!ctx) return { scene: null, camera: null, domElement: null };
  try {
    const rendererState = getModule<RendererModuleState>(ctx, rendererModule);
    const cameraState = getModule<CameraModuleState>(ctx, cameraModule);
    return {
      scene: rendererState?.scene ?? null,
      camera: cameraState?.camera ?? null,
      domElement: rendererState?.renderer?.domElement ?? null,
    };
  } catch {
    return { scene: null, camera: null, domElement: null };
  }
}

/**
 * 判断是否为高斯泼溅节点（参考 SDK shadow-module.ts isGaussianNode）。
 */
function isGaussianNode(obj: THREE.Object3D): boolean {
  return obj.userData?.isGaussianSplat === true;
}

/**
 * 根据 meta 路径找到场景中对应的真实物体。
 *
 * 路径映射：
 * - gaussianSplatting.* → 高斯泼溅网格（SplatMesh / SparkRenderer / DropInViewer）
 * - initial.player.* → 非空 CharacterGroup（creative 模式无角色时返回 null，禁止兜底场景 Group）
 * - collision.* → 碰撞阴影网格（CollisionShadowLightMesh / ShadowLightMesh）
 */
function findSceneObjectByPath(scene: THREE.Scene, metaPath: string): THREE.Object3D | null {
  const skipNames = [
    'DebugGroup',
    'LightGroup',
    'AnimationGroup',
    'AudioGroup',
    'ShadowCatcher',
    'ModuleBoundsDebug',
    'AudioListenerAnchor',
  ];

  // 0. zone 网格（统一注册表）：interactionZones / audio.audioZones / 未来任何 zone 控件。
  //    interactionZones 的 geometry 是碰撞框 mesh、model 是 GLTF 模型、shape 按类型绑定；
  //    audio 是编辑器自建的预览网格。全部由 provider.findSceneObject 统一解析。
  const zoneHit = parseZoneGridPath(metaPath);
  if (zoneHit) {
    const { provider, parsed } = zoneHit;
    return provider.findSceneObject?.(scene, parsed) ?? null;
  }

  // 1. collision → 阴影接收网格
  if (metaPath.startsWith('collision')) {
    for (const child of scene.children) {
      if (child.name === 'CollisionShadowLightMesh' || child.name === 'ShadowLightMesh') {
        return child;
      }
    }
  }

  // 2. initial.player → 角色模型
  //    注意：creative 预览模式下角色模型不加载，CharacterGroup 是空的。
  //    此时严禁兜底返回场景根组/首个 Group——那会导致 gizmo 拖动 player 时
  //    整体平移场景（对齐 v1.3.0 gaussian 必须命中真实 SplatMesh 的修复）。
  //    因此必须命中「非空 CharacterGroup」才算有效目标；找不到则返回 null，
  //    createGizmoInstance 会退化为「仅改数值不应用视觉」。
  if (metaPath.startsWith('initial.player')) {
    const charGroup = scene.children.find((c) => c.name === 'CharacterGroup');
    if (charGroup && charGroup.children.length > 0) {
      return charGroup;
    }
    return null;
  }

  // 3. gaussianSplatting → 高斯泼溅网格
  if (metaPath.startsWith('gaussianSplatting')) {
    for (const child of scene.children) {
      if (isGizmoObject(child)) continue;
      if (isGaussianNode(child)) return child;
      // 递归一层（有些策略把 splat 包在 Group / DropInViewer 容器里）
      if ((child as any).isGroup || ((child as any).children?.length ?? 0) > 0) {
        for (const grandchild of child.children) {
          if (isGaussianNode(grandchild)) return grandchild;
        }
      }
    }
  }

  // 4. 兜底：找第一个非已知组的 mesh
  for (const child of scene.children) {
    if (child.name && skipNames.some((n) => child.name.startsWith(n))) continue;
    if (isGizmoObject(child)) continue;
    if ((child as any).isMesh || (child as any).isGroup) {
      return child;
    }
  }

  return null;
}

/**
 * 子编辑器 draft 条目是否正在被拖拽。
 *
 * 为什么需要这个标志（而非复用 suppressRebuild）：子编辑器的写回链路是
 * draft 变更 → FileBundle.register → contentVersion++，而 contentVersion 位于 **force watch**
 * 里，调用的是 scheduleRebuild(true)——force 会**绕过** suppressRebuild。若不额外拦住，
 * 拖拽期间每轮防抖写回都会触发一次全量重建，表现就是「拖一下 gizmo 场景就整个刷新」。
 *
 * 主编辑器无此问题：它拖拽时不写 FileBundle（contentVersion 不变，force 通道不点亮），
 * 且把 transform 直接写进 Three.js 对象（无需重建即跟手）。draft 条目没有可直写的场景
 * 对象（属 P1），因此拖拽期一律不重建，松手后补偿一次。
 */
let draftGizmoDragging = false;

/**
 * 「纯 bundle 变更引发的冗余重建」抑制截止时间戳。
 *
 * draft 写回只改 FileBundle（contentVersion / fingerprint），**不改 meta**——而这两者
 * 同时位于两个重建 watch（普通快照 watch + 渲染入口 force watch）里，故一次写回会触发
 * 两次重建请求。draft 条目在场景里没有对应物体（creative 模式不加载 NPC），拖拽/写回
 * 都不会产生任何可见变化，这两次重建纯属浪费（整场刷新、高斯重建闪烁）。
 */
/**
 * 上一次**真正执行重建**时的 meta 渲染快照。
 *
 * 用「与上次重建时是否一致」而非「与上次判断时是否一致」来判定「本次是否只改了 FileBundle」：
 * 两个重建 watch（普通快照 + 渲染入口 force）会因同一次写回先后触发，若在判断中更新基线，
 * 后者会把前者刚更新的基线当成「未变」而误判。以「上次重建时」为基准则两次判断结果一致，
 * 无顺序依赖。
 */
let lastRebuiltMetaJson = '';

/**
 * 本次重建是否应当跳过（v1.44.0：客观规则，取代原「时间窗口 + 调用方设窗」方案）。
 *
 * 规则：**meta 未变 且 当前编辑层是嵌套层（栈深 ≥2）** → 跳过。
 *
 * 为什么改成客观规则：原方案靠调用方在「gizmo 拖拽松手」时设 skipBundleOnlyRebuildUntil
 * 时间窗口，但**打点拾取（applyPickPosition）**、表单输入等其他 draft 写回路径不走该分支
 * → 每次打点/编辑都照样整场重建。改为「meta 是否真变更 + 层级」两个客观条件后，
 * 任何调用方的 draft 写回都被自动覆盖，无需逐个补丁。
 *
 * 为什么安全（永不误吞）：
 * - meta 真变更（主编辑器拖拽 / 属性面板编辑）→ 条件不成立 → 照常重建；
 * - 非根层子配置在 creative 预览下无消费方（NPC 模块未装配、永不加载）→ 重建本无可见变化。
 *
 * ⚠️ 若将来 creative 模式改为装配并加载 NPC（或非根层配置出现消费方），本跳过规则需放宽。
 */
function shouldSkipRebuildForNestedDraft(): boolean {
  if (getRenderMetaJson(props.value) !== lastRebuiltMetaJson) return false;
  return (props.editingConfigDepth ?? 0) > 1;
}

/**
 * 当前激活条目是否全部来自子编辑器草稿（draft）。
 *
 * draft 条目没有对应场景对象，gizmo 拖拽不会（也无法）直接移动任何物体——预览只能靠
 * 「draft 写回 FileBundle → 渲染快照变化 → 重建」生效。因此：
 * - **激活期间不得抑制 rebuild**，否则子编辑器里的数值编辑/拖拽结果都不会上屏；
 * - 仅在**拖拽过程中**临时抑制（避免重建销毁正在拖拽的 TransformControls），
 *   拖拽结束立即解除抑制并补偿一次重建。
 */
function isDraftOnly(entries: GizmoEntry[]): boolean {
  return entries.length > 0 && entries.every((e) => e.source === 'draft');
}

/** 拖拽开始/结束：禁用/恢复 FlyCamera + 记录拖拽初始状态快照 + 互斥拖拽 */
function onGizmoDraggingChanged(inst: GizmoInstance, event: { value?: unknown }): void {
  const dragging = event.value === true;
  const sdk = sdkRef.value;

  // draft 条目：拖拽期完全阻断重建（含 force，见 draftGizmoDragging 注释），
  // 松手后也不重建 —— 判据见下方分支内注释。
  if (inst.source === 'draft') {
    if (dragging) {
      draftGizmoDragging = true;
      setSuppressRebuild(true);
    } else {
      draftGizmoDragging = false;
      setSuppressRebuild(false);
      // draft gizmo 拖拽结束：**一律不主动重建**，并抑制本次写回引发的「纯 bundle」重建。
      //
      // 两条路径都不需要重建：
      // ① draft 条目在场景里没有对应物体（creative 模式不加载 NPC）：重建不产生任何可见变化；
      // ② 改动已落进 FileBundle，退出子编辑器时 onCloseSubEditor → runPendingConfigLoad →
      //    configPendingLoad=false → watch(configPendingLoad) 会统一强制重建一次，不会丢改动。
      //
      // 反过来说：这里主动重建的收益上限是「同一次拖拽内提前看到一次刷新」，代价却是
      // 整场高斯重载 + 资源重新 fetch —— 收益与代价完全不成比例，故不做。
      // 此处无需设窗：写回引发的重建已由 shouldSkipRebuildForNestedDraft 以客观规则统一拦下
      // （同样覆盖打点拾取、表单输入等其他 draft 写回路径）。
    }
  }

  if (dragging && inst.proxy) {
    // 记录拖拽开始时 proxy 和场景物体的完整 transform 快照，
    // 用于增量应用：拖拽时只把 delta 加到场景物体原始值上，不覆盖绝对值。
    inst.dragStart = {
      proxy: {
        pos: inst.proxy.position.clone(),
        rot: inst.proxy.rotation.clone(),
        scale: inst.proxy.scale.clone(),
      },
      sceneTarget: inst.sceneTarget
        ? {
            pos: inst.sceneTarget.position.clone(),
            rot: inst.sceneTarget.rotation.clone(),
            scale: inst.sceneTarget.scale.clone(),
          }
        : null,
      metaTransform: inst.path
        ? (() => {
            const entry = activeGizmoEntries.value.find((e) => e.path === inst.path);
            return entry
              ? {
                  position: [...entry.transform.position],
                  rotation: [...entry.transform.rotation],
                  scale: [...entry.transform.scale],
                }
              : null;
          })()
        : null,
    };

    // 互斥：禁用其他所有 gizmo 实例，防止重叠时同时拖拽
    for (const other of gizmoInstances) {
      if (other !== inst) {
        other.controls.enabled = false;
      }
    }
  } else {
    inst.dragStart = null;

    // 恢复其他 gizmo 实例
    for (const other of gizmoInstances) {
      if (other !== inst) {
        other.controls.enabled = true;
      }
    }
  }

  if (!sdk) return;

  // v20260819：SDK 门面 getSceneManager()/getFlyCameraController() 已删除，
  // 改走 ECS 直读 cameraModule state.flyController
  const ctx = sdk.getContext();
  const flyCtrl = ctx
    ? ((getModule<CameraModuleState>(ctx, cameraModule)?.flyController ?? null) as {
        setEnabled: (e: boolean) => void;
        isEnabled?: () => boolean;
      } | null)
    : null;

  if (!flyCtrl) return;

  // 引用计数管理相机：第一个 gizmo 开始拖拽时保存状态并禁用，
  // 最后一个 gizmo 结束拖拽时恢复，防止多 gizmo 重叠时相机卡死。
  if (dragging) {
    if (gizmoDragCount === 0) {
      flyCameraWasEnabled = flyCtrl.isEnabled?.() ?? true;
    }
    gizmoDragCount++;
    flyCtrl.setEnabled(false);
  } else {
    gizmoDragCount = Math.max(0, gizmoDragCount - 1);
    if (gizmoDragCount === 0) {
      flyCtrl.setEnabled(flyCameraWasEnabled);
    }
  }
}

/** gizmo 拖拽中：proxyGroup 变化 → 回写 meta + 增量应用到真实场景物体 */
function onGizmoObjectChange(inst: GizmoInstance): void {
  const proxy = inst.proxy;
  if (!proxy) return;
  const mode = getGizmoModeForPath(inst.path);
  const newTransform = {
    position: [proxy.position.x, proxy.position.y, proxy.position.z] as number[],
    rotation: [
      THREE.MathUtils.radToDeg(proxy.rotation.x),
      THREE.MathUtils.radToDeg(proxy.rotation.y),
      THREE.MathUtils.radToDeg(proxy.rotation.z),
    ] as number[],
    scale: [proxy.scale.x, proxy.scale.y, proxy.scale.z] as number[],
  };

  const isInteractionZone = inst.path?.startsWith('interactionZones');
  const matchingEntry = activeGizmoEntries.value.find((e) => e.path === inst.path);
  const metaOrig = inst.dragStart?.metaTransform ?? matchingEntry?.transform ?? null;

  // resize 模式：proxy.scale → 几何参数回写（v3 shape 参数 或 v2 geometry.size）
  // interactionZones 与 audio.audioZones 统一：走 'size' channel，
  // v3 shape 由 MetaEditor onPropertyChange 识别 `shape.size` 并按 type 拆分到结构化参数。
  if (mode === 'resize') {
    const target = resolveShapeEditTarget(inst.path);
    if (target) {
      const { type: geoType } = getZoneGeometryParams(target.zoneValue);
      const newSize = proxyScaleToSize(geoType, [proxy.scale.x, proxy.scale.y, proxy.scale.z]);
      notifyGizmoChangeWithPath(target.basePath, 'size', newSize);
    }
    return;
  }

  if (mode === 'translate') {
    // interactionZones（zone 组）与 draft 条目（子编辑器草稿，无场景对象）**都必须走增量回写**：
    // 直接用 proxy.position 写的是「proxy 所在坐标系」的值，而非配置坐标系的值 ——
    //  - zone 组：proxy 代表组中心，与 meta 里存的单个 zone 值不同；
    //  - draft 条目：proxy 已按 worldOrigin 补偿（渲染坐标），直写会把渲染坐标当配置坐标存盘，
    //    表现为「拖拽后数值整体偏移一个 worldOrigin，怎么拖都对不上」。
    // delta = proxy 的位移，同一坐标系下与整体偏移无关，故对两类条目都安全。
    if ((isInteractionZone || inst.source === 'draft') && inst.dragStart && metaOrig) {
      const delta = [
        proxy.position.x - inst.dragStart.proxy.pos.x,
        proxy.position.y - inst.dragStart.proxy.pos.y,
        proxy.position.z - inst.dragStart.proxy.pos.z,
      ];
      notifyGizmoChangeWithPath(inst.path, 'position', [
        metaOrig.position[0] + delta[0],
        metaOrig.position[1] + delta[1],
        metaOrig.position[2] + delta[2],
      ]);
    } else {
      notifyGizmoChangeWithPath(inst.path, 'position', newTransform.position);
    }
  } else if (mode === 'rotate') {
    if (inst.dragStart && metaOrig) {
      const axisIndex = getActiveRotateAxisIndex(inst.controls);
      if (axisIndex === null) return;
      const startRotDeg = [
        THREE.MathUtils.radToDeg(inst.dragStart.proxy.rot.x),
        THREE.MathUtils.radToDeg(inst.dragStart.proxy.rot.y),
        THREE.MathUtils.radToDeg(inst.dragStart.proxy.rot.z),
      ];
      const delta = normalizeDeltaDeg(newTransform.rotation[axisIndex] - startRotDeg[axisIndex]);
      const reportedRot: number[] = [metaOrig.rotation[0], metaOrig.rotation[1], metaOrig.rotation[2]];
      reportedRot[axisIndex] = normalizeRotationDeg(metaOrig.rotation[axisIndex] + delta);
      notifyGizmoChangeWithPath(inst.path, 'rotation', reportedRot);
    } else {
      notifyGizmoChangeWithPath(inst.path, 'rotation', newTransform.rotation.map(normalizeRotationDeg));
    }
  } else {
    if (isInteractionZone && inst.dragStart && metaOrig) {
      const sx = inst.dragStart.proxy.scale.x !== 0 ? proxy.scale.x / inst.dragStart.proxy.scale.x : 1;
      const sy = inst.dragStart.proxy.scale.y !== 0 ? proxy.scale.y / inst.dragStart.proxy.scale.y : 1;
      const sz = inst.dragStart.proxy.scale.z !== 0 ? proxy.scale.z / inst.dragStart.proxy.scale.z : 1;
      notifyGizmoChangeWithPath(inst.path, 'scale', [
        metaOrig.scale[0] * sx,
        metaOrig.scale[1] * sy,
        metaOrig.scale[2] * sz,
      ]);
    } else {
      notifyGizmoChangeWithPath(inst.path, 'scale', newTransform.scale);
    }
  }

  // 增量应用到真实场景物体
  const sceneTarget = inst.sceneTarget;
  if (sceneTarget && inst.dragStart && inst.dragStart.sceneTarget) {
    if (mode === 'translate') {
      sceneTarget.position.set(
        inst.dragStart.sceneTarget.pos.x + (proxy.position.x - inst.dragStart.proxy.pos.x),
        inst.dragStart.sceneTarget.pos.y + (proxy.position.y - inst.dragStart.proxy.pos.y),
        inst.dragStart.sceneTarget.pos.z + (proxy.position.z - inst.dragStart.proxy.pos.z),
      );
    } else if (mode === 'rotate') {
      const axisIndex = getActiveRotateAxisIndex(inst.controls);
      if (axisIndex === null) return;
      const startRotDeg = [
        THREE.MathUtils.radToDeg(inst.dragStart.proxy.rot.x),
        THREE.MathUtils.radToDeg(inst.dragStart.proxy.rot.y),
        THREE.MathUtils.radToDeg(inst.dragStart.proxy.rot.z),
      ];
      const currentRotDeg = [
        THREE.MathUtils.radToDeg(proxy.rotation.x),
        THREE.MathUtils.radToDeg(proxy.rotation.y),
        THREE.MathUtils.radToDeg(proxy.rotation.z),
      ];
      const deltaRad = THREE.MathUtils.degToRad(normalizeDeltaDeg(currentRotDeg[axisIndex] - startRotDeg[axisIndex]));
      const nextRotation = [
        inst.dragStart.sceneTarget.rot.x,
        inst.dragStart.sceneTarget.rot.y,
        inst.dragStart.sceneTarget.rot.z,
      ];
      nextRotation[axisIndex] += deltaRad;
      sceneTarget.rotation.set(nextRotation[0], nextRotation[1], nextRotation[2]);
    } else {
      const sx = inst.dragStart.proxy.scale.x !== 0 ? proxy.scale.x / inst.dragStart.proxy.scale.x : 1;
      const sy = inst.dragStart.proxy.scale.y !== 0 ? proxy.scale.y / inst.dragStart.proxy.scale.y : 1;
      const sz = inst.dragStart.proxy.scale.z !== 0 ? proxy.scale.z / inst.dragStart.proxy.scale.z : 1;
      sceneTarget.scale.set(
        inst.dragStart.sceneTarget.scale.x * sx,
        inst.dragStart.sceneTarget.scale.y * sy,
        inst.dragStart.sceneTarget.scale.z * sz,
      );
    }
    sceneTarget.updateMatrixWorld(true);
  }

  // 统一 zone 网格运行时同步（注册表驱动）：interactionZones / audio 等 gizmo 拖拽后同步真实物体
  const zoneHit = inst.path ? parseZoneGridPath(inst.path) : null;
  if (zoneHit?.provider.syncRuntime) {
    zoneHit.provider.syncRuntime(inst.path!, zoneHit.parsed, zoneHit.provider.getZone(zoneHit.parsed));
  }
}

/**
 * 读取当前场景的世界原点（rebase 偏移）。
 *
 * 场景内可见内容位于**渲染坐标** = 配置坐标 − worldOrigin；而配置类数据
 * （draft / meta 里的 transform.position）存的是**配置坐标**。
 *
 * draft 条目没有场景对象可绑定（creative 模式不加载 NPC），proxy 只能靠自己摆位——
 * 不做该补偿会让坐标轴落到视野外（实测距相机 2347 单位，表现为「开关亮了但看不到坐标轴」）。
 */
function getSceneWorldOrigin(): THREE.Vector3 | null {
  const ctx = sdkRef.value?.getContext();
  if (!ctx) return null;
  try {
    return getWorldOrigin(ctx);
  } catch {
    // SDK 未就绪 / 模块缺失 → 视为无偏移（等价于旧行为）
    return null;
  }
}

/** worldOrigin 订阅的取消句柄（SDK 实例变化时重新订阅，卸载时取消） */
let unsubscribeWorldOrigin: (() => void) | null = null;

/**
 * worldOrigin（rebase）变化 → 重算 draft 条目 gizmo 位置（v1.45.0）。
 *
 * 为什么需要：draft 条目的 proxy 位置 = **配置坐标 − worldOrigin**。rebase 后 worldOrigin
 * 变化（日志「🔄 已偏移 N 个碰撞体」即此），若不重算，坐标轴会停在旧渲染坐标上
 * → 表现为「一偏移碰撞体，gizmo 坐标轴就飘远」。
 *
 * 为什么 meta 条目不受影响：它们有 sceneTarget 绑定，proxy 与场景内容同一基准（都经场景
 * 统一偏移），本来就不做 worldOrigin 补偿，故无须跟随。
 *
 * 拖拽中的实例跳过：其 proxy 位置已被用户手势偏离基值，重算会打断拖拽。
 */
function applyRebaseToDraftGizmo(): void {
  const worldOrigin = getSceneWorldOrigin();
  for (const inst of gizmoInstances) {
    if (!isConfigFrameEntry(inst.source, inst.path) || inst.controls.dragging) continue;
    const entry = activeGizmoEntries.value.find((e) => e.path === inst.path);
    if (!entry) continue;
    inst.proxy.position.set(
      entry.transform.position[0] - (worldOrigin?.x ?? 0),
      entry.transform.position[1] - (worldOrigin?.y ?? 0),
      entry.transform.position[2] - (worldOrigin?.z ?? 0),
    );
  }
}

/**
 * 该 transform 条目是否处于「配置坐标系」（需做 worldOrigin 补偿）—— v1.46.0 收口。
 *
 * SDK 对不同字段的 rebase 口径**不同**（已逐处核实）：
 * - **配置帧**（入 world 时 SDK 做 `− worldOrigin`）：
 *   · `initial.player` —— character-spawn.ts:87-89 `defaultSpawnPoint.clone().sub(worldOrigin)`；
 *   · 子编辑器 draft 条目（npc `list[].transform`）—— npc-load-from-config 同款 `.sub(worldOrigin)`。
 * - **渲染帧**（SDK 直接落配置值、不 rebase）：
 *   · interactionZones —— thirdparty-controller.ts:401 `zoneMesh.position.set(...geoPos)`；
 *   · audio zones —— 编辑器自建预览网格，无 rebase。
 *
 * 原实现按 `source === 'draft'` 一刀切，导致两头都错：对 `initial.player` 漏补偿、
 * 对 zone 误补偿。四处补偿点统一复用本函数按字段判定。
 */
function isConfigFrameEntry(source: GizmoSource | undefined, path: string | undefined): boolean {
  if (source === 'draft') return true;
  if (!path) return false;
  return path === 'initial.player' || path.startsWith('initial.player.');
}

/** 订阅 / 重新订阅 worldOrigin 变化（SDK 实例变化时先取消旧订阅，避免回调堆积） */
function subscribeRebaseForDraftGizmo(sdk: ViewerSDK | null): void {
  unsubscribeWorldOrigin?.();
  unsubscribeWorldOrigin = null;
  if (!sdk) return;
  const ctx = sdk.getContext();
  if (!ctx) return;
  try {
    unsubscribeWorldOrigin = subscribeWorldOrigin(ctx, () => applyRebaseToDraftGizmo());
  } catch {
    // SDK 未就绪 / world-origin 模块缺失 → 不做跟随（等价于旧行为）
  }
}

/**
 * 为单个 GizmoEntry 创建一个独立的 TransformControls 实例。
 * 每个实例有自己的 proxy / helper / 事件绑定，通过闭包捕获 inst 引用。
 */
function createGizmoInstance(
  scene: THREE.Scene,
  camera: THREE.PerspectiveCamera,
  domElement: HTMLCanvasElement,
  entry: GizmoEntry,
): GizmoInstance {
  const path = entry.path;
  const transform = entry.transform;
  // 子编辑器草稿路径（source='draft'）与 3D 场景对象没有对应关系，必须跳过
  // findSceneObjectByPath —— 它末尾有「返回场景首个 Group/Mesh」的兜底分支，
  // 草稿短路径一旦落进去就会把 gizmo 绑到毫不相干的物体上，拖拽静默移动错误对象。
  // 因此 draft 来源直接退化为「仅改数值」：proxy 独立于场景，拖拽只回写 draft。
  const isDraft = entry.source === 'draft';

  // 找到场景中对应的真实物体（用于即时视觉反馈）
  const sceneTarget = isDraft ? null : findSceneObjectByPath(scene, path);
  if (!sceneTarget && !isDraft) {
    console.warn(`[Gizmo] 未找到路径 "${path}" 对应的场景物体，仅改数值不应用视觉`);
  }

  // 创建不可见 proxyGroup 作为拖拽锚点
  const proxy = new THREE.Group();
  proxy.visible = false;

  // draft 来源不参与 zone 组合逻辑（其值取自 draft 而非 meta，且无对应场景对象）
  const isInteractionZoneModel = !isDraft && path.startsWith('interactionZones') && path.includes('.model.transform');
  if (isInteractionZoneModel && sceneTarget) {
    // 已存在 zone：从场景物体复制组合后的绝对位置
    proxy.position.copy(sceneTarget.position);
    proxy.rotation.copy(sceneTarget.rotation);
    proxy.scale.copy(sceneTarget.scale);
  } else if (isInteractionZoneModel) {
    // 新增 zone：场景物体尚未创建（suppressRebuild 阻止了 rebuild），
    // 从 meta 计算组合位置初始化 proxy，避免用相对偏移导致拖拽时漂移
    const parsed = parseInteractionZonePath(path);
    if (parsed) {
      const zone = getInteractionZoneValue(parsed.zoneKey);
      const geometryTransform = getTransformWithDefaults(zone?.geometry?.transform);
      const modelTransform = getTransformWithDefaults(zone?.model?.transform);
      const composed = composeInteractionZoneModelTransform(geometryTransform, modelTransform);
      proxy.position.set(composed.position[0], composed.position[1], composed.position[2]);
      proxy.rotation.set(
        THREE.MathUtils.degToRad(composed.rotation[0]),
        THREE.MathUtils.degToRad(composed.rotation[1]),
        THREE.MathUtils.degToRad(composed.rotation[2]),
      );
      proxy.scale.set(composed.scale[0], composed.scale[1], composed.scale[2]);
    }
  } else if (transform) {
    // draft 条目（无场景对象）：transform.position 是**配置坐标**，而场景内容经 rebase 显示在
    // **渲染坐标**（配置坐标 − worldOrigin）。不补偿会令坐标轴落到视野外。
    // 只需补偿初始位置 —— onGizmoObjectChange 用「proxy 当前 − 拖拽起点」的**差值**回写，
    // 差值在同一坐标系下与整体偏移无关，故写回 draft 的值仍是正确的配置坐标。
    const worldOrigin = isConfigFrameEntry(entry.source, path) ? getSceneWorldOrigin() : null;
    proxy.position.set(
      transform.position[0] - (worldOrigin?.x ?? 0),
      transform.position[1] - (worldOrigin?.y ?? 0),
      transform.position[2] - (worldOrigin?.z ?? 0),
    );
    proxy.rotation.set(
      THREE.MathUtils.degToRad(transform.rotation[0]),
      THREE.MathUtils.degToRad(transform.rotation[1]),
      THREE.MathUtils.degToRad(transform.rotation[2]),
    );
    proxy.scale.set(transform.scale[0], transform.scale[1], transform.scale[2]);
  }

  scene.add(proxy);

  const controls = new TransformControls(camera, domElement);
  controls.setSize(0.75);
  const mode = getGizmoModeForPath(path);
  // resize 模式底层用 scale 模式，但限制轴可见性
  if (mode === 'resize') {
    controls.setMode('scale');
  } else {
    controls.setMode(mode);
  }

  const inst: GizmoInstance = {
    controls,
    proxy,
    helper: controls.getHelper(),
    path,
    source: entry.source ?? 'meta',
    sceneTarget,
    dragStart: null,
  };

  // 通过闭包绑定事件，让 handler 能拿到对应的 inst
  controls.addEventListener('dragging-changed', (event) => onGizmoDraggingChanged(inst, event));
  controls.addEventListener('objectChange', () => onGizmoObjectChange(inst));
  controls.attach(proxy);

  // resize 模式：创建后立即应用 — geometry 实例设轴可见性，非 geometry 实例隐藏
  if (mode === 'resize') {
    if (isResizeCapablePath(path)) {
      applyResizeMode(inst);
    } else {
      inst.helper.visible = false;
      inst.controls.enabled = false;
    }
  }

  // three r169+：TransformControls 不再继承 Object3D，需把 helper 加入 scene
  scene.add(inst.helper);

  return inst;
}

/** 创建并 attach TransformControls（支持多 gizmo） */
function setupGizmo(): void {
  const sdk = sdkRef.value;
  if (!sdk) return;

  const { scene, camera, domElement } = getSdkThreeContext(sdk);
  if (!scene || !camera || !domElement) return;

  // 清理旧的 gizmo（如有）
  teardownGizmo();

  gizmoScene = scene;

  // 设置激活标志，防止紧随其后的 gizmoSyncTarget watcher 用 meta 值覆盖真实物体
  gizmoActivating = true;
  nextTick(() => {
    gizmoActivating = false;
  });

  // zone 网格同步（统一注册表驱动）：interactionZones / audio 等只显示激活的 zone
  syncZoneGridsByActiveEntries();

  // 为每个激活条目创建独立的 gizmo 实例
  const entries = activeGizmoEntries.value;
  for (const entry of entries) {
    const inst = createGizmoInstance(scene, camera, domElement, entry);
    gizmoInstances.push(inst);
  }

  // v1.27.0：创建后存在未绑定实例（sceneTarget=null）→ 自调度重试绑定。
  // 真正的根因：延迟激活路径（MetaEditor waitForSdkRefresh → activateGizmoMulti）
  // 走的是 watch(activeGizmoEntries) → setupGizmo，**不经** restoreGizmoAfterSceneReady——
  // v1.26 在 restore 内部加的自调度重试从未被启动。此时 SDK zone 网格由 zone-module
  // fire-and-forget attachInteractionZones 异步创建（晚于 onSceneReady），gizmo 坐标轴
  // 已创建但场景无网格可绑。此处统一兜底：未绑定 → 调度重试，绑定成功 → 取消。
  // v1.28.0：player 空 CharacterGroup（sceneTarget=null 属"仅数值编辑"常态）不计入重试。
  // v1.29.0：draft 来源（子编辑器草稿路径）同理恒为「仅数值编辑」，也不计入重试，
  // 否则会因永远找不到场景对象而无限空转重试。
  if (
    gizmoInstances.some(
      (inst) => inst.sceneTarget == null && inst.source !== 'draft' && !inst.path.startsWith('initial.player'),
    )
  ) {
    scheduleGizmoRestoreRetry();
  } else {
    cancelGizmoRestoreRetry();
  }
}

/** 销毁所有 TransformControls 实例 */
function teardownGizmo(): void {
  for (const inst of gizmoInstances) {
    inst.controls.detach();
    inst.controls.dispose();
    if (gizmoScene) {
      gizmoScene.remove(inst.helper);
      gizmoScene.remove(inst.proxy);
    }
  }
  gizmoInstances = [];
  gizmoScene = null;
  gizmoDragCount = 0;
  // 拖拽中场景被销毁（如关闭子编辑器）时 dragging-changed=false 可能永不回调，
  // 必须在此复位，否则后续所有重建会被永久拦住。
  draftGizmoDragging = false;
}

/**
 * SDK 重建后恢复 gizmo 实例（幂等）。
 *
 * 场景：导入新 singleSceneConfigPath / regionReplaceConfigPath 等触发 rebuildSdk →
 * teardownSdk → teardownGizmo 销毁全部 gizmo 实例，但 activeGizmoEntries 仍保持激活
 * （左侧开关仍显示开启）。若不在新 scene 就绪后重新 setupGizmo，会出现：
 * ① 3D 场景中 gizmo 控件消失；② 数值面板修改 transform 时 watch(gizmoSyncTarget)
 *    因 gizmoInstances 为空直接 return → 画面不更新（只有"关闭再开启"才能恢复）。
 *
 * 触发时机（双保险）：
 * - onSceneReady（权威时机：SplatMesh / zone 对象均已加载，sceneTarget 可找到）
 * - watch(sdkRef) 轮询兜底（onSceneReady 因消息错过 / late-subscribe 边界未触发时）
 *
 * 就绪判据：scene/camera/domElement 可用 且 所有激活路径的 sceneTarget 均可找到。
 * 后者保证 setupGizmo 创建实例时 findSceneObjectByPath 不返回 null ——
 * 否则 gizmo 虽显示但拖拽/数值修改无法作用到真实物体（只回写 meta）。
 *
 * ⚠️ v1.3.0 修正：findSceneObjectByPath 的 gaussian 分支在第 4 步有"返回 scene 第一个
 * Group/Mesh"的兜底，导致场景尚未加载完成（SplatMesh 未 add）时轮询就误判为"就绪"，
 * gizmo 绑定到错误的兜底 Group（pos=0,0,0）→ 显示但拖拽/改值无效。
 * 因此对 gaussian 路径，就绪判据必须是 **命中 isGaussianNode 的真实 SplatMesh**。
 *
 * @returns true 表示已恢复（或无需恢复），false 表示场景未就绪（调用方应重试）
 */
function restoreGizmoAfterSceneReady(): boolean {
  if (activeGizmoEntries.value.length === 0) return true;
  const sdk = sdkRef.value;
  if (!sdk) {
    scheduleGizmoRestoreRetry();
    return false;
  }
  const { scene, camera, domElement } = getSdkThreeContext(sdk);
  if (!scene || !camera || !domElement) {
    scheduleGizmoRestoreRetry();
    return false;
  }
  // 就绪判据：所有激活路径的 sceneTarget 均可找到（audio zone 预览网格编辑器自建，视为就绪）
  for (const entry of activeGizmoEntries.value) {
    // audio zone 预览网格由编辑器自身创建（不依赖 SDK 场景加载），直接视为就绪
    if (entry.path.startsWith('audio.audioZones')) continue;
    // draft 来源（子编辑器草稿路径）本就无对应场景对象，恒为「仅数值编辑」→ 视为就绪，
    // 否则会阻塞恢复并触发无意义的自调度重试。
    if (entry.source === 'draft') continue;
    const target = findSceneObjectByPath(scene, entry.path);
    const isPlayerEntry = entry.path.startsWith('initial.player');
    if (!target && !isPlayerEntry) {
      scheduleGizmoRestoreRetry();
      return false;
    }
    // gaussian 路径：必须命中真实 SplatMesh（isGaussianNode），兜底 Group 不算就绪
    // （gaussian 前缀与 player 前缀互斥，此处 target 运行时必非 null，`target &&` 仅为类型收窄）
    if (entry.path.startsWith('gaussianSplatting') && target && !isGaussianNode(target)) {
      scheduleGizmoRestoreRetry();
      return false;
    }
    // player 路径（v1.28.0）：creative 预览模式角色模型不加载，CharacterGroup 为空是
    // **常态**而非"未就绪"——findSceneObjectByPath 返回 null。此时 gizmo 仍应恢复并
    // 退化为"仅改数值"（sceneTarget=null：createGizmoInstance / onGizmoObjectChange
    // 均已空值保护，proxy 独立于场景根组，不会复现 v1.7.0 的"拖动平移整个场景"），
    // 与手动"关闭再开启"的 setupGizmo 行为一致。故 player 找不到目标不阻塞恢复，
    // 也不参与下方"待绑定"重试（见 hasPendingUnbound / setupGizmo 尾部判断）。
  }
  // 已恢复且无"未绑定"实例（sceneTarget 为 null）→ 幂等返回。
  // v1.25.0：若 gizmoScene 存在但存在未绑定实例（自动激活早于网格就绪——
  // MetaEditor 延迟激活的 waitForSdkRefresh 有 2s 兜底，大场景 loadScene 可能更慢，
  // 返回时 zone 网格尚未创建 → createGizmoInstance sceneTarget=null → 仅改数值不应用视觉），
  // 而此刻 sceneTarget 已可找到 → 重新 setup 绑定真实物体（等价"关闭再打开"）。
  // v1.28.0：player 空 CharacterGroup 属"仅数值编辑"常态，不计入待绑定。
  // v1.29.0：draft 来源（子编辑器草稿路径）无对应场景对象，同样不计入待绑定。
  const hasPendingUnbound = gizmoInstances.some(
    (inst) => inst.sceneTarget == null && inst.source !== 'draft' && !inst.path.startsWith('initial.player'),
  );
  if (gizmoScene && !hasPendingUnbound) {
    cancelGizmoRestoreRetry();
    return true;
  }
  setupGizmo();
  for (const entry of activeGizmoEntries.value) {
    setInteractionZoneGeometryVisible(entry.path, true);
  }
  // draft 条目不自建场景对象 → 不能抑制 rebuild，否则子编辑器的编辑结果不上屏
  setSuppressRebuild(!isDraftOnly(activeGizmoEntries.value));
  // v1.26.0：setup 后仍可能存在未绑定实例（网格晚到）→ 继续自调度重试
  // v1.28.0：player 空 CharacterGroup（仅数值编辑）不计入重试，避免空转
  // v1.29.0：draft 来源（子编辑器草稿路径）同理不计入重试
  if (
    gizmoInstances.some(
      (inst) => inst.sceneTarget == null && inst.source !== 'draft' && !inst.path.startsWith('initial.player'),
    )
  ) {
    scheduleGizmoRestoreRetry();
  } else {
    cancelGizmoRestoreRetry();
  }
  return true;
}

/**
 * v1.26.0：自调度重试 restoreGizmoAfterSceneReady。
 *
 * 触发场景见 gizmoRestoreRetryTimer 注释：延迟激活 gizmo 时 zone 网格可能晚于激活就绪
 * （zone-module.init fire-and-forget attachInteractionZones + 800ms 兜底延时），
 * 且 watch(sdkRef) 轮询兜底在 deactivateGizmo 清空 entries 时提前 return。故 restore
 * 内部在未就绪时自行安排重试，直到全部 sceneTarget 可找到、gizmo 失活或达到次数上限。
 */
function scheduleGizmoRestoreRetry(): void {
  if (gizmoRestoreRetryTimer != null) return;
  if (gizmoRestoreRetryAttempts >= GIZMO_RESTORE_MAX_ATTEMPTS) return;
  gizmoRestoreRetryAttempts++;
  gizmoRestoreRetryTimer = window.setTimeout(() => {
    gizmoRestoreRetryTimer = null;
    // gizmo 可能已失活（用户中途关闭）→ 不再重试
    if (activeGizmoEntries.value.length === 0) {
      gizmoRestoreRetryAttempts = 0;
      return;
    }
    restoreGizmoAfterSceneReady();
  }, 300);
}

function cancelGizmoRestoreRetry(): void {
  if (gizmoRestoreRetryTimer != null) {
    window.clearTimeout(gizmoRestoreRetryTimer);
    gizmoRestoreRetryTimer = null;
  }
  gizmoRestoreRetryAttempts = 0;
}

// 监听 gizmo 激活/关闭（通过 activeGizmoEntries 数组变化驱动）
// 每次 toggleGizmoEntry 都会替换数组引用触发此 watch，
// 需要 diff 出新增/移除的路径，增量创建/销毁对应 gizmo 实例。
watch(activeGizmoEntries, (newEntries, oldEntries) => {
  const oldPaths = new Set((oldEntries ?? []).map((e) => e.path));
  const newPaths = new Set((newEntries ?? []).map((e) => e.path));

  // 全部关闭 → teardown
  if (newEntries.length === 0) {
    // 隐藏旧的 zone 网格可视化（统一注册表驱动）
    for (const oldPath of oldPaths) {
      setInteractionZoneGeometryVisible(oldPath, false);
    }
    // 移除全部 zone 网格（编辑器自建网格，gizmo 关闭即隐藏）
    for (const provider of zoneGridProviders) {
      provider.removeAll();
    }
    cancelGizmoRestoreRetry();
    teardownGizmo();
    setSuppressRebuild(false);
    return;
  }

  // 首次激活（old 为空）→ 全量 setup
  if (oldEntries.length === 0) {
    setupGizmo();
    // 只显示激活路径对应的 geometry 可视化框
    for (const entry of newEntries) {
      setInteractionZoneGeometryVisible(entry.path, true);
    }
    // draft 条目不自建场景对象 → 不抑制 rebuild（详见 isDraftOnly 注释）
    setSuppressRebuild(!isDraftOnly(newEntries));
    return;
  }

  // 增量更新：找出新增和移除的路径
  const added = newEntries.filter((e) => !oldPaths.has(e.path));
  const removed = (oldEntries ?? []).filter((e) => !newPaths.has(e.path));

  // 隐藏已移除路径的 geometry 可视化
  for (const r of removed) {
    setInteractionZoneGeometryVisible(r.path, false);
  }

  // 如果有新增或移除，需要重建 gizmo 实例（因为 TransformControls 需要逐个创建）
  if (added.length > 0 || removed.length > 0) {
    setupGizmo();
    // 显示所有当前激活路径的 geometry 可视化
    for (const entry of newEntries) {
      setInteractionZoneGeometryVisible(entry.path, true);
    }
    // draft 条目不自建场景对象 → 不抑制 rebuild（详见 isDraftOnly 注释）
    setSuppressRebuild(!isDraftOnly(newEntries));
  }
});

// 监听 gizmoModeVersion：某个路径的模式被切换后，为所有实例按各自路径读取模式并应用。
// 每个实例独立 — 切换 A 的模式不会影响 B。
watch(gizmoModeVersion, () => {
  for (const inst of gizmoInstances) {
    const mode = getGizmoModeForPath(inst.path);
    if (mode === 'resize') {
      if (isResizeCapablePath(inst.path)) {
        // geometry 实例：底层用 scale 模式 + 轴可见性限制
        inst.helper.visible = true;
        inst.controls.enabled = true;
        inst.controls.setMode('scale');
        applyResizeMode(inst);
      } else {
        // 非 geometry 实例：resize 不适用，隐藏操纵杆
        inst.helper.visible = false;
        inst.controls.enabled = false;
      }
    } else {
      // 非 resize 模式：恢复全部实例可见 + 全部轴可见
      inst.helper.visible = true;
      inst.controls.enabled = true;
      inst.controls.showX = true;
      inst.controls.showY = true;
      inst.controls.showZ = true;
      inst.controls.setMode(mode);
      // 从 resize 切回其他模式时，proxy.scale 需重置为 transform.scale
      // （resize 模式下 proxy.scale 代表 geometry.size，语义不同）
      if (inst.path?.startsWith('interactionZones')) {
        const entry = activeGizmoEntries.value.find((e) => e.path === inst.path);
        if (entry && !inst.controls.dragging) {
          inst.proxy.scale.set(entry.transform.scale[0], entry.transform.scale[1], entry.transform.scale[2]);
        }
      }
    }
  }
});

// 监听 gizmoModesVersion：geometry.type 切换后重新应用 resize 模式的轴可见性 + proxy.scale
// 仅对当前模式为 resize 的 geometry 实例生效
watch(gizmoModesVersion, () => {
  for (const inst of gizmoInstances) {
    if (!isResizeCapablePath(inst.path)) continue;
    if (getGizmoModeForPath(inst.path) !== 'resize') continue;
    applyResizeMode(inst);
  }
});

// 监听 gizmoSyncTarget：用户在数值面板修改 transform 值时，
// MetaEditor 调用 syncGizmoTransform 通知此处，同步对应 gizmo 实例的 proxy + 真实物体。
// 通过 path 匹配找到对应的 gizmo 实例（支持多 gizmo 同时激活）。
watch(gizmoSyncTarget, (target) => {
  if (!target || gizmoInstances.length === 0) return;
  const inst = gizmoInstances.find((i) => i.path === target.path);
  if (!inst) return;
  // 仅在非拖拽中时同步，避免拖拽时被回写值覆盖
  if (inst.controls.dragging) return;
  // 激活时跳过：proxy 已从 entry transform 初始化，无需重复同步
  if (gizmoActivating) return;
  const t = target.transform;
  // draft 条目：proxy 以「渲染坐标」摆放（已按 worldOrigin 补偿），数值同步必须同基准，
  // 否则在面板里改一次数值，坐标轴就会跳到视野外（与拖拽回写同一个坐标系问题）。
  const syncWorldOrigin = isConfigFrameEntry(inst.source, inst.path) ? getSceneWorldOrigin() : null;
  inst.proxy.position.set(
    t.position[0] - (syncWorldOrigin?.x ?? 0),
    t.position[1] - (syncWorldOrigin?.y ?? 0),
    t.position[2] - (syncWorldOrigin?.z ?? 0),
  );
  inst.proxy.rotation.set(
    THREE.MathUtils.degToRad(t.rotation[0]),
    THREE.MathUtils.degToRad(t.rotation[1]),
    THREE.MathUtils.degToRad(t.rotation[2]),
  );
  // resize 模式下 proxy.scale 承载的是「几何尺寸」（shape.size 经 sizeToProxyScale 映射），
  // 不是 transform.scale——手动修改 transform 后若直接用 t.scale 覆盖，
  // 再拖 resize 轴时 proxyScaleToSize 会从被污染的 scale 反算尺寸，导致几何尺寸重置。
  // 因此 resize 模式实例的 scale 必须从 meta 尺寸重新应用，transform.scale 仅在非 resize 模式生效。
  if (getGizmoModeForPath(inst.path) === 'resize' && isResizeCapablePath(inst.path)) {
    applyResizeMode(inst);
  } else {
    inst.proxy.scale.set(t.scale[0], t.scale[1], t.scale[2]);
  }

  // 数值面板编辑时也同步当前 gizmo 绑定对象（zone 网格走注册表）
  const zoneHit = inst.path ? parseZoneGridPath(inst.path) : null;
  if (zoneHit?.provider.syncRuntime) {
    zoneHit.provider.syncRuntime(inst.path!, zoneHit.parsed, zoneHit.provider.getZone(zoneHit.parsed));
    return;
  }
  if (inst.sceneTarget) {
    inst.sceneTarget.position.copy(inst.proxy.position);
    inst.sceneTarget.rotation.copy(inst.proxy.rotation);
    inst.sceneTarget.scale.copy(inst.proxy.scale);
    inst.sceneTarget.updateMatrixWorld(true);
  }
});

// 监听 geometrySyncTarget：用户在数值面板修改 geometry.size 或 geometry.type 时，
// 就地重建对应 zone 的几何体网格（不触发 SDK 整体重建）。
// 仅在 gizmo 激活（suppressRebuild=true）时有实际意义；
// 非激活状态下 SDK 会正常重建，此 watch 的 rebuildInteractionZoneGeometry 是 no-op（gizmoScene 为 null）。
watch(geometrySyncTarget, (target) => {
  if (!target) return;
  rebuildInteractionZoneGeometry(target.path);
  // 几何体重建后触发 gizmoModesVersion watch 重新应用 resize 模式：
  // 从 meta 读取最新 geometry.type，为 resize 模式实例同步 proxy.scale 和 showX/Y/Z。
  gizmoModesVersion.value++;
});

/**
 * 监听 flyToTarget：TransformControl "飞到此处" 按钮触发后，
 * 将摄像机从当前位置 tween 到目标 transform 的 position。
 *
 * 实现：手动 lerp position + quaternion，持续 ~800ms，
 * 期间临时禁用 FlyCameraController 避免冲突。
 */
let flyTweenRAF = 0;
/** 飞行动画进行中标志，防止重复触发 + 组件卸载时恢复 FlyCamera */
let flyTweenActive = false;
let flyTweenFlyCtrl: {
  setEnabled: (e: boolean) => void;
  setCameraState: (p: THREE.Vector3, q: THREE.Quaternion) => void;
  isEnabled?: () => boolean;
} | null = null;
let flyTweenWasEnabled = true;

function finishFlyTween(cam: THREE.PerspectiveCamera | null, restoreFlyCamera: boolean): void {
  flyTweenActive = false;
  flyTweenRAF = 0;
  if (restoreFlyCamera && flyTweenFlyCtrl && cam) {
    flyTweenFlyCtrl.setCameraState(cam.position.clone(), cam.quaternion.clone());
    flyTweenFlyCtrl.setEnabled(flyTweenWasEnabled);
  } else if (flyTweenFlyCtrl) {
    // 没有 camera 也至少恢复 enabled 状态
    flyTweenFlyCtrl.setEnabled(flyTweenWasEnabled);
  }
  flyTweenFlyCtrl = null;
}

watch(flyToTarget, (target) => {
  if (!target) return;

  const sdk = sdkRef.value;
  if (!sdk) return;

  const { camera: _camera } = getSdkThreeContext(sdk);
  if (!_camera) return;
  const cam = _camera; // 非 null 常量，闭包内类型收窄

  // v20260819：SDK 门面 getSceneManager()/getFlyCameraController() 已删除，
  // 改走 ECS 直读 cameraModule state.flyController
  const ctx = sdk.getContext();
  const _flyCtrl = ctx
    ? ((getModule<CameraModuleState>(ctx, cameraModule)?.flyController ?? null) as {
        setEnabled: (e: boolean) => void;
        setCameraState: (p: THREE.Vector3, q: THREE.Quaternion) => void;
        isEnabled?: () => boolean;
      } | null)
    : null;

  if (!_flyCtrl) return;
  const flyCtrl = _flyCtrl; // 非 null 常量

  // 如果上一次飞行动画还没完成，先完成它（恢复 FlyCamera 到当前位置），
  // 再开始新动画。避免 cancelAnimationFrame 后 setEnabled(wasEnabled) 丢失。
  if (flyTweenActive) {
    cancelAnimationFrame(flyTweenRAF);
    finishFlyTween(cam, true);
  }

  // 记录 FlyCamera 原始状态（仅在非飞行中时记录，避免覆盖）
  flyTweenWasEnabled = flyCtrl.isEnabled?.() ?? true;
  flyTweenFlyCtrl = flyCtrl;
  flyCtrl.setEnabled(false);
  flyTweenActive = true;

  const startPos = cam.position.clone();
  // 「飞到此处」的入参取自 transform 字段值，其坐标系**按字段而定**（见 isConfigFrameEntry）：
  // - 配置帧（draft / initial.player）→ 需 − worldOrigin 才落到渲染坐标（否则飞到场景外）；
  // - 渲染帧（interactionZones / audio zones）→ 值本身已是渲染坐标，再减会偏移一个 worldOrigin。
  // 子编辑器打开时所有字段都来自 draft（配置帧），故以 editingConfigDepth 兜底判定。
  const flyIsConfigFrame = (props.editingConfigDepth ?? 0) > 0 || isConfigFrameEntry(undefined, target.path);
  const worldOrigin = flyIsConfigFrame ? getSceneWorldOrigin() : null;
  const endPos = new THREE.Vector3(
    target.position[0] - (worldOrigin?.x ?? 0),
    target.position[1] - (worldOrigin?.y ?? 0),
    target.position[2] - (worldOrigin?.z ?? 0),
  );

  // 固定偏移：相机停在目标上方斜后方，朝向目标点。
  // 用固定方向而非相机当前朝向，确保多次点击同一目标结果一致。
  const adjustedEnd = endPos.clone().add(new THREE.Vector3(0, 3, 5));

  const startQuat = cam.quaternion.clone();
  const endQuat = new THREE.Quaternion();
  const lookMatrix = new THREE.Matrix4().lookAt(adjustedEnd, endPos, new THREE.Vector3(0, 1, 0));
  endQuat.setFromRotationMatrix(lookMatrix);

  const duration = 800;
  const startTime = performance.now();

  function tick(): void {
    // 如果动画已被取消（flyTweenActive=false），不再执行
    if (!flyTweenActive) return;

    const elapsed = performance.now() - startTime;
    const t = Math.min(elapsed / duration, 1);
    // ease-in-out
    const eased = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;

    cam.position.lerpVectors(startPos, adjustedEnd, eased);
    cam.quaternion.slerpQuaternions(startQuat, endQuat, eased);

    if (t < 1) {
      flyTweenRAF = requestAnimationFrame(tick);
    } else {
      // 完成：恢复 FlyCamera 并同步状态
      finishFlyTween(cam, true);
    }
  }

  flyTweenRAF = requestAnimationFrame(tick);
});

// SDK 就绪后注册到 bridge，供 SchemaRenderer 感知
watch(sdkRef, (sdk) => {
  registerSdk(sdk);
  // v1.45.0：订阅 worldOrigin(rebase) 变化 → draft 条目 gizmo 位置跟随偏移
  subscribeRebaseForDraftGizmo(sdk);
  // v1.2.0：SDK 重建兜底恢复 gizmo —— onSceneReady 可能因消息错过 / late-subscribe
  // 边界未触发（用户实际观测到"导入后 gizmo 不显示，关闭再开启才生效"），
  // 此处轮询等待场景就绪后恢复，最长 5s（25 次 × 200ms）。
  if (!sdk || activeGizmoEntries.value.length === 0) return;
  let attempts = 0;
  const timer = window.setInterval(() => {
    attempts++;
    const done = restoreGizmoAfterSceneReady();
    if (done || attempts >= 25 || activeGizmoEntries.value.length === 0) {
      window.clearInterval(timer);
    }
  }, 200);
});

// ==================== 打点拾取（Point Picker） ====================

/** 拾取模式激活的 transform 路径（点谁回填谁） */
let pickPath = '';
/** 拾取模式绑定的 DOM 事件句柄（用于解绑） */
let pickClickHandler: ((e: MouseEvent) => void) | null = null;
let pickKeyHandler: ((e: KeyboardEvent) => void) | null = null;
let pickDomElement: HTMLCanvasElement | null = null;
/** 拾取期间临时禁用的 FlyCamera 状态 */
let pickFlyCtrl: { setEnabled: (e: boolean) => void; isEnabled?: () => boolean } | null = null;
let pickFlyWasEnabled = true;

/**
 * 解绑拾取监听 + 恢复十字光标为默认 + 恢复 FlyCamera（幂等）。
 * 进入/退出拾取模式、SDK teardown 时统一调用。
 */
function teardownPickListeners(): void {
  if (pickDomElement && pickClickHandler) {
    pickDomElement.removeEventListener('click', pickClickHandler);
    pickDomElement.style.cursor = '';
  }
  if (pickKeyHandler) {
    window.removeEventListener('keydown', pickKeyHandler);
  }
  pickClickHandler = null;
  pickKeyHandler = null;
  pickDomElement = null;
  if (pickFlyCtrl) {
    pickFlyCtrl.setEnabled(pickFlyWasEnabled);
    pickFlyCtrl = null;
  }
}

/** 进入/退出拾取模式：绑定/解绑点击与 ESC 监听、十字光标、临时禁用 FlyCamera */
function setPickMode(active: boolean, path: string): void {
  // 幂等解绑旧监听 + 恢复相机
  teardownPickListeners();

  pickPath = active ? path : '';

  if (!active) {
    // 退出拾取模式
    return;
  }

  const { domElement } = getSdkThreeContext(sdkRef.value);
  if (!domElement) return;
  pickDomElement = domElement;
  domElement.style.cursor = 'crosshair';

  // 临时禁用 FlyCamera，避免点击拾取时同时旋转视角
  const ctx = sdkRef.value?.getContext();
  const flyCtrl = ctx
    ? ((getModule<CameraModuleState>(ctx, cameraModule)?.flyController ?? null) as {
        setEnabled: (e: boolean) => void;
        isEnabled?: () => boolean;
      } | null)
    : null;
  if (flyCtrl) {
    pickFlyCtrl = flyCtrl;
    pickFlyWasEnabled = flyCtrl.isEnabled?.() ?? true;
    flyCtrl.setEnabled(false);
  }

  pickClickHandler = (e: MouseEvent) => handlePickClick(e);
  pickKeyHandler = (e: KeyboardEvent) => {
    if (e.key === 'Escape') cancelPick();
  };
  domElement.addEventListener('click', pickClickHandler);
  window.addEventListener('keydown', pickKeyHandler);
}

/**
 * 拾取命中后：就地移动场景物体到命中点，并返回「正确的回填值」。
 *
 * 为什么不能直接把命中点世界坐标写回 meta：
 * - interactionZones 的 model.transform 是「相对 geometry 的偏移」，不是世界坐标，
 *   直接回填世界坐标会让模型飞到错误位置（compose 双倍偏移）；
 * - geometry/shape.transform 则是权威世界坐标，可直接回填。
 * 因此按 target 区分：
 *   - model：把世界坐标换算成「相对偏移增量」并 apply composed 到模型网格；
 *   - geometry/shape：直接设 geometry 碰撞框 position 并同步 helper box；
 *   - 非 zone（gaussian/player 等）：直接设真实场景物体 position。
 *
 * @returns 供 meta 回填的坐标（model 返回相对偏移、其余返回世界坐标，四舍五入到 2 位）
 */
function applyPickAndGetRefill(path: string, point: THREE.Vector3): [number, number, number] {
  const round = (v: number): number => Math.round(v * 100) / 100;
  const scene = getSdkThreeContext(sdkRef.value).scene;

  const parsed = path ? parseInteractionZonePath(path) : null;

  /**
   * 同步指定 path 的 gizmo proxy（箭头锚点）到目标位置。
   * 打点只移动场景真实物体，若不同步 proxy，gizmo 箭头会停留在旧位置
   * （看起来"箭头消失/脱节"，需重拖 shape 或重开开关才恢复）。
   */
  const syncGizmoProxy = (
    worldPos: [number, number, number],
    worldRotDeg?: [number, number, number],
    worldScale?: [number, number, number],
  ): void => {
    const inst = gizmoInstances.find((i) => i.path === path);
    if (!inst || inst.controls.dragging) return;
    inst.proxy.position.set(worldPos[0], worldPos[1], worldPos[2]);
    if (worldRotDeg) {
      inst.proxy.rotation.set(
        THREE.MathUtils.degToRad(worldRotDeg[0]),
        THREE.MathUtils.degToRad(worldRotDeg[1]),
        THREE.MathUtils.degToRad(worldRotDeg[2]),
      );
    }
    if (worldScale) {
      inst.proxy.scale.set(worldScale[0], worldScale[1], worldScale[2]);
    }
    inst.controls.update(0);
  };

  // interactionZones 的 model：相对偏移 → 换算成世界位移增量
  if (parsed && parsed.target === 'model') {
    const zone = getInteractionZoneValue(parsed.zoneKey);
    const geometryTransform = getTransformWithDefaults(
      zone?.shape?.type ? zone?.shape?.transform : (zone?.geometry?.transform ?? zone?.geometryTransform),
    );
    const modelTransform = getTransformWithDefaults(zone?.model?.transform ?? zone?.modelTransform ?? zone?.transform);
    const current = composeInteractionZoneModelTransform(geometryTransform, modelTransform);
    const newModelPos = [
      modelTransform.position[0] + (point.x - current.position[0]),
      modelTransform.position[1] + (point.y - current.position[1]),
      modelTransform.position[2] + (point.z - current.position[2]),
    ];
    const newModelTransform = {
      position: newModelPos,
      rotation: modelTransform.rotation,
      scale: modelTransform.scale,
    };
    const composed = composeInteractionZoneModelTransform(geometryTransform, newModelTransform);
    if (scene) {
      const modelObject = findInteractionZoneObject(scene, parsed.zoneName, 'model');
      if (modelObject) {
        applyTransformToObject(modelObject, composed);
      }
    }
    // 同步 model gizmo proxy 到组合后的绝对位置（否则箭头脱节消失）
    syncGizmoProxy(
      [composed.position[0], composed.position[1], composed.position[2]],
      [composed.rotation[0], composed.rotation[1], composed.rotation[2]],
      [composed.scale[0], composed.scale[1], composed.scale[2]],
    );
    return [round(newModelPos[0]), round(newModelPos[1]), round(newModelPos[2])];
  }

  if (scene) {
    if (parsed) {
      // zone 的 geometry/shape：移动碰撞框 + 同步 helper box
      const geometryObject = findInteractionZoneObject(scene, parsed.zoneName, 'geometry');
      if (geometryObject) {
        geometryObject.position.set(point.x, point.y, point.z);
        geometryObject.updateMatrixWorld(true);
        const helper = findInteractionZoneObject(scene, parsed.zoneName, 'geometryHelper') as
          (THREE.Object3D & { box?: THREE.Box3 }) | null;
        if (helper?.box) {
          helper.box.setFromObject(geometryObject);
          helper.updateMatrixWorld(true);
        }
      }
      // 同步 geometry/shape gizmo proxy 到命中点（世界坐标）
      syncGizmoProxy([point.x, point.y, point.z]);
    } else {
      // 非 zone（gaussian/player 等）：移动真实场景物体
      const sceneTarget = findSceneObjectByPath(scene, path);
      if (sceneTarget) {
        sceneTarget.position.set(point.x, point.y, point.z);
        sceneTarget.updateMatrixWorld(true);
      }
      // 非 zone 的 gizmo proxy 位置 = 真实物体位置（世界坐标）
      syncGizmoProxy([point.x, point.y, point.z]);
    }
  }
  return [round(point.x), round(point.y), round(point.z)];
}

/**
 * 拾取点击处理：屏幕坐标 → NDC → setFromCamera 取射线 →
 * viewer-sdk raycast 命中碰撞体 → 生成箭头 + 移动场景物体 + 回传坐标 → 退出拾取模式。
 */
function handlePickClick(e: MouseEvent): void {
  const sdk = sdkRef.value;
  if (!sdk) return;
  const { camera, domElement } = getSdkThreeContext(sdk);
  if (!camera || !domElement) return;

  // 屏幕坐标 → NDC
  const rect = domElement.getBoundingClientRect();
  const ndc = new THREE.Vector2(
    ((e.clientX - rect.left) / rect.width) * 2 - 1,
    -((e.clientY - rect.top) / rect.height) * 2 + 1,
  );

  const raycaster = new THREE.Raycaster();
  raycaster.setFromCamera(ndc, camera);
  const origin = raycaster.ray.origin.clone();
  const direction = raycaster.ray.direction.clone();

  // 物理射线命中碰撞体（physics 在 creative 态运行；碰撞体不在 three.js scene 图里）
  const ctx = sdk.getContext();
  if (!ctx) return;
  const hit = raycast(ctx, origin, direction, 1000);

  // 防御 1：未命中（物理世界未就绪 / 场景无碰撞体 / 射线未打到任何刚体）
  if (!hit) {
    pushToast({
      type: 'warn',
      message: '未命中碰撞体：请确认场景已加载碰撞体，或换个位置点击',
      duration: 3000,
    });
    // 保持拾取模式，便于用户重试
    return;
  }

  // 防御 2：命中距离字段兼容取值，但必须是有限且 > 0 的有效距离。
  // RAPIER castRay 正常命中 toi 恒 > 0；若为 0/NaN/Infinity（起点恰在碰撞体内部
  // 或版本字段缺失），命中点会坍缩到相机位置，属异常值，直接忽略避免污染 meta。
  const hitAny = hit as unknown as { timeOfImpact?: number; toi?: number };
  const toi = hitAny.timeOfImpact ?? hitAny.toi ?? 0;
  if (!Number.isFinite(toi) || toi <= 0) {
    pushToast({ type: 'warn', message: '命中结果异常，已忽略（请重试）', duration: 3000 });
    return;
  }
  const point = origin.clone().addScaledVector(direction, toi);

  // 防御 3：命中点三轴必须是有限值（NaN 坐标会污染 meta 导致渲染异常）
  if (!Number.isFinite(point.x) || !Number.isFinite(point.y) || !Number.isFinite(point.z)) {
    pushToast({ type: 'warn', message: '命中坐标异常，已忽略（请重试）', duration: 3000 });
    return;
  }

  // 就地移动场景物体 + 计算正确回填值
  const pos = applyPickAndGetRefill(pickPath, point);
  // pos 是**场景(渲染)坐标**：meta 与场景 1:1，故 meta 回填直接用它；
  // 而子编辑器 draft（NPC spawn config 等）存的是**配置坐标**（SDK 消费时 − worldOrigin 转场景坐标），
  // 额外提供 +worldOrigin 的版本，避免子编辑器内打点后数值整体偏移一个 worldOrigin（表现为「从 0 开始」）。
  const pickWorldOrigin = getSceneWorldOrigin();
  // 再次 round：pos 已是 2 位，但 worldOrigin 是全精度（如 -2146.320068359375），
  // 相加会重新长出长小数 —— 复用拖拽回写的同一 round，保证两条路径精度一致。
  const [configX, configY, configZ] = roundGizmoValue([
    pos[0] + (pickWorldOrigin?.x ?? 0),
    pos[1] + (pickWorldOrigin?.y ?? 0),
    pos[2] + (pickWorldOrigin?.z ?? 0),
  ]);
  const configPos: [number, number, number] = [configX, configY, configZ];
  setPickResult(pickPath, pos, configPos);

  // 完成一次拾取后自动退出
  cancelPick();
}

/** 监听 pickRequest：进入/退出拾取模式 */
watch(pickRequest, (req) => {
  if (!req) return;
  setPickMode(req.active, req.path);
});

/**
 * meta 变更 → 重建 SDK。
 *
 * 用 debounce 避免用户连续编辑（拖滑块、改 vec3）时频繁重建 SDK；
 * SDK 重建涉及 fetch、解析、Three.js 资源销毁/创建，开销大。
 */
let rebuildTimer: number | null = null;
const REBUILD_DEBOUNCE_MS = 400;

/**
 * 本轮待执行重建的来源标签集合（仅用于诊断：重建发生时打印，便于定位「谁触发了这次刷新」）。
 * 用集合而非单变量：同一次防抖窗口内可能有多个调用点请求，单变量会被后写覆盖先写。
 */
const pendingRebuildTriggers = new Set<string>();

function scheduleRebuild(force = false, trigger = 'unknown'): void {
  // 注：触发来源用集合累积而非单变量——同一次防抖窗口内可能被多个调用点请求，
  // 早期实现用单变量会被「后写覆盖先写」，导致诊断日志指向错误的来源。
  // 目录型配置内部资源补读挂起（v1.24.0）：属性面板上传 regionReplaceConfigPath /
  // npcs.configFile 后，MetaEditor 引导授权补读 config 内部引用。挂起期间跳过一切重建
  // （含 force）——否则资源未登记时改写保留相对路径，SDK 拼出无效 blob URL 报
  // ERR_FILE_NOT_FOUND；补读完成由 watch(configPendingLoad) 强制重建一次。
  if (props.configPendingLoad) return;
  // 子编辑器 draft 拖拽中：一律不重建（**含 force**）。
  // draft 写回必然改变 contentVersion，而 contentVersion 在 force watch 里 → force 会绕过
  // 下方 suppressRebuild 判断 → 拖拽期间场景反复全量刷新。
  // 松手后也不重建（见 onGizmoDraggingChanged 的 draft 分支注释）。
  // 注意此判断必须放在 force 判断之前。
  if (draftGizmoDragging) return;
  // gizmo 拖拽中抑制 rebuild：直接应用 transform 到场景物体，重建会销毁场景和 gizmo。
  // force=true 时跳过抑制：渲染入口字段（singleSceneConfigPath / regionReplaceConfigPath /
  // gaussianComponentType）变更必须全量重建，否则选中含 transform 的 widget（会自动激活
  // gizmo 并把 suppressRebuild 置 true）后"新建 + 上传文件"会被静默拦截、场景永不刷新。
  if (!force && suppressRebuild.value) return;
  pendingRebuildTriggers.add(`${trigger}${force ? '(force)' : ''}`);
  if (rebuildTimer != null) window.clearTimeout(rebuildTimer);
  rebuildTimer = window.setTimeout(() => {
    rebuildTimer = null;
    // timer 触发前 suppressRebuild 可能被 gizmo 激活设为 true（Vue watch 调度顺序：
    // getRenderRelevantSnapshot 的 watch 可能先于 activeGizmoEntries 的 watch 执行），
    // 需再次检查避免在 gizmo 已激活后仍触发场景重建。
    if (props.configPendingLoad) return;
    // timer 触发时拖拽可能已开始 → 同样拦住（含 force），避免重建打断手势
    if (draftGizmoDragging) return;
    if (!force && suppressRebuild.value) return;
    // 诊断日志：重建开销大，打印来源便于定位「到底是谁触发了这次场景刷新」
    const triggers = [...pendingRebuildTriggers].join(' + ');
    pendingRebuildTriggers.clear();
    // eslint-disable-next-line no-console
    console.log(`[PreviewPanel] 开始重建 SDK（force=${force}, 触发来源=${triggers || '未记录'}）`);
    // 记录本次重建时的 meta 快照：后续 shouldSkipRebuildForNestedDraft 以它为「纯 bundle 变更」基线
    lastRebuiltMetaJson = getRenderMetaJson(props.value);
    void rebuildSdk(props.value);
  }, REBUILD_DEBOUNCE_MS);
}

/**
 * 提取 meta 中"真正影响渲染"的子树快照，用于 watch 对比。
 *
 * 为什么不能 deep watch 整个 meta：
 * - MetaEditor 在切换选中 widget 时会调用 `materializeDefaults`，把 schema 声明但
 *   meta 缺失的默认字段写回（"显示即数据"契约）。这会让 meta 引用变化但**渲染相关
 *   字段并未真正变更**，若直接 deep watch 整个 meta 就会触发无谓的 SDK 重建
 *   （表现：点击 gaussianSplatting 等 widget 时场景偶发重新加载）。
 * - SDK 创造模式只关心：高斯泼溅入口路径 / GS 后端选项 / collision / lighting。
 *   其它字段（如 player、camera、debugger、interactive 等）不会反映到 SDK 渲染上。
 *
 * 实现：把上述子树**结构化**序列化（JSON.stringify 是稳定的，因为 Vue 响应代理
 * 在序列化时会拿到原值；属性顺序由 JSON 引擎决定，对同一对象多次取值顺序一致）。
 *
 * **同时纳入 FileBundle 指纹**：用户授权目录加载素材后，meta 里的字段值（仍是相对路径
 * 字符串）并不会变；但 FileBundle 从空 → 有内容，这种"渲染所需资源可用性"变化必须
 * 触发重建，否则会卡在"导入后看到空场景，必须点 widget 才出图"的诡异状态。
 * 把 fingerprint 拼到快照尾部即可让 watch 自动建立对 FileBundle 的依赖。
 */
function getRenderMetaJson(meta: any): string {
  const subset =
    meta && typeof meta === 'object'
      ? {
          gaussianSplatting: meta.gaussianSplatting ?? null,
          collision: meta.collision ?? null,
          lighting: meta.lighting ?? null,
          rendererScale: meta.rendererScale ?? null,
          meterScale: meta.meterScale ?? null,
          interactionZones: meta.interactionZones ?? null,
          interaction: meta.interaction ?? null,
        }
      : {};
  try {
    return JSON.stringify(subset);
  } catch {
    return '';
  }
}

function getRenderRelevantSnapshot(meta: any): string {
  const metaJson = getRenderMetaJson(meta);
  // 注意：必须在响应式上下文中调用 fingerprint()，让 Vue 的依赖追踪记录"watch
  // 依赖于 FileBundle 内部 store 的 keys"
  const bundleFingerprint = FileBundle.fingerprint();
  // v1.31.0：纳入 contentVersion——子编辑器「编辑即生效」覆盖同 key 写回时 fingerprint
  // 不变（只看 key 列表），必须依赖内容版本号才能感知内容更新并触发重建。
  const contentVersion = FileBundle.contentVersionValue();
  return `${metaJson}#${bundleFingerprint}#${contentVersion}`;
}

watch(
  () => getRenderRelevantSnapshot(props.value),
  (next, prev) => {
    if (next === prev) return;
    if (shouldSkipRebuildForNestedDraft()) return;
    if (isEditingUnconsumedConfig()) return;
    scheduleRebuild(false, 'meta-渲染快照变更');
  },
);

// audio.audioZones 变化：同步编辑器侧的 audio zone 预览网格。
// 不触发 SDK 重建（audio 不在渲染快照里，SDK 运行时自行读取）。
// 仅在 gizmo 激活期间更新（与 interactionZones 网格显隐行为一致：未选中控件/gizmo 关闭时不显示）。
watch(
  () => JSON.stringify(props.value?.audio?.audioZones ?? null),
  () => {
    if (!gizmoScene || activeGizmoEntries.value.length === 0) return;
    syncZoneGridsByActiveEntries();
  },
);

// 渲染入口字段（场景路径 / 后端 / 资源 URL）变更必须强制重建，绕过 gizmo 激活期的 suppressRebuild。
//
// 背景：选中含 transform 的 widget（如 gaussianSplatting / collision legacy / interactionZones）
// 会经 watch(selectedWidgetId) 自动激活 gizmo，进而把 suppressRebuild 置 true。此后"上传
// 本地文件"触发的普通 scheduleRebuild 会被 suppressRebuild 拦截，场景永不刷新。
// 这些入口字段与 gizmo 无关、必须全量重建，故单独 watch 并以 force=true 触发。
//
// v1.19.0：纳入 collision.url —— collision legacy 变体含 transform，选中即激活 gizmo，
// 用户在其 url 字段上传本地 GLB 时被 suppressRebuild 静默拦截（无日志、场景不变）。
// v1.20.0：纳入 interactionZones / interaction 的模型 URL（v2 zone.model.url、v3
// triangleMesh zone.shape.mesh.url）——选中 interactionZones 会批量激活所有 zone 的
// gizmo，模型 URL 变更同被拦截。
//
// 提取 interactionZones（数组/Record 双形态）或单个 zone 中所有"资源加载型" URL。
// 注意：只提取 model/mesh 资源 URL，不序列化整个子树——transform 等编辑字段仍走
// 普通 watch（gizmo 激活时就地应用，不应触发 SDK 重建）。
function collectZoneModelUrls(zones: unknown): string[] {
  const list = Array.isArray(zones)
    ? zones
    : zones && typeof zones === 'object'
      ? Object.values(zones as Record<string, unknown>)
      : [];
  const urls: string[] = [];
  for (const zone of list) {
    const z = zone as any;
    if (z?.model && typeof z.model === 'object' && typeof z.model.url === 'string') urls.push(z.model.url);
    if (z?.shape?.type === 'triangleMesh' && typeof z.shape.mesh?.url === 'string') urls.push(z.shape.mesh.url);
  }
  return urls;
}

watch(
  () => {
    const gs = props.value?.gaussianSplatting;
    const collision = props.value?.collision;
    const zoneUrls = collectZoneModelUrls(props.value?.interactionZones);
    const singleInteractionUrls = collectZoneModelUrls(props.value?.interaction ? [props.value.interaction] : []);
    // v1.23.0：纳入 FileBundle.fingerprint——属性面板上传 regionReplaceConfigPath / npcs.configFile
    // 后，MetaEditor 引导授权补读 config 内部资源（FileBundle 填充），此变更必须强制重建
    // （普通 watch 在 gizmo 激活时会被 suppressRebuild 拦截，导致本地地块预览不刷新）。
    const bundleFingerprint = FileBundle.fingerprint();
    const contentVersion = FileBundle.contentVersionValue();
    return (
      `${gs?.gaussianComponentType ?? ''}\u0000${gs?.singleSceneConfigPath ?? ''}\u0000${gs?.regionReplaceConfigPath ?? ''}` +
      `\u0000${collision?.url ?? ''}\u0000${zoneUrls.join('|')}\u0000${singleInteractionUrls.join('|')}\u0000${bundleFingerprint}\u0000${contentVersion}`
    );
  },
  (next, prev) => {
    if (next === prev) return;
    if (shouldSkipRebuildForNestedDraft()) return;
    if (isEditingUnconsumedConfig()) return;
    scheduleRebuild(true, '渲染入口字段/FileBundle 指纹变更');
  },
);

/**
 * 当前子编辑器编辑的 config 是否「未被当前场景消费」。
 *
 * 为什么需要：draft 写回只改 FileBundle 内容（contentVersion++），而 contentVersion 无条件
 * 挂在两个重建 watch 上——触发逻辑不知道、也不判断「这个文件跟当前场景有没有关系」。
 * 当配置根本没有消费方时，重建是 100% 无收益的整场重载（高斯重载 + 资源重新 fetch）。
 *
 * 已确证的判据（fail-open：不确定一律照常重建）：
 * - npc 配置：meta 编辑器预览跑 creative 模式，SDK 的 npcManagerModule/npcSystemModule
 *   属可拔模块（sdk/index.ts v2.2.0 从必装链摘除），PreviewPanel 初始化仅
 *   extraModules:[lightModule] 未装配 NPC → NPC 永不加载、该 config 无任何消费方，
 *   与 npcs.enabled 无关（即便 enabled=true 也不加载）。
 */
function isEditingUnconsumedConfig(): boolean {
  const editing = props.editingConfigPath;
  if (!editing) return false;
  const npcs = props.value?.npcs;
  const npcConfigPaths = [npcs?.configFile, npcs?.chunkedUrl, npcs?.chunks?.chunkedUrl].filter(
    (v): v is string => typeof v === 'string' && v.length > 0,
  );
  return npcConfigPaths.includes(editing);
}

// 目录型配置内部资源补读完成（v1.24.0）：MetaEditor 引导授权补读 config 内部引用后
// 将 configPendingLoad 置 false，此处强制重建一次——挂起期间跳过的重建在此补偿，
// 且此时 FileBundle 已填充、改写可全部命中 blob。
watch(
  () => props.configPendingLoad,
  (pending) => {
    if (pending) return;
    scheduleRebuild(true, 'configPendingLoad 结束');
  },
);

// ==================== 生命周期 ====================

onMounted(() => {
  // 首次挂载也走 schedule（保证 containerRef 已挂载）
  scheduleRebuild(false, 'PreviewPanel 挂载');
});

onBeforeUnmount(() => {
  if (rebuildTimer != null) window.clearTimeout(rebuildTimer);
  // 取消 worldOrigin 订阅：SDK 的 subscribers 是模块级数组，不取消会在多次挂载/重建后堆积回调
  unsubscribeWorldOrigin?.();
  unsubscribeWorldOrigin = null;
  // 清理飞行动画：取消 RAF 并恢复 FlyCamera（避免卸载后相机被永久锁定）
  if (flyTweenActive) {
    cancelAnimationFrame(flyTweenRAF);
    const { camera: _cam } = getSdkThreeContext(sdkRef.value);
    finishFlyTween(_cam, true);
  }
  deactivateGizmo();
  teardownGizmo();
  void teardownSdk();
});
</script>

